var CW={"INTJ": {"sweet": ["Knows the answer before you ask", "Plans six months ahead", "The one to call in a crisis", "Spots wasted effort instantly", "Unshakable inner compass"], "mild": ["Brain meeting always in session", "Optimizes every walking route", "Freezes at surprise invites"], "spicy": ["Wonders what small talk is for", "Mentally leaves bad meetings", "Wins arguments with cold logic", "Itches to fix your plans"], "love": ["Slow and careful to fall", "Plans the future without asking", "Affection in secret code", "Fiercely loyal once decided", "Backs your dreams for real", "Keeps every promise", "Quietly preps anniversaries", "Texts only the key points", "Scouts the date route first", "Confesses after running the odds", "Goes silent around a crush", "Shuts down fights with logic", "Treats exes as old data", "Will never admit jealousy"]}, "INTP": {"sweet": ["Endlessly curious mind", "Catches flaws nobody sees", "Ignores titles, sees people", "Explains things clearly and deeply", "Surprises everyone with wild ideas"], "mild": ["Googling random stuff at 3am", "Replies late, lost in thought", "Messy room, perfect mental map"], "spicy": ["Ears close on boring topics", "Deadline mode starts at midnight", "Won't budge if the logic holds", "Can't let a sloppy explanation go"], "love": ["Struggles to put feelings in words", "Remembers everything you said", "Late-night calls over fancy dates", "Guards alone time fiercely", "Accepts your quirks completely", "Seriously solves your problems", "Loves freely, never clingy", "Leaves you on read for 3 days", "Analyzes why they like you", "Dates at bookstores or museums", "Keeps missing the moment to confess", "Accidentally forgets anniversaries", "Explains who's right mid-fight", "Sweet talk in a robot voice"]}, "ENTJ": {"sweet": ["Decisive and reassuring", "Leads the team to victory", "Maps the road to any goal", "Always follows through", "Leads by example"], "mild": ["Schedules weekends by the minute", "Makes trip itineraries unasked", "Ends up running every party"], "spicy": ["Just get to the point", "Truly cannot wait", "Fastest critic in the room", "Schedules rest like a task"], "love": ["All in for the one they love", "Perfectionist date planner", "Terrible at being babied", "Brings up the future early", "Fiercely protective of their partner", "Genuinely proud of your growth", "Fixes your problems on the spot", "Confesses first, with confidence", "Books anniversary dinners early", "Texts are strictly business", "Runs the show even on dates", "Rushes fights to a conclusion", "Sets KPIs for the relationship", "Breakups? Clean and swift"]}, "ENTP": {"sweet": ["Ideas multiply in conversation", "Makes any room more fun", "Breaks the ice in one line", "First to try new things", "Loves a good debate with anyone"], "mild": ["Derails every conversation", "New hobby every three months", "Always testing a new app"], "spicy": ["Argues just for sport", "Great starter, weak finisher", "Hunts for loopholes", "Promises on a whim, regrets later"], "love": ["Enjoys the chase a little too much", "Bored by boring partners", "Teases the one they like", "Never a dull moment together", "Every date feels brand new", "Makes your stories even better", "Genius at cheering you up", "Roasting you is their love language", "Reply speed depends on mood", "Even confessions sound like jokes", "Changes date plans on a whim", "Treats fights as fun debates", "Still friends with every ex", "Cools off the moment you chase"]}, "INFJ": {"sweet": ["Reads you without a word", "Quietly holds your true feelings", "A silent source of support", "Rare friend for deep talks", "Always chooses kind words"], "mild": ["Replays the day before bed", "Drained by crowds", "Surprisingly detailed journals"], "spicy": ["The sudden door slam", "Smiles, sees right through you", "Impossibly high standards for self", "Quietly drifts from toxic people"], "love": ["Forever searching for the one", "Overreads their partner's mind", "Slow to open up", "Loves deeply and for long", "Notices your tiniest changes", "Your emotional anchor", "Every word feels warm", "Rewrites texts again and again", "The listener on dates", "Senses a breakup first", "Remembers every special date", "Sees through lies instantly", "Sky-high standards for the one", "Vanishes when pushed too far"]}, "INFP": {"sweet": ["Feels others' pain deeply", "True to themselves", "Kindness at just the right warmth", "Eyes light up about passions", "Notices little joys"], "mild": ["Inner story always playing", "Plays one song a hundred times", "Best weekend: never leaving home"], "spicy": ["Motivation switch gone missing", "An hour drafting one text", "Whole day lost to daydreams", "Remembers every hurt for years"], "love": ["Daydreams run ahead of the romance", "One word makes or breaks the day", "Devoted to the one they love", "Would confess in a love letter", "Embraces all of you", "Wishes your happiness above all", "Cherishes tiny anniversaries", "Overthinks every reply for hours", "Freezes up around a crush", "Every love song is about you", "Gets wistful at goodbyes", "Romanticizes their exes", "Cries alone after a fight", "Reality never matches the dream"]}, "ENFJ": {"sweet": ["Sees the best in everyone", "Brings everyone together", "First to check on someone sad", "Leaves you feeling energized", "Truly happy for others' growth"], "mild": ["Official birthday surprise planner", "Always reading the group's mood", "Advice calls that last for hours"], "spicy": ["Can't stop helping", "Calendar full from never saying no", "Exhausted by own expectations", "Puts everyone else first, always"], "love": ["Gives too much for a partner", "Never forgets an anniversary", "Your dream's biggest fan", "Holds back to avoid being disliked", "Praises you more than anyone", "Always in tune with your feelings", "Gets close with your family", "Goes all out on surprises", "Always replies so politely", "First to apologize after fights", "Your date wishes come first", "Tries to coach their partner", "Still gives their ex advice", "Expects love back in equal measure"]}, "ENFP": {"sweet": ["Lights up any room", "Makes friends in seconds", "Believes in your potential", "Spreads excitement everywhere", "Goes all in on passions"], "mild": ["Phone notes full of ideas", "Plans a trip on a whim", "Conversation jumps everywhere"], "spicy": ["Quick to heat, quick to cool", "Overbooked into burnout", "Leaves cleanup to future self", "Wild emotional rollercoaster"], "love": ["Falls in love in a heartbeat", "Crushes are painfully obvious", "Panics when texts stop", "Makes every day fun", "Every day's a festival together", "Says how they feel, full volume", "Dreams your dreams with you", "Triple-texts, then some", "Confesses on pure impulse", "Date plans decided same day", "Tells friends all about you", "Jealousy is written all over them", "Bounces to the next love fast", "Bolts when things get clingy"]}, "ISTJ": {"sweet": ["Always keeps promises", "Steady, tireless effort", "Flawless with every task", "Trusted more than anyone", "Spots tiny mistakes instantly"], "mild": ["Up at the same time daily", "Reads the whole manual", "Same place, same order"], "spicy": ["Plan changes ruin the mood", "No precedent, no action", "Shuts people down with facts", "World-class inflexibility"], "love": ["Anniversaries marked on the calendar", "Shows love through actions", "Scouts date spots in advance", "Too shy for sweet talk", "Always on time, without fail", "Remembers your birthday wishes", "Zero chance of cheating", "Sets the date budget ahead", "Short, to-the-point texts", "Confesses by the book", "Sticks to the same restaurant", "Secretly hates surprises", "Wins fights with cold facts", "Logistics over romance"]}, "ISFJ": {"sweet": ["Master of quiet thoughtfulness", "Remembers everyone's favorites", "Calming to be around", "Quietly supports everyone", "Kindly notices small changes"], "mild": ["Always carries band-aids", "Can't say no to a favor", "Keeps every old letter"], "spicy": ["Real feelings kept in storage", "Bottles it up, then explodes", "Up all night overthinking", "Too polite for own good"], "love": ["Tends to give too much", "Notices you're sick first", "Jealous but never shows it", "Loyal once they fall", "Remembers all your favorites", "Drops off snacks on rough days", "Honors even tiny promises", "Overthinks replies after reading", "Works around your schedule", "Real feelings go to friends only", "Saves every anniversary photo", "Cries suddenly at the limit", "Drags up the past in fights", "Takes six months to move on"]}, "ESTJ": {"sweet": ["The reliable organizer", "The reliable planning machine", "Unmatched sense of duty", "Genius at planning", "Always steps up in a crisis"], "mild": ["Always ends up planning the party", "Lives for the to-do list", "Can't stand people running late"], "spicy": ["Bulldozes with being right", "Can't hide the urge to boss", "Annoyed by inefficiency", "Catchphrase: that's not normal"], "love": ["Dates with the future in mind", "Flawless date plans", "Secretly bad at being babied", "Takes the lead in love too", "Protects what they commit to", "First to show up in a crisis", "Meets the parents early", "Strict about meeting times", "Texts lead with the conclusion", "Confesses in plain words", "Runs your plans on a spreadsheet", "Fights turn into lectures", "Critiques your planning", "Efficiency over romance"]}, "ESFJ": {"sweet": ["Genius at warming up a room", "Remembers everyone's birthday", "Can't ignore someone in need", "Master connector of people", "Lifts everyone with a smile"], "mild": ["Center of every group chat", "Goes all out on host gifts", "Sends everyone the photos"], "spicy": ["Impressive gossip network", "Sulks without compliments", "Called a people-pleaser", "Caretaking gone overboard"], "love": ["All out for anniversaries", "Spoils the one they love", "Anxious over slow replies", "Cares what friends think", "Close with your whole family", "Good-morning texts every day", "Calls right away on bad days", "Celebrates monthly anniversaries", "Shows you off to friends", "Wants matching everything", "Plans birthdays a month ahead", "Left on read? Total meltdown", "Expects love in return", "Knows what their ex is up to"]}, "ISTP": {"sweet": ["Cool under any trouble", "Handy, can fix anything", "There when it matters", "Gets it done the shortest way", "Totally self-sufficient"], "mild": ["Builds without the manual", "Tunes out boring talk", "Tool collection keeps growing"], "spicy": ["Replies with just \"yeah\"", "Texts only when necessary", "Won't move unless in the mood", "Vanishes without warning"], "love": ["Runs from clingy partners", "Shows love in quiet actions", "Comfortable silence together", "Texts rarely, even in love", "Fixes broken stuff instantly", "Your go-to in a crisis", "Silently carries your bags", "Texts back with just a sticker", "Dates with zero plan", "Needs alone time, even in love", "Tends to forget anniversaries", "Ghosts heavy conversations", "Even breakups are low-key", "Says yes with just \"sure\""]}, "ISFP": {"sweet": ["Effortlessly great taste", "Kind to everyone", "Quietly there for you", "Lives by their own colors", "Sensitive to beauty"], "mild": ["Splurges on cute little things", "Lazy days at home are best", "Plans by mood"], "spicy": ["Pretends deadlines don't exist", "Quietly escapes the hard stuff", "Disappears instead of speaking up", "Moody as a cat"], "love": ["Goes quiet around a crush", "Would confess in a letter", "Waits to be asked out", "Happy just being together", "Takes on your tastes", "Speaks love through little gifts", "Your presence is enough", "Secretly fears you hate them", "Rewrites every text twice", "Loops your favorite songs", "Dates at cozy cafés", "Quietly vanishes after fights", "Hurt but never says so", "Can cool off on a whim"]}, "ESTP": {"sweet": ["Unbeatable go-getter", "Thrives under pressure", "Never boring to be around", "Acts the moment they decide", "Makes friends anywhere"], "mild": ["Leaves on a whim", "First in line at new spots", "Exaggerates the punchline"], "spicy": ["Planning skills on vacation", "Next challenge over reflection", "Gets bored at light speed", "Blurts first, regrets later"], "love": ["Makes the first move fast", "Wants thrilling dates", "Loves playing games", "Loves the chase", "Your boredom-proof date", "Rushes in when you're in trouble", "Wears their heart openly", "Gets close on the first date", "Vibes over plans", "Rather meet up than text", "Blurts out confessions", "Loses interest once they win", "Bounces back the day after fights", "Hangs out with exes casually"]}, "ESFP": {"sweet": ["Lights up the room by being there", "Master entertainer", "Up for anything, always", "Instant friends with anyone", "Expert at living in the moment"], "mild": ["Camera roll full of selfies", "Calendar always packed", "First to grab the karaoke mic"], "spicy": ["Memories over savings", "Homework panic the night before", "Bored? Straight to the phone", "Seems to listen, doesn't"], "love": ["All in once they fall", "An open book about romance", "Loves surprises", "Gets lonely, texts a lot", "Makes you laugh every time", "Says \"I like you\" daily", "Throws epic anniversaries", "Camera roll full of dates", "Brings you into the friend group", "Makes up right after fights", "Gets louder around a crush", "Lonely? Call spam incoming", "Falls hard and fast", "No budget cap on anniversaries"]}};
var KT={"ENFJ>INTJ": {"title": "Drawing up everyone's future, alone in a quiet room.", "body": "You plan for everyone alone in a quiet room, then present it on the big day with more fire than anyone. That picture suits you. Seeing ahead and laying out a path is the steady ground under both your nature and the way you've grown. You can switch between the spark you get from people and the focus you find alone, between reading feelings and deciding by logic.", "say": "\"I've already mapped out the whole flow. …Just tell me if everyone can keep up without strain.\"", "do": "You work late into the night on the team's long-term plan, then share it the next morning with a personal note for each member.", "worry": "The more efficient the idea, the more you worry it leaves someone's feelings behind, so you can't commit. Some days you want to see everyone and some days no one, and the swing throws even you off.", "karai": "Your five-year plan is flawless. Your plans for this weekend? Still blank."}, "ENFJ>INTP": {"title": "You cheer people up — and take their problem apart while you're at it.", "body": "While someone pours their heart out, you lift their spirits and somehow end up sketching a diagram of the problem. A curious kind of good listener. Trusting ideas and possibilities is the thread that runs through both sides of you. Energy from people and time lost in thought, a warm heart and a logical head, planning and going with the flow — you hold almost all of it in both hands.", "say": "\"That sounds really hard. So, why did it happen? Mind if I draw it out?\"", "do": "On the way home from hearing a friend's worries, you come up with three theories for fixing it and quietly text them the next day.", "worry": "Wanting to help people and wanting to chase your own interests pull on you equally, and you're never sure where your time should go. You can't move until your thoughts settle, yet the faces of the people waiting keep flickering in your mind.", "karai": "Words of encouragement for others come out instantly. Your own replies sit for three days."}, "ENFJ>ENTJ": {"title": "Decisive in the room, thoughtful after. The leader people lean on.", "body": "You set the goal and pull everyone forward, yet you stop and check on anyone falling behind. That kind of leader fits you well. Drawing energy from people, picturing what's ahead and moving with a plan have been consistent in you from the start. Because you can both feel each person's mood and decide with clear logic, there's always warmth inside your toughness.", "say": "\"The deadline is Friday, no wiggle room. If anyone's struggling, tell me now.\"", "do": "After cutting straight to a decision in a meeting, you send a private thank-you only to the person who seemed down.", "worry": "You made the right call, yet at night you replay it, wondering if someone got hurt. When you should be firm, one look at the other person's face and your words go soft.", "karai": "Team morale: boosted. Your own energy budget: doesn't add up."}, "ENFJ>ENTP": {"title": "Turning the idea nobody saw coming into one everyone can join.", "body": "\"What if we flip it?\" is your catchphrase. You liven up a discussion, pull out an idea no one else thought of, and then shape it so everyone can get on board. Feeling alive around people and spotting new possibilities have always been part of you. You also move freely between caring about feelings and testing logic, between planning ahead and jumping on a whim.", "say": "\"What if we looked at it backwards? …In a way nobody loses out, of course.\"", "do": "A conversation you meant as small talk sparks a new project, and you've assigned roles before it ends.", "worry": "You want to push your idea forward, but you understand how the people against it feel, and that hits the brakes. The moment you make a plan, a more interesting approach pops up and you can't sit still.", "karai": "The person who got the debate going is the first one off on a tangent."}, "ENFJ>INFJ": {"title": "Words that reach the heart, on a stage or one-on-one.", "body": "In front of a crowd you lift everyone up; one-on-one you listen deeply. You can gently put words to feelings the other person hadn't even noticed. Picturing what's ahead, caring about feelings and moving with a plan — that's your core. With the energy you get from people and the calm you find alone, you can move between lively rooms and quiet ones.", "say": "\"Let's all talk! But first, can I hear just your thoughts?\"", "do": "After hosting an event with a smile, you make a cup of tea at home and go over, one by one, what each person said to you.", "worry": "The days you've helped the most are the days you come home drained. You take others' worries so deeply to heart that your own heart gets heavy too.", "karai": "You read every subtle shift in people's hearts, but miss your own battery running low."}, "ENFJ>INFP": {"title": "Pushing others forward with all your might, waiting patiently on your own heart.", "body": "When it's for someone else, you're surprisingly quick to act. When it's for you, you can wait patiently until your heart says, \"This is it.\" That's your unexpected side. Trusting ideas and caring deeply about feelings is the part of you that never wavers. You can also draw on both energy from people and depth alone, both planning and going with the flow.", "say": "\"That's so lovely! …Let me check in with my own heart about it, too.\"", "do": "You cheer on a friend's dream and even help plan it, while your own dream stays carefully tucked in your journal.", "worry": "Wanting to meet people's hopes and wanting to stay true to your heart both matter, and you freeze when you have to choose. Even with a plan, on days your heart isn't in it you can't start, and you're hard on yourself for it.", "karai": "You push everyone else's back at full force, but yours has a little sign on it: \"Not ready yet.\""}, "ENFJ>ENFJ": {"title": "You've grown your gift for bringing out the best in people, straight and true.", "body": "When you say \"You can do it,\" you truly believe it. Believing in people, standing by their feelings and getting everyone facing the same way — what you were born with and what you've lived through have drawn this into one clear line. You shine where you can help, and where you can't see how people respond, you tend to lose steam without knowing why.", "say": "\"It's okay, you can do this. Let's do it together!\"", "do": "At a gathering full of strangers, you end up introducing everyone to each other, and by the time you leave, you've started a group chat.", "worry": "When people count on you, you take on everything, and your time for yourself quietly disappears. If the mood around you clouds over even a little, you start wondering if it's your fault.", "karai": "You wish so hard for everyone's happiness that you forget to save a slice for yourself."}, "ENFJ>ENFP": {"title": "A careful planner who still laughs at every surprise.", "body": "You'll write \"free time — decide on the spot\" right into the itinerary. A playful kind of organizer. Drawing energy from people, trusting ideas and deciding with your heart have stayed the same from birth until now. Since you can both plan ahead and flex with the moment, the world of everyone around you naturally grows bigger.", "say": "\"I put together everyone's plans for next month! …But don't you suddenly want to go to the beach that day?\"", "do": "You plan a birthday party down to the minute, then throw yourself into whatever game someone dreams up on the day.", "worry": "Wanting people to be happy, you pack the schedule, and suddenly your free time is gone. The gap between days you want order and days you want nothing decided confuses even you.", "karai": "On the \"let's just wing it\" trip, guess who did the most research? You."}, "ENFJ>ISTJ": {"title": "Quietly adding kindness to a very precise manual.", "body": "People often see you as \"the meticulous one,\" but your precision is always about not leaving anyone stuck. Seeing things through to the end is the pillar your nature and character share. Energy from people and focus alone, a feel for what's ahead and solid facts, kindness and fairness — you carry all of them.", "say": "\"Please follow these steps. I'll check in with the new folks myself.\"", "do": "You finish a flawless handover document, then add handwritten notes only where the reader might trip up.", "worry": "Wanting people to follow the rules and not wanting to blame them collide, and you rewrite your reminder again and again. You want to see people, but if you're not fully prepared, you're tired before you even meet.", "karai": "You're trying to add kindness to the manual, too."}, "ENFJ>ISFJ": {"title": "The cheerleader in front, the one who remembers everyone's tastes behind the scenes.", "body": "She doesn't like spicy food, he had a little cough yesterday — you just remember these things. Caring about feelings and moving with a plan is the part of you that stays the same. With energy from people and calm alone, a feel for possibilities and a careful eye for facts, you play both the bright cheerleader and the attentive helper.", "say": "\"You were coughing yesterday, right? I brought you some throat drops.\"", "do": "You take charge of a farewell party and pick the restaurant by recalling the guest of honor's favorite foods from years of conversations.", "worry": "Helping others never feels like a burden, yet your own plans always end up last in line. Some days you want to talk about big dreams, but you stop yourself with \"I need to be realistic.\"", "karai": "Everyone's anniversaries are in your planner. Your own birthday? Someone has to remind you."}, "ENFJ>ESTJ": {"title": "A tough boss everyone loves, because you never miss a win.", "body": "You track the numbers on the progress chart and jot down each member's small wins right next to them. People love you even when you're strict, because you truly see their effort. Drawing energy from people and moving with a set plan point the same way in both your nature and character. You use imagination and real-world follow-through, warmth and fair logic, without letting go of either.", "say": "\"Let's hit this number by the end of the month. …Your slides last week were so clear, by the way.\"", "do": "At the end of a meeting you read out the decisions, then close by naming each person's \"great play of the week.\"", "worry": "Should you speak up to someone breaking the rules, or put their feelings first? Each time, it wears you down. The more realistically you move forward, the further you feel from the dream you once had.", "karai": "You manage the team's schedule to the minute, but your own break is marked \"if there's time.\""}, "ENFJ>ESFJ": {"title": "Caring about next year's dream and today's lunch alike.", "body": "Right after pitching a big idea for next year, you ask, \"Did everyone eat lunch?\" That's why you're the center of calm at any gathering. Drawing energy from people, caring about feelings and moving with a plan has always been your core. A feel for what can't be seen yet and a respect for experience and facts each show up when needed.", "say": "\"Let's do something even bigger next year!\"", "do": "You volunteer for the neighborhood festival, pitch something new, and still pass on every trick that worked last year.", "worry": "You want everyone to be happy so badly that one unhappy face keeps your heart from resting. You're pulled both by wanting to try new things and by wanting to protect the way things work.", "karai": "By the time you've handed everyone a plate, your own food has gone cold."}, "ENFJ>ISTP": {"title": "Few words, but the one you say when it counts is full of heat.", "body": "You're a calm doer who doesn't say much and fixes problems fast. You also carry a warmth that wants people to grow and wants to cheer them on. With a side that comes alive around people and a side that works quietly alone, a heart for feelings and a head that cuts to the point, your hands move before your words, and you finish with one short, warm line.", "say": "\"It's no big deal. …But I think you can do even better.\"", "do": "You quietly fix a junior's mistake without a word, then later just say, \"You were on the right track.\"", "worry": "You want to encourage people, but saying it feels awkward, so you let your actions do the talking. You move so much for others that your own time can vanish.", "karai": "Cool face on, you're keeping a secret growth diary for your junior in your head."}, "ENFJ>ISFP": {"title": "Kind words and handmade gifts — you give both easily.", "body": "Words that lift everyone up and a small gift you chose on your own — both come naturally. Deciding with your heart is the thread that ties who you were born as to who you are. Energy from people and comfort alone, a feel for the future and a taste for beauty right in front of you, planning and following your mood — you have both of each.", "say": "\"Doesn't this flower's color look like today's sky?\"", "do": "You organize a group message card for a friend's birthday, and quietly add a little trinket you picked out yourself.", "worry": "The more you plan to meet everyone's hopes, the more your heart lags behind. You love a lively crowd, but afterward you need quiet time alone to feel like yourself again.", "karai": "You're first to notice how others feel, and last to notice you're tired."}, "ENFJ>ESTP": {"title": "Getting everyone fired up, then diving in first.", "body": "\"Call first, think later\" is your motto when it matters. You talk up everyone's dream until they're on board, then you're the first to jump in and clear the way. Drawing energy from people is the part of you that never wavers. You switch between seeing the future and grabbing what's real, kindness and clean decisions, planning and pure momentum.", "say": "\"Okay, I'm calling them before I overthink it.\"", "do": "The moment after hearing a friend's problem, you're already reaching out to someone who might solve it.", "worry": "After deciding on impulse, you look back to check whether anyone got left behind. Wanting to plan carefully and wanting to move right now fight it out, and you end up thinking on the run.", "karai": "No one thinks about people's feelings more than you, but you move so fast nobody can keep up."}, "ENFJ>ESFP": {"title": "Head cheerleader for everyone's future, and the one having the most fun today.", "body": "You truly cheer on everyone's future while making the moment in front of you wonderfully fun. Drawing energy from people and deciding with your heart have always been part of you. With both a feel for future possibilities and a love of right now, both planning ahead and enjoying whatever comes, the people near you can't help but smile.", "say": "\"Let's make all your dreams come true! …But today, let's just have a blast!\"", "do": "You throw a party to cheer on a friend's challenge, and on the day, forget about hosting and have the most fun of anyone.", "worry": "You want to protect the fun, then suddenly worry about what's ahead. You get so caught up in making people happy that your own true feelings get pushed back.", "karai": "Passionate about everyone's life plans — and looking the other way from your own wallet."}, "ENFP>INTJ": {"title": "Five seconds after an idea, you're drawing the blueprint.", "body": "You don't let an exciting idea stay a daydream. Before you know it, you've quietly drawn up the full plan. Trusting ideas and possibilities is the unchanging thread in both your nature and character. Energy from people and depth alone, heart and logic, freedom and a clear plan — you carry every one of them.", "say": "\"This is going to be amazing! So I made a three-phase plan.\"", "do": "A hobby you started on a whim turns into a solo research project, complete with your own how-to guide.", "worry": "The idea takes a second, but making it a perfect plan takes forever before you start. The gap between days you want company and days you want no one around can puzzle people.", "karai": "Five seconds after the idea, you're already counting its three flaws."}, "ENFP>INTP": {"title": "Curiosity in human form — digging deep with friends or alone.", "body": "It starts with \"Hey, isn't this interesting?\" and ends with you researching alone past midnight. Trusting ideas and staying flexible have always been your ground. You move, depending on the day, between growing ideas with others and digging into how things work alone, between a heart for feelings and a head for logic.", "say": "\"Hey, isn't this fun? …Wait, let me figure out why it's fun.\"", "do": "A question that came up while talking with friends keeps you researching alone until late at night.", "worry": "Your interests keep moving, so it's hard to feel you've finished anything. After saying something logically right, you wonder if you left the other person's feelings behind.", "karai": "So many search tabs open that you forget what you wanted to know."}, "ENFP>ENTJ": {"title": "The leader who brings both the fun and the results.", "body": "You share a dream that gets everyone excited, then right away set the roles and deadlines. That speed is what surprises people. Drawing energy from people and trusting ideas are the same in your nature and who you are now. With heart and logic, quick moves and solid plans, you turn a dream straight into a goal.", "say": "\"This would be so fun with everyone! Deadline's end of next month. Let's split the roles.\"", "do": "An idea from a coffee-break chat becomes a proposal and schedule you share the very next morning.", "worry": "The harder you push for results, the fewer happy faces you seem to see, and that gets you down. You're pulled both ways: sticking to the plan, and taking a fun detour.", "karai": "The one who said \"let's keep it fun\" is chasing the numbers hardest."}, "ENFP>ENTP": {"title": "Giving every idea a kind word and a sharp question at once.", "body": "You don't stop at ideas: you ask both \"Who'll love this?\" and \"Will it actually work?\" by yourself. Finding fun things fast and moving on the spot have always been yours. Because you can feel others' hearts and also tighten the logic, your debates are sharp but leave a kind aftertaste.", "say": "\"That's fun! But hold on, there might be a hole.\"", "do": "While helping a friend with a problem, you end up offering three ways to improve things.", "worry": "After winning an argument, you remember the other person's face and feel low. Truth or kindness — which to put first? You hesitate every time.", "karai": "The one who takes the most damage after winning the argument? Usually you."}, "ENFP>INFJ": {"title": "Friends with everyone, with a quiet conviction deep inside.", "body": "You warm up to anyone in no time, yet remember a passing comment for days. Behind the cheerfulness is a surprisingly deep gaze. Picturing possibilities and deciding with your heart is your core. You have both energy from people and calm alone, both a free spirit and a steady pull toward your goals.", "say": "\"Oh, that's lovely! Hey, what does it mean to you?\"", "do": "In the middle of a fun chat, you catch a small remark someone lets slip, and check on them gently a few days later.", "worry": "You want to act on an idea right away, but stop to ask, \"Is this right?\" You love meeting people, but after getting close, you need time alone.", "karai": "You make friends with anyone, but the door to your heart has three locks."}, "ENFP>INFP": {"title": "Growing what moves you, out loud and in quiet.", "body": "In a lively crowd you're the loudest voice, and alone you write the most delicate words. Having both is why you're so good at sharing what you feel. Trusting ideas, caring about feelings and following your heart have been part of you from the start. You move back and forth between energy from people and depth found alone.", "say": "\"Hey, hey, listen! Oh, but I can't put it into words yet. Can I write it down first?\"", "do": "Heading home after a day out with a big group, you pop in earbuds and jot down the best moments of the day.", "worry": "Your waves of wanting company and wanting solitude are big, and some days a plan you made starts to feel heavy. You love so many things, but tend to move on before they take shape.", "karai": "You say \"I'm in!\" right away, then regret it alone the night before."}, "ENFP>ENFJ": {"title": "Pulling people in on a whim, and seeing it all the way through.", "body": "A surprise you dream up gets everyone's schedules lined up the same day. You end up at the center because you don't stop at saying \"let's do it.\" Drawing energy from people, trusting ideas and deciding with your heart match in both your nature and character. You also have both the freedom to move and the drive to plan and finish.", "say": "\"This would be so fun with everyone! …Okay, I'll be the organizer.\"", "do": "A week after saying \"I want to go camping,\" you're handing everyone a packing list and job assignments.", "worry": "The more you're put in charge, the less time you have to act on a whim. Your sense of duty is strong, so even on days you're not feeling it, you hold on to every plan.", "karai": "The self-declared free spirit is, as always, the one running the group calendar."}, "ENFP>ENFP": {"title": "Official finder of fun, on yet another detour today.", "body": "You hop off at a station you've never seen and come home friends with a shop owner. Days like that suit you. Getting excited about new things, believing in people and widening your world by heart — what you were born with and what you've lived have grown it in the same direction. You shine where you're free, and somehow wilt in places full of rules and routine.", "say": "\"Wait, what's that? Sounds fun! Let's go!\"", "do": "Chatting about the neighborhood bakery's new bread somehow ends with you planning the next event with the owner.", "worry": "You love starting things, and you're hard on yourself when they don't last. You look cheerful, but sometimes a passing comment cuts you deeply.", "karai": "A hundred things on your bucket list. Three checked off."}, "ENFP>ISTJ": {"title": "So proper, and so surprisingly fun to talk to.", "body": "The report is done right on deadline, yet there's a little playful touch hiding on the last page. The sincerity to do what's decided with precision lives side by side with a curiosity that lights up at new possibilities. Focus alone and fun with others, an eye for facts and a heart for feelings, keeping plans and acting on a whim — you have all of them.", "say": "\"Let's follow the steps. By the way, I came up with something really fun lately.\"", "do": "You take the same route to work every day, but on days off you head out on a whim to towns you've never seen.", "worry": "You get everything done properly, yet when every day feels the same, something seems missing. You want to try your ideas, but \"What if it fails?\" makes you overly careful.", "karai": "Taking meeting notes with a serious face — and three new project ideas in the margins."}, "ENFP>ISFJ": {"title": "A fun idea, with a rainy-day plan attached.", "body": "When you think of a picnic, you look up a rainy-day spot too, just in case. Even with fun plans, you check \"Is everyone okay?\" before you move. Deciding with your heart is the part of you that stays the same. Energy from people and calm alone, an eye for the new and care with facts, lightness and loyalty — you have both of each.", "say": "\"Sounds fun! …Oh, but is she free that day?\"", "do": "You're tempted to pick a bold gift for a friend, but in the end you carefully choose something they'll really use.", "worry": "You want to dive into new things, but worrying about bothering others keeps you from taking the step. When asked, you say yes, and your own fun gets pushed back.", "karai": "Full of the urge for adventure — and ordering the usual, at the usual place."}, "ENFP>ESTJ": {"title": "Tight on plans, generous with play.", "body": "You set the plan and lead the way, while slipping in little detours that brighten the room. A fun kind of organizer. Drawing energy from people is your steady core. Imagination and real-world follow-through, heart and logic, freedom and sticking to the plan — you have both of each.", "say": "\"Meet at nine, nobody late! And for lunch, let's try a new place.\"", "do": "You lock down how the work gets done, then hide a little quiz in every weekly team meeting.", "worry": "The more responsibility you're given, the more you feel you're forgetting the joy of acting on a whim. After calling someone out by the rules, you can't stop wondering if they're feeling down.", "karai": "Five minutes after \"let's play it by ear,\" you're handing out step-by-step instructions."}, "ENFP>ESFJ": {"title": "Fresh ideas and careful attention, delivered together.", "body": "\"Let's do something different this year!\" is usually your line. And on the day, you're quietly making sure no one is left out. Drawing energy from people and deciding with your heart have been the same from birth until now. Your feel for new possibilities and respect for experience, your lightness and your loyalty all stay alive.", "say": "\"I'll book the seats and food. The rest is a surprise!\"", "do": "You suggest a new game at a class reunion, and later send photos and updates to those who couldn't make it.", "worry": "You want everyone to be happy so much that if a new idea gets a lukewarm reaction, you pull it right away. Adventure and the comfort of the usual both matter, and you go back and forth.", "karai": "You planned the surprise, then got nervous and checked with the guest of honor first."}, "ENFP>ISTP": {"title": "A light-footed experimenter who tries it now and fixes it calmly.", "body": "Before reading the manual, you take it apart. If it doesn't work, you calmly find the cause and fix it. Adapting flexibly to the moment is the part of you that never wavers. Energy from people and deep focus alone, a feel for possibilities and an eye for facts, a heart for feelings and a head for logic — you have both of each.", "say": "\"Eh, I'll find out once I try it.\"", "do": "When a friend mentions their bike is squeaking, you crouch down right there and fix it in five minutes.", "worry": "Your waves of wanting fun with people and wanting to work quietly alone are big, and you worry people think you're antisocial. Showing feelings through action is easier than words, so you can be misunderstood.", "karai": "You feel for people's problems, but all that comes out of your mouth is solutions."}, "ENFP>ISFP": {"title": "Loving the laughter of a crowd and the quiet of being alone.", "body": "After a big laugh with friends, you slip away to photograph a flower by the road. That's so you. Caring about feelings and following your heart is the part of you that stays the same. Energy from people and comfort alone, imagination for the unseen and a love of the colors, sounds and textures right in front of you — they all live together in you.", "say": "\"Hey, look at this view! …Actually, let's not talk. I just want to look for a while.\"", "do": "You visit a museum with friends, and on the way out go back alone to stand in front of the same painting for thirty minutes.", "worry": "Wanting to connect and wanting to keep your own pace are both strong, so turning down an invite always stings a little. You love so many things, but get stuck when asked about future goals.", "karai": "Everyone's smiling in your photos, but your camera roll is mostly sky and cats."}, "ENFP>ESTP": {"title": "Off the moment the idea hits, doing the math on the way.", "body": "The moment you hear there are no weekend plans, you've picked where to go. People think of you as \"the one who always makes something happen.\" Drawing energy from people and moving with the moment are shared by your nature and character. With imagination and a grip on reality, heart and a clean cut, you jump in and still weigh what's worth it.", "say": "\"Hey, we could go right now! That place is pricey though, let's pick another.\"", "do": "Five minutes after a friend sighs \"I'm bored,\" the two of you are in line at the new bowling alley.", "worry": "After deciding on impulse, you worry whether you left someone's feelings behind. Chasing fun, your prep for what's next always ends up last-minute.", "karai": "On days you head out \"just for a bit,\" you usually catch the last train home."}, "ENFP>ESFP": {"title": "A trip around the world and today's crepe — you mean both.", "body": "You make people laugh with dreamy stories and still savor today's meal and view. The days of the people with you get a little brighter. Drawing energy from people, caring about feelings and moving with the moment are the parts that never shake. You have both imagination for what's ahead and a love of fun right now.", "say": "\"Let's travel the world someday! …But today, let's go get that crepe!\"", "do": "Heading home after talking about the future, you get swept right into a festival you spot along the way.", "worry": "There's so much fun that money and time always run short. Because you look so cheerful, it's a little lonely when no one notices you're down.", "karai": "Your dreams for the future are huge. Tomorrow's breakfast? Still undecided."}, "INFJ>INTJ": {"title": "You write \"Who will this help?\" right into the blueprint.", "body": "When you make a plan, you put \"Will this work?\" and \"Who will this help?\" side by side on the same desk. Thinking deeply on your own and working backward from where things are headed is solid ground for you, by nature and by experience. You move easily between sensing how people feel and building things step by step, so people quietly come to rely on you.", "say": "\"The logic holds. Now it's just how they'll take it.\"", "do": "The night before a meeting, you fill a notebook with answers to every likely objection—and gentle ways to say them.", "worry": "You can see the right answer, but choosing your words takes so long that you speak up late. On days you pick efficiency, the faces of the people you left behind stay with you all night.", "karai": "You've planned five years ahead, but you still haven't replied about tomorrow's dinner."}, "INFJ>INTP": {"title": "A caring heart with a \"but why?\" that never stops.", "body": "When a friend comes to you with a problem, you take in their feelings—and somehow end up taking the whole problem apart, too. Going deep in your alone time and hunting for meaning you can't see is something that's always been yours. Warm empathy and a curiosity that digs with logic, steady planning and the freedom to rethink on the spot: you reach for whichever the moment needs.", "say": "\"That sounds so hard. …Wait, but why did it happen that way?\"", "do": "You start one quick search before bed, and three hours later you're reading a research paper from a totally different field.", "worry": "You want to help, but the thinking gets so fun that your hands stop moving. Right after you make a plan, a better way pops into your head and you want to start over.", "karai": "You can explain your life's purpose, but the laundry is still sitting in the dryer."}, "INFJ>ENTJ": {"title": "Quiet insight, turned into the force that moves a team.", "body": "You say \"Friday is the deadline, final,\" and then walk straight over to check on the person who looks tired. Seeing ahead and turning decisions into results is the part of you that never wavers. Deep thinking on your own and stepping up to lead, deciding with heart and deciding with logic—you can use all of them as your own.", "say": "\"Okay, Friday it is. By the way, Sam, are you getting any sleep?\"", "do": "You put the team's goals on one sheet, then fill the margins with what each person is best at.", "worry": "The more you take charge, the less time you have to think alone. When you need to be firm, the other person's face comes to mind, and some nights you blame yourself afterward.", "karai": "You make sure everyone gets their days off, but your own break is always \"sometime.\""}, "INFJ>ENTP": {"title": "You fire up the debate, then quietly help the loser up.", "body": "People may see you as someone sharp who loves a good argument. But you're also the one checking most carefully that nobody got talked down. Chasing ideas and possibilities stays the same for you in every setting. Quiet thinking and thinking out loud, a warm heart and a logical edge, careful plans and going with the flow—you have a wide range right at hand.", "say": "\"What if we flipped it? Oh—sorry if that came out harsh.\"", "do": "An idea for a new project comes up mid-chat, you run with it on the spot, and then you rework the plan alone at home.", "worry": "Ideas flow when you're with people, but you crash the moment you get home. Every time, the urge to act on a hunch pulls against the urge to make a plan that makes sense.", "karai": "You're unbeatable mid-conversation, but the review meeting you hold with yourself on the way home runs way too long."}, "INFJ>INFJ": {"title": "You've grown your gift for sensing the unseen, straight and true.", "body": "Somewhere in your heart, you can always see a picture of how things could be. Your nature and the character you've grown point the same way, so your quiet sense of what's deep in people and your step-by-step pull toward an ideal have grown strong without wobbling. Because you know what matters to you, you shine where it's understood—and wear out, without knowing why, where it isn't.", "say": "\"You don't have to push yourself. Whenever you want to talk, I'm here.\"", "do": "You can tell from a friend's face that they're down before they say a word, and you quietly leave their favorite snack on their desk.", "worry": "You feel other people's emotions so much that you notice your own tiredness late. Your ideals are high, so the gap with reality can leave you feeling low on your own.", "karai": "You can read everyone's heart, but you keep missing the sign that you're at your limit."}, "INFJ>INFP": {"title": "A big goal in your heart, and joy in every detour.", "body": "You start a year's plan in a beautiful new planner, and three days later it's a diary and a sketchbook. And part of you finds that funny. Recharging alone and treasuring both inspiration and people's feelings has never changed for you. You can move steadily toward a goal and also bend with how you feel that day, and what you find on the detours becomes the seed of your next goal.", "say": "\"I want to do this by next year. If I change my mind along the way, that's fine too.\"", "do": "You plan the weekend down to the hour, then rearrange it all on Saturday morning based on your mood—and still feel happy with it.", "worry": "When you can't stick to a plan, you feel like you've failed. But when the schedule gets tight, you can't breathe, so you keep searching for the right balance.", "karai": "Making the plan is the most fun part of the plan."}, "INFJ>ENFJ": {"title": "The host for everyone, then the replay crew of one on the way home.", "body": "At a gathering you keep things bright and organized, and once you're home you replay the day's conversations by yourself. An eye for possibilities, and moving forward with a plan while caring about people, is the part of you that holds steady. You can think deeply alone and also get a room moving, so even figuring out \"what next time?\" becomes something you enjoy.", "say": "\"Thank you all for coming today! Later, tell me one by one how it was.\"", "do": "After the get-together ends, you send each person a thank-you message that's different from all the others.", "worry": "You love doing things for people, but suddenly you have no time alone at all. It's hard to balance wanting to be counted on with wanting to be left alone.", "karai": "You recharge everyone's heart, but you always leave your own charger at home."}, "INFJ>ENFP": {"title": "Even with someone new, you catch the feeling behind the words.", "body": "You warm up to new people fast, and you still take in the feelings beneath what they say. That's how others see you. Treasuring inspiration and staying close to people's hearts is the steady center that never changes. Quiet depth and a bright spark in a crowd, planning ahead and acting on a whim—you move between them from day to day.", "say": "\"Wait, that's amazing! Let's do it! …Actually, give me a little time to think first.\"", "do": "You hit it off with someone you just met, trade numbers, and then replay the whole conversation alone once you get home.", "worry": "The more fun the day, the harder the tiredness hits at night. Your list of things you want to do keeps growing, and they all matter, yet they all feel half-done.", "karai": "You say \"I'm in!\" to every invite, and on the morning of, you're the one hesitating most."}, "INFJ>ISTJ": {"title": "Reliable steps, with a quiet touch of care added in.", "body": "When people say \"I feel safe leaving this to you,\" it isn't only because your work is accurate. Thinking calmly on your own and moving forward with a clear outlook is the part your nature and character share, and it doesn't budge. You sense the meaning behind things and check the facts, feel for people and decide with clear reasoning, so gentle care shows through even your most careful steps.", "say": "\"These steps are fine as they are. I'll just add a note here for the new folks.\"", "do": "You finish an exact manual, then handwrite on the last page: \"Ask me anytime if you get stuck.\"", "worry": "You often feel caught between following the rules and honoring the person in front of you. You worry about what's ahead, but without solid grounds you can't move, and your thoughts go in circles.", "karai": "You put people's feelings on the checklist too, so it gets longer every time."}, "INFJ>ISFJ": {"title": "Big ideals in your heart, small acts of care every single day.", "body": "When a friend moves, you make a schedule and show up with work gloves and drinks for everyone. Recharging alone and moving with a plan while caring about people is the part of you that has always been there. You have both the imagination to picture what lies ahead and the steadiness to trust experience and facts, and together they make your kindness grounded and real.", "say": "\"Things are going to get busy, so I'll get ready now. Here—I made you lunch.\"", "do": "The night you see the weather forecast, you line up umbrellas and spare socks for the whole family by the door.", "worry": "Picturing what might go wrong makes you add more and more to your preparations. Other people's plans come first, and what you want to do keeps getting pushed back.", "karai": "You're already fully prepared for problems that haven't even happened yet."}, "INFJ>ESTJ": {"title": "You set up the rules, and you think of who's on the other side.", "body": "At the end of your proposal to fix how things run at work, you add: \"So everyone can go home on time.\" Seeing ahead and following through on what you decide is the part of you that wobbles least. Quiet thinking and brisk action, imagination and respect for facts, feeling for people and clear reasoning—you really do manage both sides of each.", "say": "\"I need you to keep the deadline. But if you're struggling, tell me early.\"", "do": "First thing in the morning you make the day's task chart, and you quietly lighten the load for anyone who looks unwell.", "worry": "The more you lead from the front, the less time you have to sort out your thoughts alone. On nights after you've given clear orders, you replay whether you said too much.", "karai": "Your reason for building a system is usually \"so nobody ends up crying.\""}, "INFJ>ESFJ": {"title": "You make a place for everyone, starting with the seating chart.", "body": "You move around a gathering with a smile, and you've still noticed the one person who's been quiet for a while. Caring about people's feelings and acting with the future in mind is the center your nature and character share. Quietly letting your imagination roam and warming up a room, thinking about meaning and caring for everyday life—you handle both with ease.", "say": "\"Tea and snacks are ready! …Hey, you've seemed down for a bit. What's up?\"", "do": "After deciding the seating for a birthday party, you picture the flow again and again so the guest of honor never has to feel awkward.", "worry": "You do so much to see people smile that your battery dies the moment you're alone. Protecting the mood sometimes means you miss your chance to say what you wanted.", "karai": "Your day goes like this: filled up by everyone's \"thank you,\" then flopping down alone at home."}, "INFJ>ISTP": {"title": "Few words, but the fastest hands when someone's in trouble.", "body": "When a friend's bike chain slips off, you fix it without a word and then ask, \"So how have you been?\" Recharging alone and quietly watching how things work is your steady base. Imagination for meaning and hands that check for themselves, care for people and a cool eye for how things work, planning ahead and moving in the moment—all of it lives inside a single action.", "say": "\"Let me see. Probably right here.\"", "do": "When the office printer jams, you're the first to open the back panel and pull the paper out cleanly.", "worry": "You show feelings through actions more than words, so your kindness doesn't always come across. You want to think carefully about the future but also focus only on what you can do now, and you can't choose.", "karai": "You're fast to show up with a toolbox, but \"Are you okay?\" never quite makes it out."}, "INFJ>ISFP": {"title": "Instead of words, you send a seasonal postcard.", "body": "Feelings you can't quite put into words, you tuck into a small gift or gesture. That's your way. Valuing quiet time alone and caring about people's feelings above all is what your nature and character share. You see meaning and the road ahead, and you savor colors and textures right in front of you; you can plan, and you can also go softly with your mood.", "say": "\"These flowers felt like you. …I just want you to feel better.\"", "do": "For a friend who's feeling low, you pick a seasonal postcard and mail it with a short note.", "worry": "You know you should think about the future, but you want to honor how you feel right now, so you can't decide. You feel others' pain easily, and one sad news story can weigh on you all day.", "karai": "You spend your whole day off choosing a gift to cheer someone up."}, "INFJ>ESTP": {"title": "Light on your feet and deep in your care—you have both.", "body": "You head out on a sudden whim, and on the way back you're the one listening most deeply to your friend's worries. Your nature and character point in different directions on every count, so no single pattern holds you, and your range is wide. Moving fast with the flow and sensing hearts and meaning, the rush to get out there and the quiet time to look back—all of it is yours.", "say": "\"Let's just go! They've seemed down lately—why don't we invite them?\"", "do": "Invited to try bouldering for the first time, you say yes on the spot, and during the break you're giving the person next to you career advice.", "worry": "When you're on the move it's fun, but once you're alone, a single comment someone made won't leave your head. People tend to see you as light, and how deeply you think rarely comes across.", "karai": "You look like you go with the vibe, but you've been thinking about the reason for that vibe for three days."}, "INFJ>ESFP": {"title": "From the center of the fun, you spot the one on the edge.", "body": "The person having the most fun at the party is, on the way home, wondering, \"Did she have a good time?\" That surprising side is you. Making decisions with people's feelings in mind stays the same in every setting. Thinking deeply alone and livening up a group, imagining meaning and savoring the moment, planning and riding the flow—you move between them freely.", "say": "\"Today is so much fun! Hey, let's go get her to join us.\"", "do": "After belting out a song at karaoke, you quietly pass the mic and the song list to someone who hasn't sung yet.", "worry": "After you've had fun with everything you've got, your heart can't keep up without time alone. Wanting to enjoy now and wanting to prepare for later take turns showing up.", "karai": "The second you get home, you switch off along with your phone."}, "INFP>INTJ": {"title": "You turn the ideal in your heart into timelines and step-by-step plans.", "body": "You map out your favorite story's world with timelines and maps, until the notes are thicker than the story itself. Thinking deeply alone and picturing what isn't here yet is your unchanging starting point. You stay true to your feelings and reason things through, enjoy the flow and plan ahead, so your ideals don't stay dreams—you break them into steps and make them real.", "say": "\"With this plan, three years should do it. If it stops being fun, we'll rethink it then.\"", "do": "You decide to redo your room, collect photos of the mood you love, and then make a chart of every furniture measurement.", "worry": "The faster things go, the more you stop and ask, \"Is my heart actually happy with this?\" Even for choices you want to make with your heart, you go looking for a correct reason.", "karai": "You've made a scored chart of whether things spark joy."}, "INFP>INTP": {"title": "You can explain \"this just makes me cry\" with music theory.", "body": "Once you start talking about something you love, you can't stop—and you can explain its charm both as a feeling and as a system. Loving time alone, valuing inspiration, and following your interests is the ground your nature and character share. You care about feelings and you think things through logically, so being moved and analyzing sit at the same table.", "say": "\"This song makes me cry somehow. …I think it's because the chord changes right here.\"", "do": "After a movie, you stay up late writing notes that analyze exactly why it moved you.", "worry": "If you can't explain what you feel with logic, you can't settle down. And sometimes you think so hard that you miss the moment to simply enjoy it.", "karai": "By the time you've figured out why you were moved, the feeling has wandered off."}, "INFP>ENTJ": {"title": "Hard numbers and \"because I love it,\" in the same slide deck.", "body": "In meetings you lay out clear numbers, while the first slide passionately explains why you want to do this at all. Picturing possibilities no one can see yet is the center your nature and character share. Nurturing ideas alone and leading from the front, heart and logic, flexibility and follow-through—you use each one as the goal demands.", "say": "\"We hit the target this month. Also, I really love this project.\"", "do": "While helping a junior coworker, you sketch out a three-stage action plan on paper and hand it to them right there.", "worry": "The more you take the lead, the less time you get to lose yourself in what you love. On days you make tough calls, you wonder whether you went against what you care about.", "karai": "In meetings you decide in seconds, but picking dinner takes you thirty minutes."}, "INFP>ENTP": {"title": "Sharp, joking opinions—with a kind follow-up included.", "body": "Right after you say \"What if we flipped it?\", you quietly check the other person's face. Trusting inspiration and moving freely with the situation is something that's always been you. You can dream up ideas alone and grow them by talking, care about feelings and push with logic, so you can enjoy a debate without leaving anyone behind.", "say": "\"Oh—I don't mean your idea's bad, okay?\"", "do": "You invent the rules for a new game while chatting with friends, then secretly work out all the details at home.", "worry": "When a debate gets fun and you say too much, you spend the whole night uneasy about how they felt. You often feel there's never enough time for either hyping things up with people or daydreaming alone.", "karai": "Every sharp comeback comes with a quiet little follow-up."}, "INFP>INFJ": {"title": "You take a passing idea and grow it for a whole year.", "body": "You picked up a hobby on a whim, and before you knew it, a full year of practice plans filled your planner. Calming your heart alone and treasuring inspiration and people's feelings is the part of you that doesn't move. You can follow your feelings softly and also move steadily ahead, so you can grow a small idea into something that helps others.", "say": "\"This way just feels right somehow. So I'll get it ready by next month.\"", "do": "A month before a friend's birthday, you start saving gift ideas on your phone, a little at a time.", "worry": "Stuck between wanting freedom and wanting things settled, you make plans and erase them. Trying to meet others' expectations, you pack your schedule so full that your own heart gets left behind.", "karai": "You've even scheduled your \"take it easy\" days."}, "INFP>INFP": {"title": "You've always held on to what moves you, simply and sincerely.", "body": "When you find a view you love, you stop, take a photo, and save it with a few words. Your nature and the character you've grown point the same way, so caring for what moves you, staying close to others' pain, and shaping your feelings in your own way have grown without wavering. Where that's welcomed, you shine freely; where it isn't, you lose your spark without knowing why.", "say": "\"That's so lovely. …I can't explain it, but it's just good, you know?\"", "do": "On the way home after the rain, the sky in a puddle is so pretty that you take the long way back.", "worry": "When you keep doing things that don't fit your heart, it wears down without you knowing why. The harder you try to fit in, the easier it is to lose track of what you loved.", "karai": "The story in your head is past volume ten, but cleaning your room hasn't gotten past page one."}, "INFP>ENFJ": {"title": "You put your feelings into words and build them with friends.", "body": "You plan a small event and gather people, and between tasks you hide in a café to write down what it all means to you. Valuing inspiration and deciding with people's feelings in mind stays the same in every setting. Nurturing your thoughts alone and leading the circle, following your heart and planning ahead—you move back and forth between them.", "say": "\"If we do it together, it'll be great! I already made the schedule.\"", "do": "The night you hear a friend's sad news, you mail them an encouraging letter with three dates you could meet next.", "worry": "As you keep cheering everyone on, your alone time to settle your own feelings disappears. The more you lock in plans to meet expectations, the less free your heart feels.", "karai": "You cheer on everyone's dreams at full volume, but your voice gets tiny when it's your dream."}, "INFP>ENFP": {"title": "You go back and forth between lively days and storybook nights.", "body": "On the night after you've made everyone laugh, you replay the day's events and savor them like a story. Trusting inspiration, valuing feelings, and moving with the flow is the part of you that stays steady. You can dream deeply on your own and also get energy from people, which is exactly why both kinds of time feel so full.", "say": "\"Let's all go, it'll be so fun! I'm walking home alone, though.\"", "do": "The night after a day out with friends, you look back through the photos and make a playlist that fits the memories.", "worry": "You love seeing people, but after too much you suddenly don't want to talk to anyone. You can't predict that wave yourself, and after turning down an invite you feel guilty.", "karai": "The number of people you've told \"Let's hang out soon!\" is way bigger than the free days on your calendar."}, "INFP>ISTJ": {"title": "A tiny drawing in the corner of a perfect manual.", "body": "People often see you as the \"very proper\" type, yet kindness and a love of beauty slip into the small details of your work. Recharging alone and quietly thinking things over is the ground your nature and character share. Seeing what's not there yet and building on facts, feeling for people and deciding with logic, freedom and follow-through—you can use all of them.", "say": "\"I'll check and get back to you. Also, could I change the colors on this?\"", "do": "After writing a flawless instruction manual, you draw a tiny picture in the corner of the last page.", "worry": "You're doing everything right, yet sometimes you feel empty: \"Is this what I wanted to do?\" Even when you start something you love, you look for a reason and a plan first.", "karai": "You've even put deadlines on your dreams, and now you're rushing yourself."}, "INFP>ISFJ": {"title": "A family calendar, with little doodles in the margins.", "body": "You remember the likes and plans of the people close to you, and quietly add your own small touch. Calming your heart alone and deciding with people's feelings in mind is the steady piece your nature and character share. Imagination and trust in experience, going where your heart leads and planning ahead—you put all of it into your everyday care.", "say": "\"Everything's ready for tomorrow. I made you a little good-luck charm, too.\"", "do": "You write the family's plans neatly on the calendar and add small drawings in the blank spaces.", "worry": "In days full of things you have to do, time for what you love keeps shrinking. You're happy to help, but sometimes you wonder, \"What was it I wanted to do?\"", "karai": "You never forget anyone's special day, but you push back the deadline on your own dream every year."}, "INFP>ESTJ": {"title": "You have both the drive to get things done and a gentle heart.", "body": "At work you give clear, brisk directions; at home you sink into your favorite music or books alone. Your nature and character point in different directions on every count, so you don't fit a set mold, and your range is wide. The strength to plan and follow through and the sensitivity to settle your heart and protect what matters both come from the same sincerity.", "say": "\"That's it for today! Is everyone getting enough rest?\"", "do": "While making the team's schedule, you jot down next to each name something that person has been working hard on lately.", "worry": "The more people count on you to lead, the more you push your own feelings aside. After you say something right, you remember the look on their face and feel down.", "karai": "In meetings you run things like a drill sergeant; on the way home you're crying at a heartwarming video."}, "INFP>ESFJ": {"title": "Everyone's comfort, with a spoonful of playfulness.", "body": "You set up the welcome party at work smoothly, right down to a handmade card for each new hire. Deciding with people's feelings in mind is what your nature and character both hold dear. Daydreaming alone and warming up a room, inspiration and keeping daily life in order, going with your mood and planning well—you mix them however you like.", "say": "\"Seats and food are all set! And there's a little surprise, too.\"", "do": "For a friend's housewarming, you pick a plant that suits their room and even give it a name before you hand it over.", "worry": "The more you try to meet everyone's expectations, the less time you have to daydream alone. You care so much about harmony that the things you love start to feel selfish.", "karai": "After you've collected everyone's \"That was fun!\", you push your own fun to next month."}, "INFP>ISTP": {"title": "Quietly working with your hands, putting kindness into what you make.", "body": "You repair an old piece of furniture yourself, then paint it your favorite color while you're at it, until you love it more than before. Recharging alone and moving freely with the moment stays the same for you. You can picture what doesn't exist yet and test it with your hands, care about feelings and see how things work, so what you make carries your care for whoever uses it.", "say": "\"One screw, and this is fixed.\"", "do": "As you measure a homemade shelf, you check again and again that it's at a height the user can reach.", "worry": "You're not great at putting feelings into words, so your kindness can look curt. Even when you try to settle things with logic, your hands stop if your heart isn't convinced.", "karai": "All you ever say is \"Whatever,\" yet you remember their favorite color and finish the piece in it."}, "INFP>ISFP": {"title": "You see a sunset and think of a story's first page.", "body": "You line up stones and leaves from a trip in a small box and give each one a memory's name. Valuing time alone, putting feelings first, and moving with the flow is what your nature and character share. You can imagine what isn't here yet and savor colors, sounds, and textures exactly as they are, so whatever moves you can become a story or something you make by hand.", "say": "\"Doesn't this sunset look like the start of a story?\"", "do": "You bring home one flower you found on a walk, put it in a tiny jar, and gaze at it for a while.", "worry": "You love so many things, but you're not sure how to connect them to your future. You don't like clashing with people, so you tend to quietly swallow what you want to say.", "karai": "You can't throw away a single keepsake, and your drawer has already become a tiny museum."}, "INFP>ESTP": {"title": "You nudge a hesitant friend forward and jump in together.", "body": "You give a hesitant friend a push, jump in with them, and still keep an eye on how they feel afterward. Moving flexibly with the situation is the steady center your nature and character share. Dreaming alone and moving with energy among people, inspiration and a grip on reality, caring about feelings and coolly weighing pros and cons—you use each one as the moment calls for.", "say": "\"Don't overthink it, just try! …But if you hate it, tell me right away.\"", "do": "Invited fishing for the first time, you say yes instantly, and come home best friends with the person fishing next to you.", "worry": "After you act on impulse, you're alone wondering, \"Did I hurt anyone?\" Because people see you as fun and easygoing, it's hard to say you'd like a quiet day.", "karai": "You'll sign up for bungee jumping in a second, but it takes you five minutes to flag down a server."}, "INFP>ESFP": {"title": "A master at sharing the fun of right now with everyone.", "body": "You go around telling everyone about great food and fun places, and in each one you find a story that's just yours. Caring about people's feelings and moving with the flow is your center, no matter what. Getting lost in your imagination and brightening up a group, inspiration and savoring the fun in front of you—you have both.", "say": "\"Everyone's going to love this place! Doesn't it feel like a secret hideout?\"", "do": "On a whim, you start a handmade photo album for a friend's birthday and finish it just in time on the morning of.", "worry": "You pack in so many fun plans that you run short on alone time to settle your heart. Trying so hard to keep things bright, you can't show anyone when you're sad.", "karai": "You smile the whole time in front of everyone, then play sad songs on the ride home and soak in them."}, "ENTJ>INTJ": {"title": "Out front in the meeting, redrawing the blueprint alone at night.", "body": "You state the plan with total confidence in the meeting, then go home and refine it one more round. Reading ahead, deciding by logic, and sticking to the steps never wavers, wherever you are. Standing in front of people gives you momentum, yet your best thinking happens in quiet. You move easily between the room where you lead and the desk where you polish.", "say": "\"This is the direction. I'll sleep on the details and send them over.\"", "do": "The night after presenting the plan to your team, you're alone at your desk fixing which way the arrows point on the slides.", "worry": "The more you're asked to lead, the less time you get to think alone. Balancing the joy of being relied on with your need for quiet takes real energy every time.", "karai": "The moment you say \"Leave it to me,\" the solo route to midnight is already locked in."}, "ENTJ>INTP": {"title": "Quick to decide, and just as quick to question it.", "body": "You reach a conclusion fast, then immediately start asking, \"But is that really true?\" Checking every spark of insight with logic is how you think in every setting. Add to that the push to rally people toward a goal and the focus to take a system apart alone, plus the discipline to keep a plan and the flexibility to rebuild it midway. Going back and forth between speed and depth is your gift.", "say": "\"Okay, decided. Wait, wouldn't it be more fun to tear down the assumptions first?\"", "do": "You're the one marking up your own plan with the most red ink.", "worry": "You want to decide quickly, but the more you think, the more answers appear, and your hands stop. You want days with people and days alone, and when you overbook, you run out of breath.", "karai": "The answer was ready ages ago, but testing it got so fun that only the deadline kept moving."}, "ENTJ>ENTJ": {"title": "Once you spot the goal, the road is already built.", "body": "The moment you see the goal, the steps line up in your head. Your ability to read ahead with people around you, think things through, and see them to the end looks exactly the same whether you view what you were born with or what experience shaped. That's why you always end up running things. It also means that places where nothing gets decided can leave you tired in a way you can't explain.", "say": "\"So where's the finish line?\"", "do": "You set goals for your day off and check your completion rate in the evening.", "worry": "The more you go at your own pace, the later you notice others haven't kept up. Even rest has to mean something to you, so it's hard to truly relax.", "karai": "For your lazy day, you've made a lazy-day schedule."}, "ENTJ>ENTP": {"title": "The goal never moves, but the route can change any time.", "body": "The deadline is sacred. How you get there, though, can change on the day. Getting energy from people and turning ideas into logic has never wavered for you. What shifts is your approach: you can build a tight plan, and you can enjoy a surprise twist, using each one when the moment calls for it.", "say": "\"The deadline is Friday, no exceptions. …So can I change the entire method?\"", "do": "You build a precise meeting agenda, then launch a whole new project from the small talk that day.", "worry": "The urge to keep your commitments and the urge to try a more interesting path show up at the same time. When plans change too often, you wonder if you're dragging people around.", "karai": "You prepared three backup plans, then took off with a fourth that wasn't any of them."}, "ENTJ>INFJ": {"title": "You map the road to the ideal, and notice who's falling behind.", "body": "While listening to a younger coworker talk about their future, you've already drafted their five-year plan in your head. Picturing what isn't visible yet and moving forward with a clear outlook stays constant in you. You can lead out front or think quietly, decide by logic or read feelings, so you naturally notice anyone who's about to be left behind.", "say": "\"Let's make this our goal. …Is everyone doing okay?\"", "do": "In the middle of a planning meeting, a quiet member's face catches your eye, and at the break you hand them a cup of tea.", "worry": "Even when you know the right direction, you can't say it if someone might get hurt. On days you think too hard about feelings, time alone is what brings you back.", "karai": "You fit everyone's happiness into the plan, and somehow your own free time vanished."}, "ENTJ>INFP": {"title": "You turn big ideals into reality, on terms your heart accepts.", "body": "When you say, \"We have to do this project,\" your eyes are already looking a little ahead. Being drawn to possibilities that don't have a shape yet is you, from every angle. You carry the drive to rally people and get results, and the need to warm your thoughts alone; the push to decide and move, and the softness to take a detour your heart asks for.", "say": "\"If we're doing it, I want to do it in a way I truly believe in.\"", "do": "After passionately pitching your idea and gathering a team, you go home and write in your journal to settle your feelings.", "worry": "Wanting results and wanting it to feel right rarely point the same way. After a day of leading people, you need more alone time than you expect.", "karai": "You have a plan to change the world, but today's laundry is still waiting for the right mood."}, "ENTJ>ENFJ": {"title": "A leader who won't give up on results or on people.", "body": "You lay out the team goal clearly, and you also notice when someone's voice drops a little. Getting energy from people and moving ahead with a plan is your steady ground. Where you differ is in how you judge: you can decide by logic or by caring for each person, and you choose based on the moment.", "say": "\"Let's hit this target this month! So, anyone feeling down lately?\"", "do": "After running a tight meeting, you check in one-on-one with the person who barely spoke.", "worry": "When you need to be firm, their face comes to mind and you soften your words too much. Trying to move everyone forward, you end up being the one running around the most.", "karai": "You're so busy watching everyone grow that your own goal has been rolled over to next month."}, "ENTJ>ENFP": {"title": "You can carry the excitement all the way to the finish line.", "body": "It started as a spur-of-the-moment surprise, and somehow there's now a schedule and a budget sheet. Feeling more alive in a crowd and lighting up at new possibilities has never changed. You can decide by logic or by heart, follow the plan or follow your mood, and having both lets you turn fun into real results.", "say": "\"This is going to be so fun! …Okay, let's assign roles and deadlines.\"", "do": "The day after suggesting a birthday party for a friend, you've already texted everyone their assignments.", "worry": "You want to start fun things one after another, but you also want to finish all of them properly, so you get swamped. When you meant to comfort someone, you talked efficiency first, and later hold a solo review meeting.", "karai": "The person who said \"Let's keep it casual\" is the one running the show the hardest."}, "ENTJ>ISTJ": {"title": "A practical builder who stacks big visions on solid steps.", "body": "Right after saying \"We're aiming for number one,\" you start checking last month's data line by line. Deciding with logic and moving with a clear outlook stays steady in every setting. You have the drive to pull people in and the patience to work quietly, the eye for possibilities and the care to check facts, so you can tie a dream to the ground with numbers and steps.", "say": "\"First, could you show me all of last month's data?\"", "do": "The night you talk about your dream, you work out its exact cost in a spreadsheet.", "worry": "Wanting to try new things and wanting the safe method pull at each other, so deciding takes time. After a long stretch of leading, you miss quiet time to just work.", "karai": "Even for an adventure, you won't leave until the manual is finished."}, "ENTJ>ISFJ": {"title": "You read the big picture and still catch the small troubles nearby.", "body": "While drawing up the team's yearly plan, you also add everyone's birthday to the calendar. Your sincerity in finishing what you commit to has always been the same. You can stand in front or support quietly, look ahead or value what's right here, decide with your head or stay close to feelings. Reliability and kindness live together in you without strain.", "say": "\"Let's get this far by next year. Oh, but first, are you feeling alright?\"", "do": "When you help a friend move, you number all the boxes and also show up with their favorite tea.", "worry": "Even when you want to lead, your care for others comes first and you take a step back. The harder you try to do your part well, the more your own rest gets pushed aside.", "karai": "You can see the company's future clearly, but not how many vacation days you have left."}, "ENTJ>ESTJ": {"title": "You move a team with a vision of the future and a feel for the field.", "body": "When you pitch a new idea, you bring three past examples that worked. Gaining energy from people, deciding with logic, and moving with a plan doesn't waver one bit. The difference is how you see things: you can picture what doesn't exist yet and you can lean on experience and facts. So your plans never become fantasy, or just a copy of last time.", "say": "\"This is where I want us in three years. …So let's decide what we do tomorrow morning.\"", "do": "Right after sharing the three-year goal at the morning meeting, you head to the stockroom to count the inventory yourself.", "worry": "You want to change things and also protect what's working, so drawing the line is hard. You tend to use your own tidiness as the standard and expect the same speed from others.", "karai": "\"Do it however you like\" arrives with a submission template attached."}, "ENTJ>ESFJ": {"title": "You plan out a place where everyone belongs.", "body": "You organize the event flawlessly, then spend the day thanking every single person. Gaining energy from people and moving ahead carefully with a plan is your lasting strength. You can also picture the future and value what's real now, decide with logic and care about how people feel, so you protect both results and a warm mood at once.", "say": "\"Let's push through! Tea and snacks are ready, by the way.\"", "do": "You redo the office cleaning rota and, while you're at it, find out everyone's favorite snack.", "worry": "When you want results, the worry about upsetting people shows up. You love being relied on, take on too much, and find your schedule packed solid.", "karai": "You worked out everyone's seat and forgot to save one for yourself."}, "ENTJ>ISTP": {"title": "Set the goal, then handle the rest with skill and ingenuity.", "body": "To others, you may look like someone who says little but delivers results first. Thinking with logic and deciding by reason stays consistent in every scene. On top of that, you can lead people or work quietly with your hands, see far ahead or grab the facts, follow a plan or adjust on the spot, so you quickly pick \"the best move right now.\"", "say": "\"I'll mess with it first and figure it out after.\"", "do": "After announcing the team goal, you lay out your tools and start building a prototype alone.", "worry": "Wanting to plan ahead and wanting to act on the spot keep trading places, so your own pace is hard to read. When you're put in charge, you miss time alone with your hands busy.", "karai": "Your face clearly says it would be faster to just fix it than to keep talking in this meeting."}, "ENTJ>ISFP": {"title": "A gentle sense of things, with a firm strength tucked inside.", "body": "Usually you're the smiling listener, but when it really matters you set the plan with surprising clarity. You hold both a calm care for your own senses and pace, and the strength to set a goal and lead people. Alone time and a crowd, feelings and logic, the present moment and the long view: you can reach all of them, so you don't hesitate when it counts.", "say": "\"Either is fine. Oh, but this one thing, I can't budge on.\"", "do": "Picking a café with friends, you say \"anywhere,\" then gently steer everyone to a quiet place with outlets.", "worry": "You want things calm, but when things drag on, you quietly get irritated. You hold back what you want to say, and later it can come out sharper than you meant.", "karai": "With the softest smile, you won't let the deadline slip by even one day."}, "ENTJ>ESTP": {"title": "A competitor who maps the win, then makes the call on the spot.", "body": "You build your strategy with the long view, yet once you're on the scene, your body moves before you think. Getting energy from people and deciding quickly by logic stays the same in every setting. You have the power to plan ahead and the reflexes to grab the chance in front of you, which is why you shine when it matters most.", "say": "\"Here's the plan. The rest, we improvise live!\"", "do": "You prepare flawless materials for a sales meeting, then change the pitch on the spot as you read the client's reactions.", "worry": "You want to think ahead, but you jump at whatever's fun right now and the plan slides. You skip a check to keep things fast, and regret it later.", "karai": "Three days after making a long-term plan, you're already off on a different game."}, "ENTJ>ESFP": {"title": "Bringing a team full of laughter all the way to the goal.", "body": "You're the life of the wrap party, and quietly already talking about the next goal. Feeling more energy the more you're with people never changes. You can plan ahead and enjoy the moment fully, decide by logic and sense how people feel. With fun and follow-through, you get everyone moving in a bright direction.", "say": "\"Let's have the best time today! …Oh, we meet at 8 tomorrow.\"", "do": "While being the loudest one setting up for the school festival, you also post the cleanup chart on the wall.", "worry": "You want to enjoy the moment, but part of your mind keeps planning the next step. Because you care about people's feelings, you tend to dwell after saying something tough.", "karai": "The plan you made on a whim, you carry out more precisely than anyone, and everyone's stunned."}, "ENTP>INTJ": {"title": "You turn sparks of insight into a steady blueprint.", "body": "An idea tossed out in small talk becomes a proposal by the next morning. Being moved by possibilities and thinking things through logically is the most unchanging part of you. You can widen ideas by talking or refine them deeply alone, move lightly or plan far ahead, so you have both broad ideas and the steadiness to finish them.", "say": "\"Wouldn't it be interesting to think about it backwards?\"", "do": "A book that caught your eye at the bookstore sparks a new project, and by evening you've outlined the chapters.", "worry": "You want to bounce ideas off people, but talk too long and you need to be alone. Torn between trying it now and planning it first, you're often slow to start.", "karai": "The plan in your head is perfect, but you move ahead without explaining it, and everyone's surprised."}, "ENTP>INTP": {"title": "Widening ideas in debate, digging deeper on your own.", "body": "One minute you're leaning in with \"Tell me more!\" and the next you suddenly want to think alone. Trusting insight, thinking with logic, and flowing with the situation look the same from every side. The difference is where your energy comes from: you can move between the boost of talking with people and the deep thinking of time alone.", "say": "\"Give me a sec to think about this on my own.\"", "do": "After a lively debate, you go home and keep it going alone in three pages of notes.", "worry": "Some days you want people, other days no one at all, so planning your week is tricky. Thinking is so fun that sometimes you feel satisfied before you ever act.", "karai": "On days with no one to debate, you argue with online articles in your head."}, "ENTP>ENTJ": {"title": "Ideas turned into projects the very same day.", "body": "You toss out a fun idea in a meeting, and suddenly owners and deadlines are set. Getting energy from people and testing ideas with logic has always been you. You have the lightness to move with the flow and the power to plan and push through, so you can be both the idea person and the organizer.", "say": "\"What about this? Okay, decided. Prototype by next week.\"", "do": "The vegetable garden you started on the weekend is run on a harvest schedule by week two.", "worry": "Trying new ideas and keeping the plan you made can clash, and you get tied up by your own rules. Moving fast, you're slow to notice people who can't keep up.", "karai": "For something you \"just kind of tried,\" the report is suspiciously impressive."}, "ENTP>ENTP": {"title": "Still chasing whatever's interesting, all the way here.", "body": "Is \"What if we just dropped all of that?\" one of your catchphrases? Your knack for widening ideas through talk and flipping the obvious has grown in the same direction in what you were born with and what experience built. Open questions light up your eyes, so places with nothing but routine can drain you for no clear reason.", "say": "\"Who decided it had to be this way, anyway?\"", "do": "Every time you find a new hobby you buy all the gear, and three months later you're talking about the next one.", "worry": "You're great at starting, but you blame yourself for getting bored of keeping going. When a dull place drains you, it's usually not your fault; it's just the wrong place.", "karai": "Once the debate heats up, you forget you started on the opposite side."}, "ENTP>INFJ": {"title": "You offer sharp insight in a shape the heart can receive.", "body": "While listening to a friend's worries, you casually name the real feeling they hadn't noticed yet. Picturing possibilities that aren't visible yet is the least shakable part of you. You can widen ideas with people or reflect deeply alone, think with logic or sense feelings, move lightly or see far ahead. With sharpness and kindness, you give people a push.", "say": "\"Which one matters most to you?\"", "do": "Helping a friend think about a career change, you list three jobs that would suit them before they do.", "worry": "Even with an interesting thought, you hesitate to say it in case it hurts someone. Taking feelings in so deeply means you need plenty of time alone to recover.", "karai": "You give brilliant life advice to others, and settle your own life with \"Eh, it'll work out.\""}, "ENTP>INFP": {"title": "Free ideas, carried gently on a kind heart.", "body": "The night after getting lost in a debate with friends, you sit alone and start writing something like a story. Valuing inspiration and moving flexibly with the flow never changes. You can get lively with people or let your imagination grow alone, test ideas with logic or honor feelings, so your fun ideas always carry a wish to help someone.", "say": "\"That's so funny! …But the person hearing it might feel a little sad.\"", "do": "A strange animal you saw at the zoo turns into a made-up field guide you start writing with a friend.", "worry": "Even when logic says yes, you can't move if your heart isn't on board. After a fun night, you look back alone to check whether your words hurt anyone.", "karai": "In the margins of your notebook, brilliant ideas, doodles, and unsaid feelings take up equal space."}, "ENTP>ENFJ": {"title": "Fun ideas that bring everyone's hearts together.", "body": "You pitch a new project with a smile, and quietly visit the likely critics one by one beforehand. Getting energy from people and being moved by possibilities is your steady ground. You can think logically and care about feelings, move on the spot and plan ahead, so you can excite the room and still lay a path everyone can follow.", "say": "\"Want to figure out together how to make everyone excited about it?\"", "do": "You design a new club practice routine and secretly make an easier version so the less confident kids can enjoy it too.", "worry": "Even when you want to say something sharp, you swallow it for the mood or the other person. The more you carry the leader role, the less time you get to try ideas freely.", "karai": "After taking in everyone's opinions, your own original idea is nowhere to be found."}, "ENTP>ENFP": {"title": "Spreading the fun with both logic and heart.", "body": "When you talk, people just seem to gather around. Getting energy from people and moving lightly on inspiration is the same no matter how you slice it. The difference is in how you judge: you have the sharpness to test ideas logically and the warmth to make people smile. You love a good debate and still leave no one behind.", "say": "\"Doesn't that logic seem a little off? …No, I totally get how you feel, though.\"", "do": "Mid-chat you invent a new game, then rework the rules so even little kids can join.", "worry": "You want to say what you think is right, but picturing someone's disappointed face hits the brakes. Your interests keep moving and you value your friendships, so there's never enough time.", "karai": "Five minutes after saying \"Let's think about this calmly,\" you're the most fired up."}, "ENTP>ISTJ": {"title": "Edgy ideas, made real through careful steps.", "body": "Even with a new idea, you start by testing it small and putting the results in a table. Thinking and judging with logic doesn't waver in any setting. You can widen ideas by talking or progress steadily alone, look at possibilities or check the facts, stay flexible or follow the plan. Your strength is never letting an idea stay just talk.", "say": "\"Sounds interesting. But let me check the past records first.\"", "do": "You propose a better paperwork flow at work, then time a full week of tasks with a stopwatch.", "worry": "You want to try new things and also keep the reliable method, so it's hard to decide. When you're stuck enforcing rules for too long, the lack of room for ideas leaves you restless.", "karai": "You verify your boldest idea with the plainest process anyone's ever seen."}, "ENTP>ISFJ": {"title": "Behind \"the usual way,\" you're already thinking of a better one.", "body": "You finish the task you were given, and somehow there's now a system that makes it easy for anyone next time. You have the kindness to look after people and do what's expected with care, and the curiosity to question the obvious and dream up new ways. Comfort and inspiration, quiet support and lively ideas: that mix makes any place a little better.", "say": "\"The usual way is fine. …I was just thinking this might make it a bit easier.\"", "do": "You reorganize the family fridge with color-coded labels so anyone can find anything.", "worry": "You're good at going along with others, but when the same thing repeats, part of you gets bored. Even with a good idea, you sometimes hold it back because of the mood in the room.", "karai": "You wear the humblest face and keep the boldest improvement plan in your pocket."}, "ENTP>ESTJ": {"title": "A leader who keeps wild ideas running on the ground.", "body": "You change the usual meeting with \"Let's do this one standing,\" and still end it right on time. Getting energy from people and deciding with logic never changes. You can chase new ideas or rely on experience and facts, move flexibly or work to a plan. Ideas in one hand, execution in the other.", "say": "\"Why not shake it up? Then let's set owners and deadlines right now.\"", "do": "You suggest a new booth for the neighborhood festival and draw the foot-traffic map yourself.", "worry": "Because you understand why rules matter, balancing them with the urge to try new things is hard. As the leader, you put being right first, and your words can come out harsh.", "karai": "To spread an unconventional method, the first thing you do is write a manual."}, "ENTP>ESFJ": {"title": "The one who makes everyone's everyday a little more fun.", "body": "You bring a small new twist to every regular get-together, and still track attendance and fees perfectly. Getting more energy the more you're with people stays the same in every scene. You can come up with new possibilities and care for daily life, think with logic and consider feelings, stay light and stay earnest. You shape fun ideas into something everyone enjoys.", "say": "\"Wouldn't it be fun if we did this?\"", "do": "You organize sharing extra food with the neighbors and throw in a little seasonal raffle too.", "worry": "Even when a cheeky comeback pops into your head, you swallow it for the other person's sake. You love doing things for others, so there's little time left to test your own ideas.", "karai": "The person with the silliest idea is also the one cleaning up most thoroughly."}, "ENTP>ISTP": {"title": "Logic and agility get you out of almost any problem.", "body": "When you buy a new appliance, you try every button before reading the manual. Thinking with logic and adapting to the situation is you from every angle. You can widen ideas by talking or work quietly alone, see future possibilities or grab the facts in front of you, so people count on you with words and hands alike when things go wrong.", "say": "\"In theory it should work. …Well, let's just try it.\"", "do": "While listening to your friend chat, you've already fixed the squeak in their bike with the tools at hand.", "worry": "The gap between wanting to debate and wanting to work in silence is big, so people may see you as moody. You also waver between widening ideas and sticking only to what's certain right now.", "karai": "You said \"I'll explain later,\" and it's already fixed."}, "ENTP>ISFP": {"title": "Enjoying with your mind, savoring with your heart and senses.", "body": "An idea from chatting with friends turns into a handmade trinket once you're home alone. Moving flexibly with the flow and wanting to stay free hasn't changed a bit. You can get lively with people or rest quietly, picture possibilities or savor the senses, think with your head or follow your heart. All of these are your way of enjoying life.", "say": "\"That's a fun idea. But right now, I just want to look at this view.\"", "do": "An old sign you spot on a walk grabs you, and before you know it you've been sketching it for an hour.", "worry": "Even when you want to say something sharp, thinking of the other person makes you hesitate. You love a lively time, but without time alone you wear out fast.", "karai": "You keep your calendar open on principle, yet you've already checked every exhibit you care about."}, "ENTP>ESTP": {"title": "The idea hits, and you're already heading out the door.", "body": "The moment after you say \"This could be a new business,\" you're getting ready to go see it in person. Getting energy from people, thinking with logic, and moving with the flow has always been the same. The difference is how you see: you can imagine what doesn't exist yet and grab the reality in front of you fast. You're quick to think and quick to act.", "say": "\"Okay, let's go check it out right now!\"", "do": "On a trip, you pitch a new idea to the locals right there and test it on the spot.", "worry": "You want both future possibilities and today's fun, so your schedule is always packed. Thinking on the move, you head to the next thing before looking back, and repeat the same mistakes.", "karai": "On the way home from the meeting where you agreed to be careful, you've already taken the first step."}, "ENTP>ESFP": {"title": "Amazing ideas that make the whole moment fun.", "body": "When rain cancels the plan, you turn it into a game night at home on the spot. Getting energy from people and moving lightly with the flow is a strength that never changes. You can dream up new possibilities and savor the fun in front of you, think with logic and sense feelings, so everyone around you ends up smiling too.", "say": "\"Hey, I just had a great idea! …If everyone's in, let's do it now.\"", "do": "At the park you join some kids you don't know, and ten minutes later you're the one inventing the new rules.", "worry": "You want to keep the good vibes, but when you spot a contradiction you can't help calling it out. You're sensitive to feelings, so you remember the moment a room went cold for a long time.", "karai": "It was supposed to be just for fun, yet you're the one enjoying it most seriously."}, "INTJ>INTJ": {"title": "Three moves ahead, and steady the whole way.", "body": "In a meeting, you're often the only one who has already spotted the trap nobody else sees. The nature you were born with and the one your experience shaped point the same way: think alone, read ahead, build the cleanest path. Where things make sense, you deliver more than anyone expects. Where the rules have no reason, your energy quietly drains away.", "say": "\"Bottom line: that's going to hurt us in three months.\"", "do": "Before the meeting starts, you've already prepared answers to the questions on the last page.", "worry": "You tend to skip the explanation, and people sometimes call you cold or hard to read. Finding the words that help others understand you takes longer than you'd think.", "karai": "The plan in your head is flawless, and you are the only person on earth who can read it."}, "INTJ>INTP": {"title": "You can redraw your map of the future, happily, as often as it takes.", "body": "The plan is set, but that other idea looks fun too. Going back and forth between plan and detour is very you. Thinking deeply on your own and seeing how things really work has been constant from the start. You can drive toward a goal or rebuild everything around a new discovery, so a stuck problem only gets more interesting.", "say": "\"The steps are ready. …But wouldn't this way be more fun?\"", "do": "After making a moving checklist, you start reading about your new neighborhood's history and can't stop.", "worry": "The urge to decide and the urge to keep thinking hit at once, so new ideas pile up right before the deadline. In front of the submit button, you want just one more look.", "karai": "Your folder holds five files, all named \"final.\""}, "INTJ>ENTJ": {"title": "You plan in private, then lead the charge in public.", "body": "People probably see you as a confident leader waving the flag. But before the big moment, there's almost always quiet time where you work out the strategy alone. Seeing ahead, mapping the logic, and moving once you decide run through both your inborn nature and the one you grew into. You handle quiet prep and public action alike, so you turn assignments into results fast.", "say": "\"I've set the direction. Now let's hand out roles.\"", "do": "You run the meeting, then put in your earbuds and hold a solo review on the way home.", "worry": "After moving people, the tiredness hits all at once. The more people rely on you, the less time you get to think by yourself.", "karai": "The harder you led the team that day, the more likely every notification on your phone is off that night."}, "INTJ>ENTP": {"title": "You turn a casual chat into a project plan before anyone notices.", "body": "A half-joking idea becomes a step-by-step plan by the next morning. Around you, that happens a lot. Trusting your hunches and thinking things through logically have always been part of you. You move between refining ideas alone and expanding them in conversation, between sticking to a path and changing course on the spot, so play and serious work blur in a good way.", "say": "\"That could work. Wait, if we think three years out, this way is stronger.\"", "do": "A joke during a coffee break sparks a new project, and by morning you've sketched its outline.", "worry": "The more excited everyone gets, the more ideas there are, and somehow the sorting lands on you. Days you want to expand and days you want to narrow down show up in the same week.", "karai": "The person who opened the topic and the person cleaning it up are usually both you."}, "INTJ>INFJ": {"title": "You put what's right and what's kind on the same map.", "body": "You decide what to tell a junior colleague in one night, then spend three days on how to say it. That's how you spend your time. Recharging alone, reading where things are headed, and planning ahead form a base that has never shifted. You check what's right with logic and take in people's feelings at the same time, so people quietly come to you for advice.", "say": "\"Logically, this is the right answer. …I'd still change how we say it.\"", "do": "When a friend asks for advice, you send back a solution and a \"don't push yourself\" as a set.", "worry": "What you think is right and not wanting to hurt anyone pull against each other, so you often swallow your words. Because you understand so much, you end up carrying other people's worries too.", "karai": "You read the other person's feelings three moves ahead and forget to read your own."}, "INTJ>INFP": {"title": "You protect the ideals that move you, with solid logic behind them.", "body": "Your head agrees, but your heart isn't ready to go yet. You know that honest side of yourself well. Valuing time alone and being drawn to possibilities no one can see yet never wavers. You can push forward with logic and plans, or follow your values and go with the flow, and you spare no logic or planning for what you love. That is your strength.", "say": "\"I get why it matters. Just wait for my feelings to catch up.\"", "do": "You build a perfect schedule for your creative hobby, then start a different piece depending on your mood.", "worry": "Some days you know what you should do, but your feelings just won't follow. Balancing the plan with your heart's pace quietly wears you out.", "karai": "Your life plan is detailed, but tomorrow is still blank."}, "INTJ>ENFJ": {"title": "You cheer on everyone's dreams, with a winning strategy attached.", "body": "In front of people, you're the bright one cheering them on. On the way home, you're working out the steps to make their dream real. Seeing ahead and moving once you decide has always been your thing. You carry deep solo thinking and the warmth that lights up a room, a cool, logical eye and a kind heart, all at once.", "say": "\"You've totally got this! Also, I narrowed next week's to-dos down to three.\"", "do": "Your best-friend speech makes the whole room cry, and behind the scenes you've timed the program to the second.", "worry": "Because you're good at encouraging others, you take things on with a smile even on days you're running low. After busy, lively time, you don't get enough quiet time to recover.", "karai": "At everyone's future-planning meeting, the only missing agenda item is yours."}, "INTJ>ENFP": {"title": "To you, who carries excitement and calm in the same pocket.", "body": "\"Sounds fun, I'm in!\" comes out about as fast as you spot the hole in the plan. That's what makes you fun. Excitement about possibilities nobody can see yet sits at your center and never changes. Deep solo thinking and jumping into a crowd, clear logic and warm empathy, careful planning and riding the moment: you switch between them as each scene needs.", "say": "\"Don't you think we could make it even more fun?\"", "do": "You hit it off with a stranger over big dreams, then jot down that dream's weak spots on the train home.", "worry": "The gap between days you want people and days you want no one is wide, so planning your week is tricky. Grading your own spur-of-the-moment choices afterward can wear you out.", "karai": "You're the life of the party and the chair of the post-party review, both at once."}, "INTJ>ISTJ": {"title": "You build big visions one reliable step at a time.", "body": "You come up with ideas no one has tried yet, and you still check how it went last time. People see you as careful yet surprisingly fresh. Recharging alone, laying out the logic, and moving as planned are the same in your inborn nature and in how you grew. You go back and forth between imagining possibilities and checking facts one by one, so you rarely make big mistakes.", "say": "\"Let's try a new system. After we recheck last year's numbers.\"", "do": "Before buying a new appliance, you picture how you'll use it for years and compare a hundred reviews.", "worry": "Because you double-check everything, turning ideas into reality tends to take a while. Betting on potential and choosing certainty play a quiet tug-of-war inside you.", "karai": "You tap the stone bridge to test it, then propose upgrades before crossing."}, "INTJ>ISFJ": {"title": "You quietly take care of things before anyone gets stuck.", "body": "An extra jacket, a spare copy of the handout. Your care always arrives a little early. Recharging alone, planning ahead, and moving steadily have never wavered for you. Picturing what could happen and valuing the facts in front of you, cool logic and real kindness: that mix is what lets you get ahead of problems so gently.", "say": "\"Just in case, I brought a spare.\"", "do": "You set up next month's event plan before anyone else, with notes on what each guest likes.", "worry": "Because you act before being asked, people can start taking it for granted, which stings a little. Between efficiency and fitting in with others, your own time keeps getting pushed back.", "karai": "You clear away everyone's \"uh-oh\" in advance and never mention your own."}, "INTJ>ESTJ": {"title": "The bridge between the ideal on paper and real life on the ground.", "body": "When work stalls, people somehow call you. There's a reason. Making decisions with logic and carrying them through as planned is the core you share in both temperament and character. You can read ahead alone and give clear directions in front of people, sketch a path from insight and secure it with facts, and you connect all of it yourself.", "say": "\"Here's the goal. This week, we finish these three things for sure.\"", "do": "You spot wasted steps at work, design a new process, and hand it to everyone the next day.", "worry": "Since you can already see the answer, others' slower pace can frustrate you. When leading goes on for a while, your thinking time alone keeps shrinking.", "karai": "Before the \"let's decide together\" meeting even starts, the answer is already in your pocket."}, "INTJ>ESFJ": {"title": "You read ahead quietly so everyone has a place to belong.", "body": "Seating, the flow of the day, how everyone gets home. The moment someone suggests getting together, your mind is already at work. Planning ahead and moving things forward is a strength that has never wobbled. You hold on to time alone and time with people, possibilities and the facts in front of you, logic and feelings, so you can lift the mood and set up the system too.", "say": "\"I seated people who'd probably get along next to each other.\"", "do": "On neighborhood cleanup day, you've already decided where the tools go and who's making tea afterward.", "worry": "Helping people is fun, but before you know it there's almost no time left to think alone. While matching everyone's feelings, you sometimes miss the chance to share your own opinion.", "karai": "The second you agree to organize, the after-after-party is already designed in your head."}, "INTJ>ISTP": {"title": "You think about the far future, then test it with your hands.", "body": "Once you think up how something works, you want to try it right away. You don't stop at theory; you actually build things that run. Recharging alone and thinking things through logically look the same from either side of you. You switch between planning far ahead and moving on the spot based on the facts in front of you, depending on what the moment needs.", "say": "\"It should work like this. …Eh, we'll know once we try.\"", "do": "Assembling furniture, you glance at the manual once, build it by feel, and still finish it.", "worry": "Phases of wanting long-term plans and phases of handling only what's in front of you take turns, so your follow-through comes in waves. If something doesn't interest you, your hands just won't reach for it.", "karai": "You spend more time playing with the tools in front of you than drawing the blueprint for the future."}, "INTJ>ISFP": {"title": "Sharp foresight, wrapped gently in a soft sense of beauty.", "body": "You see through things calmly, yet you never let go of the beautiful, comfortable things around you. That's your quiet sense of style. Recharging in time alone never changes. Seeing ahead and savoring the moment, deciding by logic and honoring feelings, planning and going with the flow: you choose among them to fit how you feel that day.", "say": "\"On paper, this one's the better deal. …But I like this color.\"", "do": "You redo your room step by step, then change everything at the end to match one item you love.", "worry": "When the logical path and the comfortable path split, either choice leaves a small snag. Your preferences are hard to put into words, so you go quiet when asked to explain.", "karai": "You can line up ten rational reasons, and you still decide with \"because I like it.\""}, "INTJ>ESTP": {"title": "You read ahead, and you enjoy this exact moment to the fullest.", "body": "People think you jumped in on impulse, while a corner of your mind was calculating the winning move all along. That happens a lot. Thinking things through logically is a base that never shakes. Deep solo thought and moving around with people, seeing ahead and grabbing the facts in front of you, planning and acting on the spot: you use them all for both play and work.", "say": "\"Let's just go! …Oh, I did check the last train home.\"", "do": "At a game, you cheer the loudest and still spot the other team's weak point first.", "worry": "The gap between days you want to be active and days you want to think alone is wide, so you overbook and wear yourself out. Afterward, you hold a mental review of the things you decided on a whim.", "karai": "Your mouth says \"it'll work out,\" and your hands already hold the step-by-step guide to making it work out."}, "INTJ>ESFP": {"title": "In the middle of the fun, one calm pair of eyes.", "body": "You're right in the middle of the laughter, yet you can see the whole flow of the room. That's you. The brightness that enjoys the moment with people, and the calm that reads ahead and builds ideas quietly alone. Because the nature you were born with and the one you grew into point in opposite directions, you can keep a good time going without anyone noticing you're steering.", "say": "\"Let's have the best time today! And let's lock in the next date while we're here.\"", "do": "You were laughing at the center of the party, and you're the first to work out the cleanup plan.", "worry": "The more fun the lively time is, the more alone time you need afterward to think. People see you as the cheerful one, which can make it hard to share your deeper thoughts.", "karai": "The loudest one at the party is the quietest one on the way home."}, "INTP>INTJ": {"title": "You turn \"I wonder why\" into results, with a deadline.", "body": "Research that started with a passing question somehow becomes a document someone actually uses. You know how to turn curiosity into results. Thinking deeply on your own and figuring out how things work has been constant from the start. You move smoothly between thinking freely wherever interest leads and planning ahead to see things through.", "say": "\"I need to know why this happens. Okay, conclusions by next month.\"", "do": "A small question about your budget becomes a spreadsheet, and a week later you've built your own money tracker.", "worry": "Wanting to think freely and wanting to finish properly collide, so you struggle with where to draw the line. Even with a plan, a new question pulls your heart away.", "karai": "You set a strict deadline even for your side quests."}, "INTP>INTP": {"title": "You've been nurturing \"I wonder why\" your whole life.", "body": "You started looking something up before bed, and suddenly it was light outside. You may know nights like that. Loving to think alone and never running out of curiosity about how things work is shared by both the nature you were born with and the one experience shaped. You shine where you can think freely, and tire quietly where you're told to obey without reasons.", "say": "\"Wait, why is it like that in the first place?\"", "do": "You look up a word from a video, and thirty minutes later you're reading about a totally different field.", "worry": "Thinking is so fun that getting started tends to slip. It's all done in your head, yet others may think you've done nothing.", "karai": "No one could guess who you are from your search history alone."}, "INTP>ENTJ": {"title": "You make free-range ideas real with friends and a plan.", "body": "When you think up a system, you gather people and actually make it run. Your experiments always take shape in front of everyone. Relying on hunches and thinking logically is a base that never shakes. Digging deep alone and pulling a group together, wandering freely and driving toward a goal: you use each one as the scene calls for it.", "say": "\"I've got a great system. Let's assign roles and test it by next week.\"", "do": "Something you researched for fun turns into a whole new way of running your club.", "worry": "When you keep leading, the time to think freely disappears and it gets stifling. Rushing to the right answer, you sometimes cut your own ideas short.", "karai": "Five minutes after suggesting \"let's all think about it,\" you announce the conclusion."}, "INTP>ENTP": {"title": "You grow ideas hatched alone into big ones through conversation.", "body": "Any story that starts with \"So I've been thinking\" usually runs a bit long. Trusting your hunches, thinking logically, and adapting to the flow is the core you share in both temperament and character. You test quietly hatched ideas in debate and polish them further. Time alone and time with others both become material for deeper thinking.", "say": "\"What do you think happens if we flip it?\"", "do": "A theory you came up with chatting with friends keeps you testing it at home until midnight.", "worry": "Talking is fun in the moment, but once home you're suddenly drained and don't want to contact anyone. You have so many ideas that you move on before finishing any.", "karai": "You're great at starting debates; how to end one is still under research."}, "INTP>INFJ": {"title": "Answers checked with logic, delivered in the kindest words.", "body": "People who confide in you often leave looking a little lighter. That's because you calmly untangle the cause while choosing words that are easy to receive. Recharging alone and valuing possibilities no one sees yet never changes. Logic and compassion, free thinking and planning ahead: you offer whichever fits the person in front of you.", "say": "\"I think this is the reason. …But you don't have to decide right now.\"", "do": "While listening to a friend, you sort out the cause in your head and quietly hand them a note with a next step.", "worry": "The more you think about someone's feelings, the more you hesitate to give an honest opinion. Wanting to think freely and wanting an answer work at once, so you carry worries for a long time.", "karai": "You solve other people's worries overnight and let your own age for three years."}, "INTP>INFP": {"title": "You can explain what you love with both reasons and tears.", "body": "When a favorite work comes up, analysis and passion start mixing in the same sentence. Valuing time alone, imagining possibilities, and moving gently is the core you share in both temperament and character. With the power to think logically and the power to honor your own values, your passions hold both depth and warmth.", "say": "\"There are three reasons I love it. …No, mostly it just makes me cry.\"", "do": "You copy song lyrics into a notebook and draw your own diagram of what each metaphor means.", "worry": "Feelings that logic can't settle keep turning over in your mind. Choosing between being right and being kind makes your replies slow.", "karai": "You sort out your feelings at the length of a full research paper."}, "INTP>ENFJ": {"title": "To you, who pushes people forward with well-thought-out backing.", "body": "When you say \"You can totally do it,\" there's usually a list of reasons behind it. Relying on hunches and valuing possibilities no one sees yet has always been your thing. Thinking alone and getting energy from a crowd, checking with logic and caring about feelings, free ideas and planning ahead: together they give your bright words real weight.", "say": "\"I've got actual reasons, too. Want to hear them?\"", "do": "The night before mentoring a junior colleague, you sort out their situation alone before meeting them.", "worry": "Encouraging people is fun, so you often cut into your thinking time alone. Between answering feelings and calmly checking what's right, you struggle to find words.", "karai": "In public you're everyone's head cheerleader; at home, a quiet researcher."}, "INTP>ENFP": {"title": "You stretch your curiosity endlessly through the people you meet.", "body": "Meet an interesting person or topic, and your heart and head start moving at once. You're curiosity in human form. Getting excited about unseen possibilities and moving lightly is the same in both temperament and character. Deep solo thinking and diving into groups, checking with logic and staying close to feelings carry that curiosity everywhere.", "say": "\"That's amazing! …So how does it actually work?\"", "do": "At an event you've never been to, you befriend the person next to you and grill them on how their job works.", "worry": "Your interests keep moving, so things you start often stall halfway. On nights after big fun with people, the lack of alone time catches up with you.", "karai": "Your bookshelf has one half-finished notebook for every obsession you've had."}, "INTP>ISTJ": {"title": "You solve free-roaming questions with reliable steps.", "body": "At work, people probably trust you as serious and solid. But in your head, new questions are always moving. Recharging alone and thinking logically are the same in your inborn nature and in how you grew. Free imagination and checking facts one by one, adapting to the flow and sticking to what's decided let you offer ideas with evidence attached.", "say": "\"I'll follow the rules. …Mind if I look into why this step exists?\"", "do": "You handle routine tasks perfectly, then spend spare minutes researching where those tasks came from.", "worry": "Following rules and thinking freely collide, so you tend to feel boxed in. There's so much to verify that you miss the moment to share your idea.", "karai": "When you hear \"there's no precedent,\" you object while getting a little excited."}, "INTP>ISFJ": {"title": "Eyes that catch small changes, and a hand quietly offered.", "body": "When someone seems down, you notice first, quietly think about why, and then gently reach out. Your care follows that order. Recharging in time alone never wavers. Possibilities and the facts in front of you, logic and compassion, flexibility and keeping your word all add up to quiet support.", "say": "\"You haven't been sleeping, have you? Here, this tea helps.\"", "do": "You notice the growing pile of energy drinks on a coworker's desk and quietly take one task off their plate.", "worry": "When you're adjusting to others a lot, you lose time to think at your own pace and get tired. Even when logic says otherwise, you hold back out of consideration.", "karai": "Your care for others gets full marks, but your explanation of your own feelings is always turned in blank."}, "INTP>ESTJ": {"title": "You make the rules and quietly test the upgrade too.", "body": "You set up systems at work for everyone to follow, while trying out the next improved version yourself. That's you. Thinking logically and deciding by reason is a base that doesn't change. Thinking alone and leading people, imagining possibilities and grounding them in facts, experimenting freely and seeing things through let you turn ideas into steps people can use.", "say": "\"This is the most efficient process. Next month, I'll bring a better one.\"", "do": "You write the check-in process for a community bazaar overnight, then tweak it on the spot while watching the line.", "worry": "Leading for too long leaves no room to let your ideas roam, and you feel stifled. You make the rules, yet you're often the one most boxed in by them.", "karai": "The person who writes the most rules is the person who doubts them the most."}, "INTP>ESFJ": {"title": "You bring people together while your mind keeps exploring how things work.", "body": "The one who looks after everyone's feelings and puts the room at ease: that's how people see you. At the same time, a drive to dig into how things work and why is alive and well in the nature you were born with. Because you keep asking why while fitting in with others, your care always hits the mark.", "say": "\"Everyone feeling good about it is what matters. …Also, this way is faster.\"", "do": "After organizing a class reunion perfectly, you go home and start researching something totally unrelated.", "worry": "You don't mind helping people, but without time to think alone, you suddenly run out of room. Some days, after going along with everyone, you lose track of what you actually thought.", "karai": "You nod along with a smile while counting the contradictions in what they're saying."}, "INTP>ISTP": {"title": "You can't help testing with your hands what your head figured out.", "body": "Once you think \"it's probably like this,\" you want to take it apart and check. Moving between thinking and testing brings you closer to the heart of things. Recharging alone, thinking logically, and adapting flexibly are shared by the nature you started with and the one you grew into. Your strength is switching between imagining freely and checking how things feel in your hands.", "say": "\"In theory, it's this. Taking it apart would be faster, though.\"", "do": "You buy a gadget that caught your eye and take it apart before using it, stopping just short of no return.", "worry": "You focus intensely on what interests you and can't touch what doesn't. Explaining your thinking feels like a hassle, so you get misunderstood.", "karai": "You grab the screwdriver before the manual."}, "INTP>ISFP": {"title": "You protect your own pace with both thinking and feeling.", "body": "Behind \"I just like it\" are more reasons than even you can count. Your preferences have that quiet depth. Recharging alone and moving gently with the flow never changes. Curiosity about how things work and savoring the moment, a logical head and a heart that values feelings all work together in front of what you love.", "say": "\"Why does this color combo feel so calming?\"", "do": "You keep going back to your favorite cafe, watching how they brew, and trying it at home.", "worry": "There are times you want to reason and times you just want to feel, so some days your feelings are hard to explain. When someone rushes you, both your thoughts and feelings freeze.", "karai": "You could talk for an hour about why you chose every single thing in your room."}, "INTP>ESTP": {"title": "You move before you think, and think while you move.", "body": "You try first, and if it fails, you stop right away to rethink how it works. People are often surprised by how fast you switch. Thinking logically and adapting to the moment is part of who you've always been. Deep solo thought and moving with people, imagining possibilities and grabbing the facts in front of you connect your action and your analysis.", "say": "\"Let's just try it! …Oh, I think I know why that failed.\"", "do": "You start a new board game with friends and find the winning pattern by the third round.", "worry": "Long stretches of doing things with others leave too little time to sort out your thoughts alone. Some days you second-guess what you decided on momentum.", "karai": "First to jump in, first to find the cheat code."}, "INTP>ESFP": {"title": "A free mind and a bright heart, finding every day interesting.", "body": "Even mid-laugh, you suddenly wonder, \"Why is this happening?\" Fun and curiosity always walk side by side with you. Not being bound by rules and moving with the flow is the same in your inborn nature and in how you grew. Time alone and time shining with people, possibilities and this very moment, logic and feelings: you get to enjoy them all.", "say": "\"Why do you think everyone got so hyped?\"", "do": "After singing your heart out at karaoke, you start looking up how the scoring system works.", "worry": "You need both the fun of being with people and the fun of thinking alone, so planning gets tricky. After riding the mood, the sudden urge to go quiet can catch you off guard.", "karai": "The one who was most hyped is the one philosophizing on the way home."}, "ESTJ>INTJ": {"title": "You plan next week and map the next five years with the same hand.", "body": "\"Next week's to-dos\" and \"the five-year plan\" sit side by side in your notebook. Deciding with logic and looking far ahead runs through both your temperament and your character. You can get a group moving or think deeply alone, check the facts in front of you or picture a future that doesn't exist yet. You use each one as the moment calls for it.", "say": "\"Do you think this job will even exist in three years?\"", "do": "After handing out roles in the meeting, you spend your lunch break sketching a new system by yourself.", "worry": "On days you lead in front of people, you need more alone time than you expect. Choosing between what's solid now and the ideal further out can slow your decisions down.", "karai": "You've got a ten-year plan, but still no idea what's for dinner tonight."}, "ESTJ>INTP": {"title": "Hands that follow the rules, a mind that questions them.", "body": "Somehow, the job of slowly improving old ways of doing things keeps landing on you. Judging things by logic is the ground that both your temperament and your character stand on. You can rally people to follow the steps, and you can dig alone into why things work. You have a steady hand for facts and an eye for other options, plus the drive to decide and the room to keep thinking.", "say": "\"Wait—wouldn't this go faster if we flipped the steps?\"", "do": "You follow the work manual step by step while filling its margins with tiny notes on how to improve it.", "worry": "The urge to conclude fast and the sense that you haven't thought enough collide, and you get impatient with yourself. Your people days and hide-away days differ so much that planning your week is tricky.", "karai": "While you were redesigning the system, the deadline for the original task quietly passed."}, "ESTJ>ENTJ": {"title": "You take last year's numbers and make a bold bet on next year.", "body": "People are puzzled that you can be so careful and so bold at once. Getting energy from people, deciding with logic, and moving with a plan match exactly in your temperament and your character. The difference is how you see things: you trust proven facts and past results, and you also bet on new possibilities. So a safe plan and a daring leap end up in one proposal.", "say": "\"Here's last year's number. So this year, let's change the whole approach.\"", "do": "For the neighborhood festival, you perfect the usual schedule and then quietly slip in one brand-new event.", "worry": "Torn between the comfort of what's worked before and the urge to change things in a big way, you redo the math again and again. Others seem slow, so you tend to carry it all yourself.", "karai": "By the time you suggest talking it over, the conclusion slide is already finished."}, "ESTJ>ENTP": {"title": "A cheerful inventor who also asks, \"So who's doing what, by when?\"", "body": "In meetings you toss out ideas that surprise everyone, then wrap up by pinning down deadlines and owners. Getting energy from people and deciding with logic is the steady part shared by your temperament and your character. You can build a plan on facts, and you can change course on a sudden spark. Fun and reliability really do fit in the same meeting.", "say": "\"Love that idea! Let's lock in the budget and deadline right now.\"", "do": "At a product brainstorm, you write ten ideas on the whiteboard, narrow them to three yourself, and draw up a timeline.", "worry": "Wanting to stick to the plan and wanting to try something new take turns, so your direction wobbles. When someone asks, \"So which is it?\" you're not quite sure what to say.", "karai": "You have three proposals going, and you cheated on each one halfway with the next idea."}, "ESTJ>INFJ": {"title": "Looks like the planner, but notices every small wobble in people's hearts.", "body": "At work people see you as \"the organized one,\" yet you notice exactly who is pushing too hard and where. Moving forward with a clear plan is the ground both your temperament and your character share. You have drive and quiet depth, an eye for facts and an eye for the future, logic and a feel for emotions. With that many different strengths, you simply see more.", "say": "\"Has anyone seemed down lately?\"", "do": "While putting the progress chart together, you stick a little personal note on it for each team member.", "worry": "You replay decisions made for efficiency, wondering if they hurt anyone. The more you take on roles surrounded by people, the less time you have to reset alone.", "karai": "You can worry about everyone, yet you're the very last to notice you're tired."}, "ESTJ>INFP": {"title": "You give quiet ideals a deadline and make them come true.", "body": "It starts with caring and ends with getting it done. That's your usual flow. Your temperament and your character point in different directions on all four sides. So you can rally people or think in quiet, build on facts or let your imagination grow, decide with logic or trust your heart's \"yes,\" plan ahead or go with the flow.", "say": "\"This is going to be great. Okay, let's get this far by Friday.\"", "do": "A hobby you started just for fun has somehow turned into a full project with a chart and deadlines.", "worry": "You want to honor your feelings, yet you catch yourself measuring yourself by efficiency and results. The things you love most are the ones you push hardest on, and the tiredness piles up.", "karai": "You were talking about your dream, and three minutes later there are owners and due dates."}, "ESTJ>ENFJ": {"title": "A detailed practice plan, with a word of encouragement beside it.", "body": "When you lead a team, you build a detailed practice plan and also prepare words that lift each person up. Getting energy from people and moving with a plan is a strength found in both your temperament and your character. Your straight, fact-and-logic judgment and your belief in people's feelings and potential come from different places. That's why your strictness always carries hope for others.", "say": "\"I really believe you all can do this.\"", "do": "Training a junior, you hand over the manual along with a letter listing three things they're great at.", "worry": "Wanting to say what's right and not wanting to hurt anyone collide, so choosing your words takes time. The harder you try to live up to expectations, the fewer places you have to admit you're struggling.", "karai": "Even your pep talks are prepared right on schedule."}, "ESTJ>ENFP": {"title": "You laugh at the center of the party, then run the cleanup.", "body": "At events you're the center of the fun, and before long you're also directing the cleanup. Getting more energy the more you're with people is the steady part your temperament and your character share. Everything else is wonderfully mixed: careful facts and fresh ideas, logic and heart, planning ahead and enjoying the moment. You have all of them.", "say": "\"Let's all go, it'll be so fun! …Oh, I'll send the meeting time later.\"", "do": "A hobby group you started on a whim somehow now has proper rules and an attendance sheet.", "worry": "Torn between jumping into fun and keeping your promises, you feel a little tug whichever you choose. After acting on a whim, you sometimes blame yourself for not being more careful.", "karai": "You've made a fairly detailed schedule for living freely."}, "ESTJ>ISTJ": {"title": "Explaining in front of everyone, finishing before anyone else.", "body": "You explain the steps to everyone, then finish your own part accurately before anyone else. That sight puts people at ease. Relying on facts, deciding with logic, and moving with a plan flow steadily through your temperament and your character alike. Only your energy source differs, so you can lead from the front or finish quietly alone, with the same quality anywhere.", "say": "\"That's the process. No questions? Then I'll get started.\"", "do": "You assign moving-day jobs to the whole family, then pack up the bookshelf by yourself without asking anyone for help.", "worry": "You're glad to be trusted with bringing people together, but afterward you're wiped out and want to be alone. Some days you wonder whether people can keep up with how thorough you are.", "karai": "\"It's faster if I just do it myself\" has become your catchphrase."}, "ESTJ>ISFJ": {"title": "In charge of the family calendar and Grandma's favorite dishes.", "body": "At family events, somehow you're the one who makes the schedule and remembers Grandma's favorite food. Valuing facts and experience and moving with a plan is ground your temperament and your character share. Leading people and tidying things carefully alone, judging with straight logic and caring for feelings come from different places, yet you use them all naturally.", "say": "\"I saved Grandma the seat by the window.\"", "do": "At a family gathering, you make the seating chart and quietly make sure people who don't get along aren't side by side.", "worry": "Even when you should speak up, you swallow your words for the other person's sake, then think, \"I should have said it.\" When people keep relying on you, your own rest gets pushed back.", "karai": "You've noted everyone's favorites, but freeze when asked what your own favorite food is."}, "ESTJ>ESTJ": {"title": "\"Who, what, and by when?\" comes out of your mouth naturally.", "body": "When you ask, \"Who's doing what, by when?\" most things start moving. Your temperament and your character are the same, so working with people, checking facts, deciding with logic, and following the plan run through you in one straight line. That's why people rely on you without a second thought. Where your way fits, you get big results; where it doesn't, you get tired without knowing why.", "say": "\"So when's the deadline?\"", "do": "For the year-end cleaning, you tape a sheet to the fridge listing each family member's area and finish time.", "worry": "When others move slowly, you end up taking it all on. Some days you mean to say the right thing, it lands as harsh, and you feel low.", "karai": "Even your days off have quietly turned into \"today's tasks.\""}, "ESTJ>ESFJ": {"title": "An organizer who runs things tight, yet never comes off cold.", "body": "Put you in charge of a dinner and you keep the budget and time on track, and even arrange gifts for those who couldn't come. Getting energy from people, valuing facts, and moving with a plan match perfectly in your temperament and your character. Only how you decide differs: you move between straight logic and care for everyone's feelings. That warmth is why you never seem cold.", "say": "\"It's thirty dollars each, two hours. …Oh, I already ordered the farewell flowers.\"", "do": "After making a fair duty roster at work, you quietly swap shifts with someone who looks unwell.", "worry": "You want to make a fair call, but when someone looks disappointed you can't decide. You pay so much attention to everyone that you only notice your own tiredness afterward.", "karai": "Strict about the rules, softest of all toward anyone in trouble."}, "ESTJ>ISTP": {"title": "A mouth giving directions, and hands already holding the tools.", "body": "When trouble hits, you give everyone directions, and somehow you're already holding the tools yourself. Relying on facts and deciding with logic is the steady part running through both your temperament and your character. You can push a plan forward in front of people or work quietly with your hands, enjoy the safety of a set plan or adapt on the spot. Words and hands, you fix it both ways.", "say": "\"Eh, if it breaks, we'll figure it out on site.\"", "do": "You read the furniture instructions carefully, then halfway through switch to your own method and finish faster.", "worry": "You want a plan and you don't want to be tied down, so each new appointment makes you hesitate. After leading people, you go quiet and want to tinker with machines alone.", "karai": "You do read the manual. You just never tell anyone you read it."}, "ESTJ>ISFP": {"title": "Precise on weekdays, tending pottery and plants on weekends.", "body": "At work you're precise, yet on days off you take your time caring for favorite dishes and plants. People find it surprising, but valuing real facts and how things feel is a trait your temperament and your character share. You can move in a group or savor time alone, decide with logic or choose by feeling, plan ahead or follow your mood. That careful touch shows up everywhere.", "say": "\"Oh, I love the color of this cup.\"", "do": "In your balcony garden, you keep a watering log while agonizing over which flower colors go together.", "worry": "Quick decisions and slow, feeling moments swap places all day, and switching wears you out. Even with things you love, you think \"I have to do this right,\" and some of the fun slips away.", "karai": "Even during your relaxing time, you're counting exactly how many minutes you've rested."}, "ESTJ>ESTP": {"title": "A detailed game plan, and quick calls to win it live.", "body": "Before the game you set a detailed strategy, yet in the moment you read your opponent and pick the best move on the spot. Getting energy from people, seeing facts, and deciding with logic are exactly the same in your temperament and your character. Your pace is what differs: you can plan far ahead and switch moves in an instant. Because you prepared, you can change boldly.", "say": "\"This is the plan. …But if they switch it up, we'll adjust then.\"", "do": "You write a barbecue shopping list, then spot a sale at the store and change the whole menu.", "worry": "Wanting to stay on schedule and wanting to act the moment an idea hits mean you undo your own decisions. When someone asks, \"What was the point of the plan?\" it stings a little.", "karai": "You make schedules fast, and rewrite them even faster."}, "ESTJ>ESFP": {"title": "You run every part of the prep, then sing loudest at the party.", "body": "At family birthday parties, you run all the prep and then sing the loudest on the day. Getting energy from people and valuing what's real in front of you is the unchanging part of both your temperament and your character. Your logical, by-the-plan drive and your bright knack for making things fun come from different sides. Seriousness and cheer live happily in the same place.", "say": "\"Hey, want to make something out of these balloons?\"", "do": "After assigning cleaning duties, you put on music and get everyone dancing while you tidy up.", "worry": "The harder you try to meet your responsibilities, the less room you have to enjoy yourself. Choosing between pleasing people and keeping things on track makes you most careful at the happiest events.", "karai": "You play both the hype person and the host, then burn out completely on the way home."}, "ESFJ>INTJ": {"title": "You quietly tuck kindness inside your cool, logical plans.", "body": "You may look cool at first, but your plans always include care so that no one gets stuck. Moving forward steadily with a plan is ground your temperament and your character share. You can warm up a group or think deeply alone, value facts or picture possibilities, read feelings or decide with logic. With so many different strengths, you have plenty to draw on.", "say": "\"This is the most efficient way. …But I'll help you until you get used to it.\"", "do": "While charting the family's future plans, you make sure everyone's birthdays are written in too.", "worry": "After finding the logical answer, you worry it might leave someone feeling lonely. You have waves of wanting people and wanting solitude, and turning down invitations pricks your conscience.", "karai": "Right after a calm analysis, you check your phone three times to see how they reacted."}, "ESFJ>INTP": {"title": "An explorer who always puts well-reasoned answers to use for others.", "body": "Even as you say, \"Logically, it works like this,\" part of your mind is checking that no one will be troubled by it. Your temperament and your character point in different directions on all four sides. You have warmth in groups and quiet focus alone, trust in experience and curiosity about possibilities, care for feelings and a logical mind, a knack for planning and room to keep thinking.", "say": "\"Logically, it's this. As long as it doesn't cause anyone trouble.\"", "do": "Hearing that a group schedule isn't working out, you quietly figure out the best combination and then gently share it.", "worry": "You need time to think alone, but you can't say no when someone relies on you. After giving the right answer, there are nights you lie awake wondering if you hurt them.", "karai": "You said \"I'm not bothered,\" and you're the one still bothered the longest."}, "ESFJ>ENTJ": {"title": "You remember the big goal and everyone's birthday at the same time.", "body": "When you lead a team, you set big goals and still remember every member's birthday. Getting energy from people and moving with a plan is the steady part your temperament and your character share. You have grounded respect for facts and a vision that looks far ahead, a heart for others and logic to decide. You watch the numbers and the faces with equal care.", "say": "\"Here's our sales target. But first, shall we all grab lunch?\"", "do": "While writing a big project plan, you've already booked the restaurant for the wrap party.", "worry": "You want to decide quickly, but if someone looks unhappy you can't push it through, and later you wish you'd been clearer. Chasing both results and being liked wears you out.", "karai": "Strict about targets, yet you spend an hour choosing snacks for the team."}, "ESFJ>ENTP": {"title": "Easing the mood, then casually offering the idea nobody thought of.", "body": "In discussions, you say \"This might sound weird, but...\" and then casually offer the idea nobody else had. Getting more energy the more you're with people is what your temperament and your character share. You switch, as needed, between trusting experience and fresh sparks, kindness and logic, careful planning and changing on the fly.", "say": "\"What if we looked at it backwards?\"", "do": "As organizer of the class reunion, you keep the usual program and somehow add a quiz contest.", "worry": "You want to share your idea but don't want to spoil the mood, so you hesitate over when to speak. Sometimes a debate gets too fun, and after winning it you lie awake worrying.", "karai": "You started arguing for their sake, and halfway through you're just enjoying the debate."}, "ESFJ>INFJ": {"title": "You think about a friend's smile five years from now.", "body": "When friends come to you for advice, you help in practical ways while also thinking, \"What would keep this person smiling five years from now?\" Valuing feelings and moving with a plan is your core, shared by your temperament and your character. You draw energy from people and settle your heart alone, see the facts and picture someone's future. All of it goes into supporting others.", "say": "\"I really think there's a place that suits you even better.\"", "do": "Helping a friend change jobs, you gather listings for them and hand over a handwritten note of encouragement.", "worry": "Because you want so much to help, you carry other people's worries as if they were your own. You love lively gatherings, yet you're puzzled by how suddenly you want to be alone once they end.", "karai": "You think so carefully about others' futures, but your own next week is still blank."}, "ESFJ>INFP": {"title": "Great at caring for others, with one secret dream kept close.", "body": "You take good care of everyone while nurturing a precious dream you show no one. Fewer people know about it than you might think. Deciding by what matters to people's hearts is a trait your temperament and your character share. You can move in a group or deepen your thoughts alone, rely on experience or let imagination grow, follow the plan or go with your feelings.", "say": "\"You can keep eating—there's just something I'd like you to hear.\"", "do": "After neatly managing the family schedule, you write long entries in your diary alone at night.", "worry": "When others' expectations and what you care about drift apart, either choice hurts a little. After going along with others, your heart can't catch up without some time alone.", "karai": "You tell others \"Do whatever you like,\" but can't say it to yourself."}, "ESFJ>ENFJ": {"title": "Running the yearly festival while picturing the town ten years on.", "body": "In community work, you run each year's events with care while wondering, \"How do we keep people coming to this town ten years from now?\" Getting energy from people, deciding with heart, and moving with a plan are the same in your temperament and your character. Only your outlook differs, and your respect for facts and your belief in possibilities always work together.", "say": "\"Thanks for helping again this year! …Next year I'd love an event where the kids are the stars.\"", "do": "As a parents' group officer, you sort last year's records while also writing a proposal for something new.", "worry": "You love helping so much that before you know it you've taken on too many roles. Because you want to meet everyone's hopes, you're hard on yourself when things go wrong.", "karai": "\"Don't push yourself\" is your catchphrase, yet you're the one pushing hardest."}, "ESFJ>ENFP": {"title": "You book the usual place, then plan the next fun on the way home.", "body": "People often say you're the one who books the usual place, then on the way home asks, \"Want to try that new spot next time?\" Getting energy from people and deciding with heart is the part that stays the same in your temperament and your character. You can use both grounded experience and excitement for the new, sticking to plans and following your whims.", "say": "\"Did you know a new café opened by the station?\"", "do": "You keep up every yearly tradition while adding one new game each time to surprise the family.", "worry": "Ideas keep coming, but your responsibilities weigh on you too, so both feel half-done. Trying so hard to please everyone, you push back the things you were looking forward to.", "karai": "You keep your planner neatly, but choosing the stickers for it takes the longest."}, "ESFJ>ISTJ": {"title": "Accurate paperwork, handed over with a throat drop on top.", "body": "Your work is precise and trusted, and you're the first to notice someone struggling and check on them. Valuing facts and experience and moving with a plan is the steady part your temperament and your character share. You have warmth that brightens a group and focus to work quietly alone, a caring heart and a logical mind. Together they make you dependable and kind.", "say": "\"Paperwork's checked. …More importantly, you look pale. Are you sleeping?\"", "do": "After filing your expenses exactly by the rules, you quietly leave a throat drop on a coworker's desk.", "worry": "When following the rules clashes with helping the person in front of you, you agonize alone for a long time. You value people, yet without quiet time alone, your tiredness won't go away.", "karai": "People call you strict about rules, but you're actually the easiest to sway with feelings."}, "ESFJ>ISFJ": {"title": "Happy in the spotlight or behind the scenes, either way.", "body": "In front of everyone you run things with a smile, and behind the scenes you finish the small prep no one notices. Relying on experience, valuing feelings, and moving with a plan are the same in your temperament and your character: they're your core. Only your energy source differs, so you can gain energy in a crowd or tidy things carefully alone.", "say": "\"If anyone's cold, I brought lap blankets.\"", "do": "Hosting the office welcome party, you emcee cheerfully after checking in advance which foods the new hire can't eat.", "worry": "Helping others has become so normal that you're late to notice your own tiredness. Saying no is hard, so favors quietly pile up.", "karai": "You remember every \"thank you,\" but can't recall the last day you took off."}, "ESFJ>ESTJ": {"title": "Deciding on time, and catching the voice that almost spoke.", "body": "You end meetings right on time, then quietly reach out to anyone who didn't get to speak. That role suits you at school groups and at work alike. Getting energy from people, valuing facts, and moving with a plan are exactly the same in your temperament and your character. Only how you decide differs, as care for feelings and straight logic work side by side.", "say": "\"Then we'll go with this plan. …You were about to say something earlier, weren't you?\"", "do": "After dividing up the chores fairly, you take on a tired family member's share with \"Just for today.\"", "worry": "After making the right call, you worry whether it hurt anyone. Be direct or wrap it gently—you go back and forth depending on who you're talking to.", "karai": "Five minutes after a stern warning, you're running out to buy their favorite snack."}, "ESFJ>ESFJ": {"title": "You've grown kindness into one straight, sturdy trunk.", "body": "\"Has everyone eaten?\" comes out of you naturally wherever you are. Your temperament and your character are the same, so getting energy from people, learning from experience, and moving smoothly while caring for feelings run through you without wavering. That care has warmed rooms and connected people. It's also why you shine where you're thanked and wear down fast where it's cold.", "say": "\"Let me know if there's not enough.\"", "do": "You keep every friend's birthday on your calendar and never miss sending a message.", "worry": "Being sensitive to reactions, a little coldness can bother you all day. Often your tiredness comes not from weakness but from places where kindness isn't returned.", "karai": "You remember everyone's favorite drink, then forget to order your own."}, "ESFJ>ISTP": {"title": "Before the comforting words, you've already opened the toolbox.", "body": "When a friend is in trouble, you've started fixing their broken bike before saying a single comforting word. Valuing real facts and experience is the steady part your temperament and your character share. You have warmth for a group and focus with your hands, a caring heart and a logical mind, comfort in a set plan and ease adapting on the spot. Your kindness comes out through your hands.", "say": "\"Here, let me see. I think it's fixable right here.\"", "do": "You were chatting with relatives, and the next thing anyone knows, you're alone fixing the kitchen leak.", "worry": "Wanting closeness and wanting to do your own thing take turns, and even you can't predict your moods. Saying feelings out loud feels awkward, so you wonder if your actions got the message across.", "karai": "When someone says \"thank you,\" you get shy and change the subject to tools."}, "ESFJ>ISFP": {"title": "After caring for everyone, you slip away into your favorite scents.", "body": "You're great at looking after everyone, yet you treasure nothing more than time surrounded by scents and music you love. Valuing what's real and deciding with heart is a trait your temperament and your character share. You have brightness in a group and calm in solitude, the ability to plan and the ease to follow your mood. Both kinds of time make you who you are.", "say": "\"When we're done, I'm going to sneak off for a cup of tea alone.\"", "do": "When friends come over, the menu is set days ahead, but the table flowers are chosen by your mood that morning.", "worry": "Going along with others, there are moments you lose track of what you like. You want a clear plan, but when your mood isn't in it you can't move, and you blame yourself.", "karai": "Plans for others: packed. Plans for yourself: \"if I feel like it.\""}, "ESFJ>ESTP": {"title": "\"Is everyone okay?\"—and right away, the next move.", "body": "When plans fall apart, you calm everyone down and have already found another way. Getting energy from people and valuing the facts in front of you is the unchanging part of your temperament and your character. Your care for feelings and your crisp logic, your planning and your quick read of the moment come from different sides.", "say": "\"Trains are down? Okay, let's call two cabs, right now.\"", "do": "You'd prepped the event perfectly, then saw rain that morning and switched to an indoor venue right away.", "worry": "Acting from care and wanting to decide quickly collide, so you watch that your words don't come out sharp. Torn between sticking to the plan and changing it, you keep mulling it over even after deciding.", "karai": "While worrying about everyone, you're secretly itching to move on to the next thing."}, "ESFJ>ESFP": {"title": "Perfect reservations, then a spur-of-the-moment detour and the biggest laugh.", "body": "You take care of bookings and messages ahead of time, then on the day you take a fun detour and laugh the most. Getting energy from people, valuing what's real, and deciding with heart line up in your temperament and your character. Only your pace differs: you can plan far ahead and also flow with the mood. Because you prepared, you can let loose.", "say": "\"I booked the restaurant for six! …But first, want to stop by that crêpe stand?\"", "do": "At your kid's sports day, you bring the perfect lunch and picnic blanket, then cheer louder than anyone.", "worry": "Torn between preparing properly and enjoying the moment, you feel a little uneasy whichever you pick. Putting everyone's fun first, you realize later that you're running on empty.", "karai": "You're the organizer, the most excited one there, and you nearly leave without settling the bill."}, "ISTJ>INTJ": {"title": "Using old records to map out the next ten years.", "body": "Do ideas about the years ahead come to you while you reread old files? Thinking things through alone, deciding with logic, and keeping to a plan never change for you. They're your steady ground. You also mix the care to stack up checked facts with the imagination to picture a future that has no shape yet, so people lean on you for long-term plans.", "say": "\"Could I see last year's numbers again? It's for the three-year plan.\"", "do": "You've kept years of household budgets, and built your own plan from them all the way to retirement.", "worry": "Stick with the usual way, or switch to something new? You can take a long time to decide. With caution and foresight running at once, your head is always a little crowded.", "karai": "Your ten-year plan is flawless. Tonight's dinner is still a blank page."}, "ISTJ>INTP": {"title": "Following the steps, but always asking \"Why, though?\"", "body": "\"Wait, why is it done this way?\" That question pops up even while you're reading a manual. Thinking quietly on your own and judging by logic stay the same, no matter what. You move between the care to build on facts and the curiosity to chase ideas, between keeping to the steps and rethinking them on the spot. Your detours often bring back answers no one expected.", "say": "\"The steps are right. I just wonder why they're in this order.\"", "do": "You meant to read the manual line by line, and somehow you're now researching how the whole product works.", "worry": "Wanting to follow the rules and wanting to try a better way can collide, and your hands stop. Thinking is so fun that the deadline sneaks up and suddenly you're in a rush.", "karai": "Your research detours run so long it takes five minutes to remember what you were looking up."}, "ISTJ>ENTJ": {"title": "The one who read every page, then calls the play.", "body": "At meetings, you've read the materials more closely than anyone, and you're the one who wraps up with \"Okay, here's how we'll move.\" That's how people see you: a leader they can count on. Deciding with logic and moving with a clear plan are always at the center of who you are. You switch between quiet focus and the drive to get a room moving, between nailing down facts and dreaming up big goals.", "say": "\"I've checked every number. So next year, let's aim higher.\"", "do": "You fire up the team around a shared goal, then go home and quietly update the progress chart by yourself.", "worry": "Because you look so dependable in front of others, your time to rest alone keeps getting pushed back. You often go back and forth on whether to play it safe or go bold.", "karai": "The person who said \"Let's all work on this together\" is the one carrying the most alone."}, "ISTJ>ENTP": {"title": "Pitching new ideas, with a budget sheet hidden behind them.", "body": "It looks like you're just tossing out ideas, but by that night you've checked them against the numbers. That's your surprising side. Thinking things through with logic stays the same in every situation. Quiet time alone and warm time with people, the caution to trust facts and the spark to widen what's possible, keeping a plan and changing course lightly. You play all of these cards to turn one idea after another into something real.", "say": "\"How about this? Fun, right? …Oh, and I already did the budget.\"", "do": "An idea pops up in casual chat, and by that night you've put it in a spreadsheet to see if it can actually work.", "worry": "You come up with so many ideas that picking which one to really pursue wears you out. Some days you crave a lively crowd, other days you can't face anyone, and the swing catches even you off guard.", "karai": "You start a debate on purpose, then spend the walk home fact-checking your own arguments."}, "ISTJ>INFJ": {"title": "A listener who lights the way with plans and kindness.", "body": "When someone comes to you for advice, you first sort out the situation as if writing it on paper. Then you gently shine a light on what they want most. That's the kind of listener you are. Calming your mind in time alone and preparing with the future in view never change. You hold steady fact-checking and a feel for deeper meaning, cool logic and warm care, in both hands.", "say": "\"Okay, I get the situation. So what do you want to do?\"", "do": "While listening to a friend's problem, you're mapping out the steps to solve it and the order of the words you'll say, both at once.", "worry": "When the right answer and the kind answer are different, choosing can keep you up at night. You pour so much into preparing for others that sharing your own feelings always comes last.", "karai": "You're great at tidying up other people's hearts, but yours is covered in sticky notes."}, "ISTJ>INFP": {"title": "Writing secret poems into a well-kept daily schedule.", "body": "You finish what needs doing by the deadline, yet lose all sense of time in anything that moves your heart. You have a quiet passion. Recharging in time alone stays the same, always. Steady trust in experience and a vivid imagination, calm logic and gentle care for feelings, keeping your plans and going with the flow all live together in you, with no strain.", "say": "\"I'll get it done. …But this one thing, I just can't give up.\"", "do": "You write in your journal at the same time every day, and now and then slip in a poem no one will ever see.", "worry": "\"I should do it properly\" and \"I want to do it my way\" can show up together, and some days you can't commit to either. When your head agrees but your heart won't follow, you're hard on yourself.", "karai": "You've written a three-page plan for living freely."}, "ISTJ>ENFJ": {"title": "Handing over a pep talk with a step-by-step note attached.", "body": "\"You can do this.\" When you say it, there's always research and preparation behind it. Making a plan and seeing it through is a strength that holds in every setting. Calm focus alone and bright energy with people, an eye for facts and faith in what's possible, clear logic and a kind heart. Because you can use all of them, you're great at helping people move forward.", "say": "\"You've got this. …And here's a note with the steps, just in case.\"", "do": "You sit through a junior coworker's practice presentation, clap loudly, and then hand them a list of questions they might get.", "worry": "The harder you work to meet everyone's hopes, the less quiet time alone you get. You often struggle to decide when feelings come first and when the rules should.", "karai": "You're amazing at encouraging others, but the only pep talk you give yourself is \"Not good enough yet.\""}, "ISTJ>ENFP": {"title": "Bursts of inspiration and slow, steady effort: an unlikely duo.", "body": "You jump into a new hobby on a whim, and somehow you're the one who keeps it up the longest. That's very you. Your inborn temperament and the character you grew into point in different directions on all four sides. Recharging alone and having fun with people, building on facts and catching sparks, deciding with logic and reading feelings, keeping plans and riding the flow: you have every one of them.", "say": "\"This is going to be so fun! Want to see my notes from last time?\"", "do": "You started a balcony garden on a whim, and you log the watering every single morning.", "worry": "New things excite you, but too much change in a row suddenly drains you. Some days, after acting on a whim, you scold yourself with \"I should have been more careful.\"", "karai": "You say you decided \"just for fun,\" yet your prep afterward is the most thorough of anyone's."}, "ISTJ>ISTJ": {"title": "Someone who has kept their word, steadily, all along.", "body": "You arrive ten minutes early, and anything you're asked to do is done the day before it's due. That honesty is rooted the same way in the temperament you were born with and the character you grew into. Checking facts one by one and finishing what you start is part of you, through and through. You shine where steps matter, and in places where everything is decided on a whim, you wear out without knowing why.", "say": "\"Let me check last time's records, and then I'll get back to you.\"", "do": "You keep a list of what's in the fridge, sorted by which expiration date comes first.", "worry": "Sudden changes of plan or vague instructions, one after another, wear you out badly. That's not a weakness. It's usually a sign you're stuck in a way of doing things that doesn't fit you.", "karai": "Asked to \"play it by ear,\" you start writing a manual for it."}, "ISTJ>ISFJ": {"title": "Known at work and at home as \"the one who makes us feel safe.\"", "body": "At work and at home, people probably tell you, \"It's such a relief when you're here.\" Recharging alone, trusting facts, and moving with a plan haven't changed one bit over the years. You also have both the logic to judge fairly and the warmth to care about how others feel. So your work is precise, and you still quietly lend a hand to anyone who's struggling.", "say": "\"One date on this form was off by a day. …I went ahead and fixed it.\"", "do": "You keep the team schedule perfectly accurate, and quietly lighten the load for anyone who seems unwell.", "worry": "When you should speak up about what's right, worry about hurting someone makes you swallow your words. As you keep taking on requests, your own breathing room slowly disappears.", "karai": "You fix other people's mistakes so quietly that they never find out they made one."}, "ISTJ>ESTJ": {"title": "Prep alone, lead with confidence: a host people trust.", "body": "People trust you: \"If they're in charge, it'll run smoothly.\" Trusting facts, deciding with logic, and sticking to the plan are strengths that have never changed. You prepare quietly on your own, then on the day you step up, speak out, and get everyone moving. Time to recharge in quiet and time to shine with people both belong to you.", "say": "\"Today's plan has three parts. When we're done, let me have a little quiet time to sort things out.\"", "do": "You run the neighborhood event without a hitch, then go home and write down what to improve in a notebook, without talking to anyone.", "worry": "The more people rely on you, the more you're out in front, and your quiet time alone gets cut down. On days you were too strict with someone who was sloppy, you quietly go over it afterward.", "karai": "You preach that rest is part of the job, and there's not one day off on your own calendar."}, "ISTJ>ESFJ": {"title": "A planning pro who even makes the seating chart, with care.", "body": "At family gatherings, you've sorted out the schedule, the budget, and the seating, and on top of that, you remember what each person likes. That's how well you prepare. Valuing experience and facts and moving with a plan stay the same, always. You move between quiet thinking and the energy you get from people, between clear logic and real warmth, depending on the moment.", "say": "\"The plan for the day is final. Oh, and Tanaka doesn't do spicy food, right?\"", "do": "For a coworker's farewell gift, you compare three options within budget, then have it wrapped in their favorite color.", "worry": "While looking after everyone, your time alone vanishes and suddenly you're drained. You often feel stuck between wanting people to follow the rules and not wanting to blame anyone.", "karai": "You know everyone's food likes and dislikes, but when someone asks what you want to eat, you can't answer."}, "ISTJ>ISTP": {"title": "Fixing it now, and getting ready for next time.", "body": "When trouble hits, you don't panic. You fix it fast with whatever's on hand. But you don't stop there: you set things up so it won't happen again. Valuing time alone and thinking things through with facts and logic don't change, whatever comes up. You switch naturally between careful planning ahead and the lightness to change your approach as things unfold.", "say": "\"I patched it for now. …I'll update the manual so it doesn't happen again.\"", "do": "You quickly fix a broken piece of furniture with your own tools, and order spare parts that same night.", "worry": "Some days you want to follow the plan, other days you want to go with your mood, so it's hard to find your own pace. You hate being tied down by rules, yet you feel uneasy without any.", "karai": "\"It'll work out,\" you laugh, with a backup for your backup in your bag."}, "ISTJ>ISFP": {"title": "A careful routine, finished with a single seasonal flower.", "body": "You measure every ingredient exactly, yet on a cold day you add a little extra ginger. Your kitchen shows who you are. Recharging in time alone and treasuring what you can see and touch stay the same, always. You blend calm logic with gentle care, and keeping your plans with going with the flow, in just the right amounts.", "say": "\"It's cold today, so I added some ginger.\"", "do": "You clean your room on the same day every week, without fail, and finish by setting out a single seasonal flower.", "worry": "\"I should do it properly\" and \"I want my own pace\" live side by side, and some days you feel stuck in between. Putting your feelings into words is hard, and it's frustrating when they don't come across.", "karai": "The day off you meant to spend lazily is somehow full of laundry and grocery plans."}, "ISTJ>ESTP": {"title": "Packing a first-aid kit before rushing off.", "body": "When it counts, your body moves before anyone else's. People see you as a doer, but behind each call are years of experience and homework. Trusting the facts in front of you and judging by logic have never changed. You have both the calm to prepare alone and the drive to jump in with people, the care to keep plans and the speed to switch gears.", "say": "\"Okay, let's go right now! I already checked the route in case it rains.\"", "do": "At a barbecue you and your friends threw together on a whim, you somehow showed up with a first-aid kit and extra charcoal.", "worry": "Wanting to go with the flow and wanting to be ready so nothing goes wrong can clash, and you get tired before you even decide. After a lively time, you feel off unless you get quiet time alone.", "karai": "Momentum is everything, you say, yet you've already checked how to build it."}, "ISTJ>ESFP": {"title": "The first to party, and the first to check the last train.", "body": "You light up the room, but you've still got the important parts covered, like when to head home and how to split the bill. That's why people feel safe having fun with you. Valuing real facts and experiences hasn't changed since you were young. Recharging alone and bringing the party, clear logic and kind warmth, keeping plans and enjoying the moment: you have them all.", "say": "\"Today is so much fun! …So the last train's at 11:12, we should go soon.\"", "do": "You were the life of the karaoke party, yet ten minutes before the end you'd already split the bill for everyone.", "worry": "The more fun you've had, the more you need time alone afterward, and the gap surprises even you. You want to just enjoy yourself, yet you catch yourself thinking about what's next or what it costs.", "karai": "You were the wildest one there, and on the way home you're already checking tomorrow's schedule."}, "ISFJ>INTJ": {"title": "Planning ten years ahead for the people you love.", "body": "You seem gentle and modest, but you're actually thinking further ahead than anyone. That's your surprising side. Calming your mind in time alone and moving steadily with a plan never change. An eye for everyday facts and the power to picture unseen possibilities, kindness that reads feelings and the calm to reason things out. With both, you quietly try to protect people's futures, years ahead.", "say": "\"With that plan, I think you'll have trouble in six months. I don't want things to get hard for you, so I'm telling you now.\"", "do": "You remember every family member's birthday, and you've made a chart of anniversaries and savings for the next ten years.", "worry": "Even when you have an opinion you know is right, it takes you a while to say it, because you think about how the other person will feel. You think so far ahead that you can miss the fun right in front of you.", "karai": "You spend three days rewording one tough-love comment into the gentlest version possible."}, "ISFJ>INTP": {"title": "Starting out to help, ending up an expert in how it works.", "body": "\"Let me look into it.\" When you say that, it usually starts with someone's problem, and before long you've reached the deep workings of the whole thing. Recharging in time alone is your steady ground. You go back and forth between trusting experience and chasing new ideas, between caring warmth and cool logic, between preparing well and rethinking freely.", "say": "\"You seemed stuck, so I looked it up. …By the way, the way this works is so interesting.\"", "do": "You set out to fix a friend's glitchy laptop, and you're still digging into the cause at midnight.", "worry": "Sometimes you hold back an answer you reached with logic, worried it might hurt someone. When you're lost in thought, you can forget something you were asked to do, and feel bad about it later.", "karai": "The research you started for someone else has quietly turned into your new hobby."}, "ISFJ>ENTJ": {"title": "A leader who gives the orders, then hands out snacks.", "body": "After making a tough call firmly, you go around and quietly check in with each person. To the people around you, you're a caring leader. Moving with a plan and getting things done never change, whatever your role. You have it all: quiet calm and the drive to lead, an eye for everyday facts and big-picture goals, gentle care and the strength to decide with logic.", "say": "\"This is the direction we're going. Oh, and thanks for staying late yesterday.\"", "do": "You give clear directions in the meeting, then hand out snacks to anyone who looks tired afterward.", "worry": "After saying clearly what needs to be decided, you worry alone: \"Did that sound too harsh?\" The more you lead, the less quiet time you get to rest.", "karai": "The same night you gave orders like a pro, you're holding a review meeting in bed about how you said them."}, "ISFJ>ENTP": {"title": "Flipping the rules upside down to make life easier for someone.", "body": "You love questioning the usual way and coming up with new ones. But your debates aren't meant to tear anything down. They're meant to make things easier for someone. Your inborn temperament and the character you grew into point in different directions on all four sides. Quiet support and lively talk, valuing experience and widening ideas, reading feelings and thinking with logic, keeping promises and changing course: you can use them all freely.", "say": "\"What if we flipped that assumption? …Oh, if you're tired, we can do it another time.\"", "do": "After pitching a bold idea in a meeting, you quietly help out the person who's swamped with preparing the slides.", "worry": "It's fun to say what you think, but afterward you replay it again and again: \"Did I go too far?\" You swing between wanting to try new things and wanting to keep the comfort you know.", "karai": "Even in full debate mode, you never forget to check the other person's face."}, "ISFJ>INFJ": {"title": "Watching over today's mood and the road ahead.", "body": "\"You seem a little down lately.\" Your kindness starts with noticing small changes right away. Calming your mind in time alone, caring about how others feel, and preparing with the future in view always stay the same. You can catch the concrete changes right in front of you and also sense the deeper meaning and possibilities, so you can stay close and think with someone about where they'll go next.", "say": "\"Let's take our time and think about what you want to do from here.\"", "do": "After listening to a friend, you pick out a book that might suit them and hand it over with a handwritten note.", "worry": "You think so deeply about others that you end up carrying their worries as if they were your own. When you feel the gap between ideals and reality, it can seem like your own failing, and you feel low.", "karai": "You can advise someone on their life ten years out, but you can't decide on your own plans for this weekend."}, "ISFJ>INFP": {"title": "Turning kindness into letters and little handmade things.", "body": "You usually prepare carefully, but when your feelings for someone stir, you suddenly want to write a letter or make something small. Recharging in time alone and deciding with your heart never waver. You move freely between steady trust in experience and imagining things that don't exist yet, between following the plan and going where your heart leads.", "say": "\"I'll have everything ready. And I wrote you a letter, too.\"", "do": "You get the birthday present ready early, then the day before, a sudden idea has you adding a handmade card.", "worry": "You often get caught between wanting to do things properly for others and wanting to dive into what moves you. Small words can hurt you, and you tend to keep it bottled up without telling anyone.", "karai": "Your planner is packed with plans, and every bit of empty space is filled with doodles."}, "ISFJ>ENFJ": {"title": "Noticing small changes, and showing everyone where to go.", "body": "Do you often find you've been asked to lead, without quite knowing how? Caring about others' feelings and moving with a plan are always at your center. Quiet calm and bright energy with people, a fine eye for details and a wide view that believes in people's potential. That's why you can check on each person and still show the whole group where to head.", "say": "\"Let's all give it a try! …Oh, you seemed worn out yesterday. Are you okay today?\"", "do": "You talk passionately about the club's goals, then message each person who couldn't make it to fill them in on the day.", "worry": "The more you do for everyone, the less time you spend alone, until you suddenly notice you're exhausted. You want so badly to meet expectations that saying \"I can't\" is hard.", "karai": "You take perfect care of everyone's feelings, and you're always the very last to notice you're tired."}, "ISFJ>ENFP": {"title": "Inviting people on a whim, and leaving no one behind.", "body": "You invite people on a whim and create a fun time, but you always keep an eye out for anyone being left out. Deciding with care for people's feelings stays the same, wherever you are. Recharging alone and lighting up with people, trusting experience and chasing sparks, keeping plans and enjoying the flow: you switch between them to fit your mood and the moment.", "say": "\"Want to have a picnic with everyone sometime? …I'll think of a backup spot in case it rains.\"", "do": "You start a new hobby in the heat of excitement, and make a practice schedule so you'll keep it up.", "worry": "The gap between days you want to be around people and days you don't want to see anyone is big, and others can misread you. You swing between wanting to dive into new things and wanting the comfort of familiar places.", "karai": "It was supposed to be a spur-of-the-moment invite, but you're the one doing the most careful planning."}, "ISFJ>ISTJ": {"title": "The rule keeper whose strictness has warmth underneath.", "body": "You keep rules and promises properly, and you take the time to explain why until the other person truly gets it. That's your way. Recharging in time alone, trusting experience and facts, and moving with a plan haven't changed over the years. You have both the kindness to read feelings and the calm to judge fairly, so there's warmth even in your strictness.", "say": "\"Please keep to the deadline. If you're not feeling well, tell me early and I'll adjust things.\"", "do": "You write up the workplace rules properly, and make a separate, easy-to-follow illustrated version for new hires.", "worry": "When you have to decide fairly, you picture someone's disappointed face and hesitate. After giving someone a warning, you keep wondering if you said too much, long after.", "karai": "You're strict about the rules, but the moment someone's in trouble, you start drafting the exception process yourself."}, "ISFJ>ISFJ": {"title": "Someone who has always held out a helping hand.", "body": "You notice when someone changes, and you quietly reach out to help. That kindness is rooted the same way in the temperament you were born with and the character you grew into. It's a strength that has grown steadily since you were a child. Because your sense of self is so clear, you shine in places that fit you, and in places that don't, you tend to get tired without knowing why.", "say": "\"Are you okay? Want me to take care of that?\"", "do": "You remember everyone's favorites, so each person gets a different treat when you bring snacks.", "worry": "You can't say no when asked, and before you know it, your own plans are at the very end of the line. Often the cause of your tiredness isn't you, but a place that doesn't suit you.", "karai": "You remember everyone's birthday, but forget your own days off."}, "ISFJ>ESTJ": {"title": "A love of helping, turned straight into getting things done.", "body": "You keep the discussion moving briskly while still paying attention to families with small children. In your neighborhood or at work, that's the kind of organizer you are. Valuing experience and facts and moving with a plan have never changed. You have both quiet calm and the power to lead a group, gentle care and the logic to make a firm call.", "say": "\"That settles who does what. …If you have little kids, just the morning is fine.\"", "do": "You run the school parents' meeting smoothly, then drop off the handouts at the homes of people who couldn't come.", "worry": "The more briskly you decide, the more you worry people think you're harsh. When people rely on you more and more, your time to rest alone disappears and suddenly you're worn out.", "karai": "You told everyone not to overdo it, then signed yourself up for two shifts."}, "ISFJ>ESFJ": {"title": "The caring heart at the center, quietly connecting people.", "body": "At gatherings, you're the one moving around, making sure everyone's okay, and once you're home and catch your breath, your energy comes back. That's your rhythm. Trusting experience, deciding with your heart, and planning ahead stay the same wherever you are. Quietly calming yourself and warming up a room take turns working in you.", "say": "\"I'm so happy you all came! I'll bring more tea.\"", "do": "You volunteer to organize the class reunion and prepare everything yourself, from RSVPs to name tags on the day.", "worry": "You love seeing people, but after too many plans, you suddenly don't want to talk to anyone. That switch confuses you, and sometimes you wonder, \"Am I bad at people?\"", "karai": "As the organizer, you looked after everyone more than anyone did, and didn't eat a single bite yourself."}, "ISFJ>ISTP": {"title": "A gentle, quiet fixer whose hands move before words do.", "body": "You don't say much, but when someone's in trouble, your hands get to work and the problem is solved before anyone notices. That's how dependable you are. Recharging in time alone and valuing what you can see and touch stay the same, always. Caring warmth and calm thinking, careful preparation and quick action all take shape through your skillful hands.", "say": "\"Here, let me see that. …There, it's fixed.\"", "do": "You fix a friend's bike chain right on the side of the road, and check the brakes while you're at it.", "worry": "Your hands move before you put feelings into words, so your kindness doesn't always come across. Caught between wanting to stick to the plan and wanting to follow your mood, you can lose your own pace.", "karai": "\"It was nothing,\" laughs the person carrying three kinds of tools in their bag."}, "ISFJ>ISFP": {"title": "Moving easily between the plan and a happy detour.", "body": "You make plans properly, yet you can change course on the spot after seeing the weather or someone's face. That lightness is your surprising side. Calming your mind alone, valuing what's in front of you, and deciding with your heart stay the same. With both careful preparation and the ease to go with the flow, you can choose the kind of help that suits each person best.", "say": "\"It's such a nice day. Want to take a little detour?\"", "do": "Visiting a sick friend, you bring the gift you'd planned plus a single flower you spotted on the way.", "worry": "Because you often go along with others, it's easy to put what you want last. Even with a plan, if it doesn't match your mood that day, something feels off.", "karai": "\"Anything's fine\" is your catchphrase, but you already know exactly which place you want to go."}, "ISFJ>ESTP": {"title": "The first to rush in, and the last to leave your side.", "body": "When trouble hits, you're the first to rush in and get moving, and once things calm down, you stay close to anyone who's feeling low. That's how people see you: someone they can count on. Valuing real facts and experiences hasn't changed since you were young. Recharging alone and diving in with people, warm care and clear calls, careful prep and quick moves: they're all tools you use.", "say": "\"Don't worry, I'll handle it right now! So, are you hurt?\"", "do": "Helping a friend move, you carry the heaviest boxes of anyone, and still remember what everyone likes to drink.", "worry": "After charging ahead, you worry whether you put a burden on someone, and you mull it over alone. When lively times go on too long, you suddenly want to be by yourself.", "karai": "You threw yourself into it harder than anyone, then went home wondering if you were too pushy."}, "ISFJ>ESFP": {"title": "At the center of the laughter, still noticing who's in the corner.", "body": "\"Let's have the best time today!\" you say, getting everyone laughing, and you still notice the person sitting quietly in the corner and go talk to them. That warmth is your strength. Valuing what's in front of you and deciding with your heart stay the same, always. You have both the calm to recharge alone and the brightness to shine in a group, the care to be prepared and the lightness to enjoy the moment.", "say": "\"Is your seat cold? I've got a blanket.\"", "do": "You lead the fun at the party, with bandages and stomach medicine tucked secretly in your bag.", "worry": "You want so much to keep everyone happy that if the mood dips even a little, it feels like your fault. The more you've laughed in a day, the more you need time alone that night to shake off the tiredness.", "karai": "The one who partied hardest is in the taxi home, checking that nobody left anything behind."}, "ESTP>INTJ": {"title": "You turn what you feel on the ground into a three-year plan.", "body": "\"Let me just go see it,\" you say, and by the time you're back, there's a plan for years ahead. In every setting, your habit of deciding with clear logic stays steady. You move between drawing energy from people and refining ideas alone, between grabbing the facts and reading what's next, between quick moves and the patience to stick with a long plan.", "say": "\"Once I can see three moves ahead, I just run.\"", "do": "On the way home from a free trial at a new gym, you've already built six months of workouts in your head.", "worry": "Your urge to act and your urge to plan are equally strong, so it's hard to pick the moment to start. After a day with people, the tiredness won't lift unless you get time alone to think.", "karai": "You act like you just went with your gut, but everyone knows you saw three moves ahead."}, "ESTP>INTP": {"title": "A hands-on experimenter whose hands and head are always busy.", "body": "People see you as someone who touches things first. In fact, while your hands are busy, you're asking \"why\" more deeply than anyone. Thinking with logic and adjusting freely to the moment never changes, wherever you are. Some days a lively crowd charges you up, other days you sink into thought alone, and you use both the facts you can hold and your curiosity about how things work.", "say": "\"Let's just open it up. …Oh wait, this mechanism is cool.\"", "do": "You start taking apart a broken hair dryer, get hooked on how the motor works, and look up to find it's morning.", "worry": "You say yes to plans right away, then feel drained on the way home because you didn't get enough time alone. Sometimes you're satisfied once you've figured it out in your head, and it never becomes anything real.", "karai": "You went out to have fun, and somehow spent the whole time studying how something works."}, "ESTP>ENTJ": {"title": "The leader who puts out fires and sets up the next move.", "body": "When trouble hits, you're the first one to act, and everyone notices. Getting energy from people and deciding with logic stay the same wherever you go. You can switch between grabbing the facts fast and imagining what's possible, and between moving on the fly and planning backward from the goal.", "say": "\"Who can move right now? Hands up.\"", "do": "The day someone suddenly can't come in, you fill the gap first, and by that night you've proposed a system so it never happens again.", "worry": "The further ahead you look, the more you also want to jump at the fun thing right in front of you. Others can seem slow, and some days you pull too hard on your own.", "karai": "\"Let's all decide together,\" you say, when the answer is already written in your notes."}, "ESTP>ENTP": {"title": "You bring \"here's what worked\" and \"what if we flip it?\" at once.", "body": "In any brainstorm, you're usually the one with the most ideas. Getting energy from people, thinking with logic, and moving with the moment have always been part of you. Add the strength to stand on solid facts and the eye for things no one has tried yet, and you can ask \"how will this actually go?\" and \"how could it be more fun?\" at the same time.", "say": "\"Last time we did this, people came. …But what if we flipped it?\"", "do": "While picking a project for the school festival, you pull out last year's sales records and pitch three brand-new ideas.", "worry": "You want to try everything you think of, so the number of things you've started keeps growing. After you win an argument, the slightly awkward air that lingers bothers you.", "karai": "\"I was just thinking…\" is the start of a talk that usually runs about thirty minutes."}, "ESTP>INFJ": {"title": "You read people deeply, then go see them right away.", "body": "You think quietly for weeks, then one morning, you suddenly act. That surprise is part of your charm. Your temperament and your character differ in every direction, so you have it all: energy from people and calm alone, an eye for facts and an eye for meaning, cool logic and warm care, quick steps and long-range vision.", "say": "\"I think they're having a hard time. I'm going to go see them.\"", "do": "You'd been stuck on a job change for weeks, then one morning decide \"today,\" and by noon you've booked an interview.", "worry": "You want to think slowly and act fast at the same time, so some days both feel half-done. You see people's feelings so clearly that you crash after you've acted.", "karai": "By the time you say you want to think it over carefully, you've usually already signed up."}, "ESTP>INFP": {"title": "Off the moment the idea hits, and always for someone you care about.", "body": "When a friend is struggling, you show up that same day with what they need. People notice your speed, but behind it there's always someone you care about or a feeling you won't give up. Adjusting freely to the moment never changes. You also have energy from people and warmth you keep alone, trust in facts and a gift for imagining, calm logic and a heart that cares.", "say": "\"I can go right now! …But I don't want to do anything they'd hate.\"", "do": "The moment you hear your favorite author is doing a signing, you start writing a letter, and on the day, you're first in line.", "worry": "You can move boldly, but doing something that doesn't sit right with you slowly hurts afterward. The more you go along with others and have fun, the more you need time alone to settle your heart.", "karai": "The things you insist mean nothing are usually packed with meaning."}, "ESTP>ENFJ": {"title": "The team captain who lifts the mood and sees everyone's potential.", "body": "You turn a junior teammate's mistake into a laugh, then quietly teach them the trick later. On a team, that's the kind of reliable senior you are. Getting energy from people has never changed. You read facts fast and believe in people's potential, you're calm with logic and warm with feelings, and you adapt or plan ahead depending on who's in front of you.", "say": "\"Let's go all out at practice today! …Then I'll talk with each of you.\"", "do": "When sports day cheer practice falls behind, you give everyone a role, and on the way out you tell each person, \"Thanks, that helped.\"", "worry": "The more you act for everyone, the more your own wishes get pushed back. Even when you want to decide quickly, you wait for others' feelings, and decisions get delayed.", "karai": "You help everyone with their problems so much that you have no one to bring yours to."}, "ESTP>ENFP": {"title": "The doer who turns \"someday\" into a plan by the next morning.", "body": "An idea tossed out in casual chat becomes real by the next day in your hands. Getting energy from people and moving lightly are the same in every setting. You also trust the facts in front of you and get excited by what could be, and you balance calm logic with warm care, so you don't just talk about dreams. You actually get people together.", "say": "\"That would be so fun! I'll book the place.\"", "do": "Someone says \"We should go camping sometime,\" and by the next morning you've made a group chat with dates.", "worry": "There's so much fun stuff that your schedule and energy are always stretched thin. Even when you want to decide with logic, you picture someone's disappointed face and hesitate.", "karai": "Say \"someday\" around you, and your next week gets one more plan."}, "ESTP>ISTJ": {"title": "Steady and by-the-book, with quick wits tucked away.", "body": "Most days, people see you as someone careful who follows the rules. But when something unexpected happens, you decide and move faster than anyone, which surprises them a little. Relying on facts and experience and deciding with logic never wavers. You use energy from people and calm alone, quick thinking and steady routines, depending on the scene.", "say": "\"Let's follow the steps. …But if it rains, we switch plans right away.\"", "do": "You take the same train every morning, but the second there's a delay, you've found the fastest way around.", "worry": "You like to prepare properly, yet the same routine day after day makes you restless. After a lively day, you can't settle until you've tidied up alone.", "karai": "The person who says \"let's stick to the plan\" somehow turns out to be the best at improvising."}, "ESTP>ISFJ": {"title": "Your hands move before your words, and the plan is already set.", "body": "When helping a friend move, you carry the heaviest boxes and still have drinks ready for everyone. That's just you. Relying on facts and experience has never changed. Energy from people and calm alone, cool logic and gentle care, quick action and patient, careful effort are all within your reach.", "say": "\"I've got that. Oh, and tomorrow's stuff is already ready.\"", "do": "When you hear a friend has a cold, you leave medicine, jelly drinks, and three days of soup at their door.", "worry": "Because you can help so quickly, favors start filling up your schedule. Even on days you want to fully relax, you hesitate to rest because you feel you should keep things in order.", "karai": "When you say you didn't do much, you've usually done quite a lot."}, "ESTP>ESTJ": {"title": "You put out the fire and write the new rule, all by yourself.", "body": "When trouble hits, you head straight to it, and once it's fixed, you set up \"here's how we'll do it next time.\" You're a leader who shines on the ground. Getting energy from people, valuing facts, and deciding with logic are your steady base everywhere. You can move lightly in the moment or plan ahead and follow through, whichever the day needs.", "say": "\"I'll go handle it. …When I'm back, let's redo the manual.\"", "do": "You plan a barbecue perfectly, then the second you see rain clouds, you switch to a covered spot.", "worry": "There are times you want rules followed and times you want to ignore them and move, and switching between them wears you out. You worry that moving so briskly makes people think you're a little scary.", "karai": "The first person to break the rule you made is probably you."}, "ESTP>ESFJ": {"title": "Hype person and host in one, the heart of every gathering.", "body": "By the end of a get-together, you know the face and name of every new person there. Getting energy from people and valuing what's real in front of you never change. You also have clear-headed judgment and a fine sense of feelings, quick moves and careful prep, so you slip naturally between hyping up the room and looking after everyone.", "say": "\"Cheers, everyone! Does your table have enough drinks?\"", "do": "At the neighborhood festival, you quickly settle prices for the food stalls, then spend the rest of the day playing with the kids.", "worry": "Even when you want to say something clearly, you sometimes swallow it because you don't want to ruin the mood. While you put everyone's needs first, you lose the space to enjoy yourself.", "karai": "On days you organize, the amount you get to eat is almost always zero."}, "ESTP>ISTP": {"title": "A skilled all-rounder, fine with a crowd or working quietly alone.", "body": "You light the campfire on the first try without a word, then become the loudest one there. That contrast is so you. Relying on facts, thinking with logic, and moving flexibly stay the same wherever you are. You get charged up going out with friends, and you also recharge tinkering alone with your bike or guitar.", "say": "\"Let's all go sometime. I'll scout it out alone first.\"", "do": "You quietly tune your bike's gears by yourself, and the moment it's done, you call a friend to go for a ride.", "worry": "The gap between days you want people around and days you don't want anyone talking to you is big, and it confuses others. You're not great at explaining those mood swings in words.", "karai": "For someone who says they like being alone, you show up pretty much every time you're invited."}, "ESTP>ISFP": {"title": "You dive in on impulse and come back with something beautiful.", "body": "You wander into a shop on a whim, become friends with the staff, and leave with a piece that's perfectly you. Your days are full of little finds like that. Valuing your senses and moving lightly never changes. Energy from people and time alone with what you love, quick clear decisions and a sense for what you like all live in you.", "say": "\"Let's go! …I think I kind of love this color.\"", "do": "On a walk, you spot a sunset and suddenly sprint up a hill to get the photo.", "worry": "Even when you want to be matter-of-fact, your likes and dislikes show on your face. After a fun time with people, you can't settle unless you get time alone for what you love.", "karai": "You seem to act on a whim, but you never compromise on the taste of your stuff."}, "ESTP>ESTP": {"title": "Your body moves before you think, a natural at taking the first step.", "body": "Before you even open a map, you're already chatting with a local. Your temperament and your character match exactly, so your knack for reading the flow and catching the key moment has grown steadily since you were a kid. You shine in places full of change, but in places where you just have to wait, you wear down without knowing why.", "say": "\"Wasting time deciding? Let's go.\"", "do": "You're the first customer at a new shop, and by the time you leave, you're talking with the owner about their next event.", "worry": "You put off thinking ahead, then panic over deadlines and paperwork. When boring days pile up, your energy fades and you can't tell why.", "karai": "\"I'll do it later\" usually means the morning it's due."}, "ESTP>ESFP": {"title": "The loudest one having fun, who can still run the show.", "body": "You're hyping everyone up, yet somewhere in your head you're reading the flow. That's how others see you. Getting energy from people, enjoying now, and moving with the moment stay the same wherever you go. With the cool sense to weigh pros and cons fast and the warmth to care for the room, you can take charge whenever it counts.", "say": "\"Yes, let's have fun! …Just let me work out when we need to head home.\"", "do": "At a friend's surprise birthday party, you're the most excited, yet you split the bill to the exact cent on the spot.", "worry": "You don't want to spoil the fun, so you tend to wrap what needs saying in a joke. After you speak plainly, you worry whether you hurt someone.", "karai": "The one who was most excited can list every lesson from the day on the way home."}, "ESFP>INTJ": {"title": "A cheerful strategist whose plans are both right and fun.", "body": "Calm enough to map the route by the minute, cheerful enough to enjoy every moment. You use both naturally. Your temperament and your character share no direction at all, so you have it all: energy from people and thinking alone, savoring with your senses and reading ahead, caring with feelings and deciding with logic, flexibility and planning. That's why your plans are both right and fun.", "say": "\"Here's the overall flow. And I added time for a toast at the end.\"", "do": "You plan a trip down to the minute, but leave one slot for \"doing nothing,\" and that's when you have the most fun.", "worry": "You want to be efficient and you want to go with the moment, so you're torn about how to spend your days off. After a lively time, you get out of sorts if you don't have quiet time alone to reset.", "karai": "The most important item on your perfect schedule is probably the after-party."}, "ESFP>INTP": {"title": "You pick up deep \"why\" questions from fun small talk.", "body": "You were having fun at the amusement park, and suddenly you're deep in thought about how the lines move. That's your surprising side. Adjusting freely to the moment never changes. You move freely between energy from people and thinking alone, enjoying with your senses and chasing how things work, warm care and clear logic.", "say": "\"Hey, why do you think this happens?\"", "do": "Looking at shelves in a gift shop, you ask the staff, \"Why does this layout make me want to buy things?\"", "worry": "You love talking with people, but when you get absorbed in thought, you forget to reply. Even when you want to honor feelings, you answer with logic and regret it later.", "karai": "\"That was fun!\" tends to get the reply, \"The system was so interesting.\""}, "ESFP>ENTJ": {"title": "Big goals, and somehow everyone follows you with a smile.", "body": "After setting firm targets in a meeting, you go around handing out snacks. That's your style of leading. Getting energy from people never changes, wherever you are. Enjoying now and picturing the future, warmth for people and cool logic, going with the flow and planning backward from the goal are all within your reach.", "say": "\"Our goal is 1.5 times last year! If we hit it, dinner's on me.\"", "do": "You organize a local fun run and arrange food stalls and a winners' podium at the finish line.", "worry": "The more you want results, the more you worry about someone's feelings after you speak strictly. Some days your head is so full of future plans that you have no room to enjoy what's in front of you.", "karai": "The moment you decide to have fun, fun gets a target too."}, "ESFP>ENTP": {"title": "You grow a joke idea into a real event.", "body": "While you're making everyone laugh, an idea somehow pops out of the conversation. Getting energy from people and moving lightly have always been part of you. You enjoy now with your senses and imagine what doesn't exist yet, and you care warmly while thinking sharply, so even your wildest ideas make sense.", "say": "\"Ooh, that sounds fun! …Wait, what if we did it backwards?\"", "do": "You meant to rearrange your room, and somehow you're inviting friends over for a little art show.", "worry": "You jump at every fun idea, and half-done projects pile up. After a heated debate, you check people's faces to see if you went too far.", "karai": "Every plan you meant as a joke somehow turns into the real thing."}, "ESFP>INFJ": {"title": "In the middle of the fun, you're first to notice who seems lonely.", "body": "On the way home from a day you laughed brighter than anyone, you quietly wonder, \"Was something bothering them?\" Caring about people's feelings moves you in every situation. You also have energy from people and calm alone, savoring now and reading meaning, going with the flow and preparing ahead, all at work.", "say": "\"You okay? Did something happen?\"", "do": "When taking a group photo, you notice someone hanging back at the edge and pull them into the middle.", "worry": "You love seeing people, but afterward, the emotional tiredness lasts longer than you expect. You read feelings so deeply that you worry about things that haven't even happened.", "karai": "While keeping the party going, you're also tracking how everyone's heart is doing."}, "ESFP>INFP": {"title": "You want to remember the color of today's sky forever.", "body": "On the way home from a fun day with friends, you can tuck that day's scenery away like a poem. Caring about feelings and moving flexibly are what you've always carried. You treasure your energy from people and your quiet feelings alone, your sense for beauty right here and your imagination for what can't be seen yet.", "say": "\"How do I even put this feeling into words?\"", "do": "After a day out, you add a short note to each photo, one by one, and make an album.", "worry": "Time with everyone and time lost in your imagination both matter, so you swing between overbooking and shutting yourself in. You can't quite put what matters to you into words, and that frustrates you.", "karai": "You look like you live on vibes, but you're more stubborn about your tastes than anyone."}, "ESFP>ENFJ": {"title": "Hear \"I want to try,\" and you've already planned the support.", "body": "When a friend shares a dream, you get excited with them, and right away you start planning how to cheer them on. Getting energy from people and deciding with care are always your center. You use your joy in the moment and your belief in people, your easygoing flow and your gift for leading with a plan, for the people around you.", "say": "\"That's such a good idea! …Let's try it once by next month. I'll help.\"", "do": "You rush to a junior's recital with flowers, and afterward you help them think of their next goal.", "worry": "Helping makes you happy, so you can't say no to favors and your schedule overflows. The more you plan for everyone, the less time you have to enjoy things freely.", "karai": "Your support schedule for other people's dreams is perfect, while your own dream stays \"someday.\""}, "ESFP>ENFP": {"title": "From the cake in front of you to the shop you'll open someday.", "body": "Eating cake at a café, you're the one who says, \"Want to open a shop together someday?\" Getting energy from people, caring about feelings, and going with the moment never change. You savor now with all your senses and imagine futures that don't exist yet, so you make the days of the people around you brighter and bigger.", "say": "\"So, what should we do next?\"", "do": "At a picnic in the park, you come up with a tiny flea market just for your group and invite friends on the spot.", "worry": "Fun things and things to try keep multiplying, and your body and schedule can't keep up. You want to reach for both today's fun and tomorrow's dreams, so narrowing it down to one is hard.", "karai": "\"My someday bucket list\" already holds more than a lifetime."}, "ESFP>ISTJ": {"title": "The \"very proper\" one, who's the center of laughs at break time.", "body": "At work, you're the dependable one who finishes paperwork neatly. But at break time, you're the one making everyone laugh. Relying on facts and experience never changes, wherever you are. You balance energy from people and calm alone, warm care and cool logic, enjoying the moment and steady routines, just right.", "say": "\"I'll finish the documents today. …After that, want to try the new bakery?\"", "do": "You write careful handover notes, then add by hand at the end, \"Ask me anytime if you get stuck.\"", "worry": "The more neatly you handle things, the more people rely on you, and the fewer chances you get to just have fun. After choosing what's right, you wonder if you left someone's feelings behind.", "karai": "You work with a serious face, while part of your brain is usually on weekend plans."}, "ESFP>ISFJ": {"title": "Big fun for the party, and a gift for every single guest.", "body": "At a house party, you laugh the most, then hand out little gift bags to everyone as they leave. Valuing what's real and caring about feelings never change. Energy from people and relief in time alone, enjoying the moment and preparing ahead with care, both sides hold up your kind of hosting.", "say": "\"Let's go big today! …There's juice too, for anyone who doesn't drink.\"", "do": "When visiting a friend, you bring their favorite snacks plus small treats for their family.", "worry": "You want to make people happy so much that you overdo the prep and are worn out on the day. After a fun time, your energy won't come back unless you rest quietly alone.", "karai": "After handing out gifts to everyone, you realize there's none left for you."}, "ESFP>ESTJ": {"title": "Put in charge, the place, the budget, and the fun are all perfect.", "body": "You lock in the place and the budget, and on the night, the organizer having the most fun is you. Getting energy from people and valuing what's real stay steady wherever you go. Warm care and clear logic, the lightness to liven things up and the responsibility to plan and finish, both work for you.", "say": "\"Okay, we meet at 7. So, where are we going after?\"", "do": "You make a detailed duty chart for a town cleanup, then on the day you find an interesting alley and take your whole team on a detour.", "worry": "The more people rely on you as \"so dependable,\" the less time you get to just play. Wanting to keep plans and wanting to enjoy the moment pull at each other, so days off can be the most tiring.", "karai": "You know everyone's schedule down to the minute, but your own day off is always TBD."}, "ESFP>ESFJ": {"title": "You take on the planning and the caring, then truly enjoy the day.", "body": "You arrange the class reunion's guest list and venue perfectly, then on the day you're the loudest one sharing memories. Getting energy from people and valuing what's real and how people feel are your steady base. You can enjoy the vibe of the moment and plan so no one's left stuck, so people count on you for events and celebrations.", "say": "\"The flow is set! But if it's more fun, we can change it halfway, right?\"", "do": "For a coworker's farewell party, you arrange the message card and flowers, then cry before the guest of honor does.", "worry": "You make rules so everyone can have fun, then on the day you want to follow the vibe. The more you try to meet others' hopes, the harder it gets to say you're tired.", "karai": "You tell people not to push themselves, but you've never once said it to yourself."}, "ESFP>ISTP": {"title": "Cracking jokes while your hands work with a craftsman's precision.", "body": "\"Ooh, fun!\" you say, jumping in before anyone, and soon you're the one working most smoothly. Valuing your senses and moving lightly stay the same wherever you are. Energy from people and quiet focus alone, warmth for feelings and clear-headed judgment both come alive in you.", "say": "\"Here, let me see. It's faster if you do it like this.\"", "do": "When a friend's bike gets a flat, you fix it quickly while cracking jokes.", "worry": "Wanting to be kind and wanting to be matter-of-fact clash, and you're unsure how to say things. After a run of busy days, suddenly a day comes when you don't want to talk to anyone.", "karai": "\"You can do anything, that's amazing!\" makes you shy, and you change the subject right away."}, "ESFP>ISFP": {"title": "Lively days and nights lost in music you love, you need both.", "body": "Laughing out with friends and being surrounded by your favorite music and art at home are both things your days can't do without. Sensing beauty and fun, caring about feelings, and moving flexibly have always been you. You can light up around people, and you can fill your heart alone with the things you love.", "say": "\"I think I want to walk home alone, slowly.\"", "do": "After a lively get-together, you stop by a park at night alone and listen to your favorite song on the way home.", "worry": "Invitations make you happy, so you overbook and later run short on time for yourself. You spend so much energy brightening the room that you never get to talk about what you love.", "karai": "You look social, but you also make firm reservations for alone time."}, "ESFP>ESTP": {"title": "You make everyone laugh and stay the calmest when trouble hits.", "body": "The moment you learn the reservation fell through, you start looking for another place while keeping everyone laughing. Getting energy from people, enjoying now, and moving with the moment stay the same wherever you go. The power to warm the room with care and the power to weigh things and decide fast both support you.", "say": "\"It's fine, it's fine! Let's grab another place while we can.\"", "do": "When the fireworks show is canceled for rain, you come back with sparklers and ice cream before anyone can get down.", "worry": "After making a logical choice, you replay over and over how the other person felt. You decide on impulse a lot, so small checks get pushed back.", "karai": "You're so sensitive to people's feelings, yet pretty clueless about what's in your wallet."}, "ESFP>ESFP": {"title": "A natural sunshine who lights up any room in an instant.", "body": "Even at a gathering full of strangers, you end up laughing in the middle of the circle. Your temperament and your character are the same, so your gift for enjoying now with others has grown straight since you were little. You come alive in places with connection, but in places where you work alone in silence, you lose energy without knowing why.", "say": "\"We're here anyway, let's have fun!\"", "do": "Even when you lose at the shopping street lottery, you come home after laughing with everyone there.", "worry": "While you put fun first, managing money and future plans slips. When you feel low, it's often not weakness but a place too far from people.", "karai": "On the night you decide \"this month I'll save,\" you usually buy something."}, "ISTP>INTJ": {"title": "A quiet designer whose prototypes grow into ten-year plans.", "body": "\"Let's just build it and see\" is your catchphrase, yet somehow every prototype ends up inside a plan that runs years ahead. Recharging alone and deciding by clear logic are steady ground for you, from every angle. What joins them is a light, hands-on urge to test things and a long view that maps out the road. You move easily between small experiments and big blueprints.", "say": "\"I'll just build one first. I already know how we'll use it in three years, though.\"", "do": "You build a prototype with your tools on the weekend, then turn it into a spreadsheet of upgrade plans on weeknights.", "worry": "The tighter your plans get, the more the thrill of just trying things seems to fade. Some days your hands stop while you decide: stick to the plan, or chase the new idea?", "karai": "Step one of your ten-year plan is almost always \"just poke at it.\""}, "ISTP>INTP": {"title": "Fixing the machine while asking why it was built that way.", "body": "Put a broken machine in front of you and two questions start at once: how to fix it, and why anyone built it like this. Recharging alone, thinking things through, and moving free of rules all line up perfectly between what you were born with and what you grew into. The difference is where you look. Your hands test what's in front of you while your mind chases the theory nobody can see yet.", "say": "\"Fixed. Also, isn't this design kind of weird?\"", "do": "After repairing an appliance, you stay up past midnight reading the history of how it works.", "worry": "Your thoughts spread so wide that by the time your hands get moving, your interest has moved on. The moment you understand something, you feel satisfied and forget to explain it to anyone.", "karai": "You nod like it all makes sense, and then explain absolutely nothing to anyone."}, "ISTP>ENTJ": {"title": "Leading the meeting, then quietly handling the hard part.", "body": "In meetings you lay out the plan with confidence. Then, late at night, you quietly take care of the hardest piece yourself. That's how people around you see it. Deciding by logic stays firm no matter which side of you is showing. Alongside it come pairs: quiet skill-building and rallying people, checking facts and reading ahead, flexibility and planning.", "say": "\"This is the direction. And I'll take care of this part tonight.\"", "do": "Right after handing out the team schedule, you head to the site alone to check the real thing.", "worry": "When you lead for too long, there's no time left to work with your hands, and your battery suddenly dies. Even when delegating would be faster, you still want to check it yourself.", "karai": "Your instructions are brilliant, and they usually end with \"Never mind, I'll do it.\""}, "ISTP>ENTP": {"title": "Turning lunch-break ideas into prototypes the same night.", "body": "One minute you're saying \"Wouldn't this be fun?\" and that same night you're already building it. Thinking with logic and adapting on the spot are traits rooted deep in both sides of you. You move between focused solo time and conversations that spark you, between solid facts and shapeless possibilities. So you never stop at just talking, or at just doing.", "say": "\"What if we did it like this? No wait, let me build one first, then we'll talk.\"", "do": "You take an idea from a lunch-break chat and make it out of cardboard as soon as you get home.", "worry": "Talking with people lights you up, but too much of it wears you out and you want to hide at home. Your hands can never keep up with how many ideas you have.", "karai": "The gap between ideas you've had and things you've finished is getting close to an extra zero."}, "ISTP>INFJ": {"title": "Quietly setting out the tools before anyone needs help.", "body": "You don't say much, but you have what someone needs ready before they even hit the problem. That's your way of helping. Recharging alone is steady ground on both sides of you. Here, several pairs join hands: seeing facts as they are and reading their meaning, deciding by logic and caring about feelings, moving lightly and planning ahead.", "say": "\"I figured this would be a problem next month. Already fixed it.\"", "do": "The day after someone asks for advice, you leave the tools they need on their desk without a word.", "worry": "You think so hard about someone's feelings that you hesitate to give the logical answer. While worrying about the future, the task in front of you sometimes slips.", "karai": "Your kindness is so fast that people miss their chance to say thank you every single time."}, "ISTP>INFP": {"title": "A maker who shapes the scenes in your heart with skilled hands.", "body": "You talk about the art you love with real fire, yet your hands stay surprisingly calm when you make things. Recharging alone and doing things your own way, not by the rules, point the same direction in both your nature and your upbringing. Precise skill and a wide imagination, cool logic and gentle feeling. Together they help you turn memories into something you can hold.", "say": "\"This color kind of makes me want to cry.\"", "do": "When a keepsake breaks, you look up how to fix it before you even feel sad, and make it sturdier than before.", "worry": "You choose with your heart, and then the logic can't catch up, which leaves you uneasy. Putting your passions into words is hard, so they often go unshared.", "karai": "The same hand that wipes away a happy tear is already holding a screwdriver."}, "ISTP>ENFJ": {"title": "Loud cheers for the team, quiet craft on your own.", "body": "You cheer everyone on with \"You've got this!\" and later you're alone in an empty room, finishing the fiddly work. Your temperament and character share nothing in common, and that's exactly why your range is so wide. Solo focus and lifting others up, checking facts and believing in potential, logic and kindness, flexibility and planning. You don't stop at words. You actually lend a hand.", "say": "\"You can all do this! I'll fix the broken part.\"", "do": "You keep your class fired up all through festival prep, then spend the last night alone rewiring the sign.", "worry": "You stand in front of people so often that you run short on time to get lost in something alone. Your job is putting feelings into words, but your own feelings rarely come out.", "karai": "After your big rousing speech, what you're really looking forward to is tinkering alone."}, "ISTP>ENFP": {"title": "A heart that loves the fun, and hands that light the fire.", "body": "At camp you're the most excited person there, and somehow you've also taken over building the fire and fixing the gear. Moving lightly with the moment is shared by your temperament and your character. Solo testing and group excitement, seeing facts and widening possibilities, cool logic and warm feeling all take turns, depending on the scene.", "say": "\"That's amazing, let's do it! Oh, let me just check we have enough supplies.\"", "do": "You show up to help a friend move, keep the mood up the whole time, and end up assembling every piece of furniture.", "worry": "After a fun chat, you suddenly need to be alone, and people ask, \"Are you mad?\" You want to do so much that you jump to the next thing before finishing one.", "karai": "The plan you started on a whim? You're somehow running the whole backstage alone."}, "ISTP>ISTJ": {"title": "A craftsperson who follows the manual, and knows when to close it.", "body": "You announce \"We start at ten, as planned\" and mean it. But when trouble hits, you close the manual and work with what's in front of you. Recharging alone, trusting facts, and deciding by logic hold firm on both sides. Faithfully following steps and adapting on the fly sit side by side. That's why people rely on you at the workbench and at the desk.", "say": "\"We start at ten as planned. If it breaks, I'll fix it on the spot.\"", "do": "Your toolbox is perfectly organized, yet when you're out you cleverly improvise with a paper clip.", "worry": "You're great at following rules, but places with too many of them suddenly feel suffocating. On days off you either overpack your schedule or leave it empty, and the balance is hard to find.", "karai": "You wrote \"stay flexible\" on your schedule, and you're sticking to it word for word."}, "ISTP>ISFJ": {"title": "The family fixer who repairs things before anyone asks.", "body": "When someone's bike tire goes flat, you fix it without a word and even pick a new spot for the pump. Recharging alone and trusting facts and experience are the same in your nature and your upbringing. Cool logic and gentle care, light movement and careful preparation. Your skill goes quietly into supporting the everyday lives of people around you.", "say": "\"It's getting cold. Take this with you.\"", "do": "You solve problems at work before anyone asks, then stick up a small note so the next person won't get confused.", "worry": "Because you handle requests so well, you can't find a reason to say no. Caught between finishing fast and putting others first, your own time slowly wears away.", "karai": "You can fix everyone's stuff, but your own tiredness is stuck in the repair queue."}, "ISTP>ESTJ": {"title": "The on-site leader who gives orders and tightens screws.", "body": "You're good at giving directions, but people may rely on you most when the equipment stops and you're the first one there. Trusting facts and deciding by logic match up in your temperament and character, steady and sure. Added to that are solo skill-building and leading from the front, adapting on the spot and seeing a plan through to the end.", "say": "\"Here's how we'll split the roles. Send any trouble my way.\"", "do": "Put in charge of a neighborhood event, you spend the day itself fixing the sound system on your own.", "worry": "The more you're asked to lead, the less time you get to work quietly alone. You want people to stick to the plan, yet you want to move on instinct, and you wonder if that's fair.", "karai": "You tell everyone not to wander off, then you're the first one to leave your post."}, "ISTP>ESFJ": {"title": "Keeping the mood warm, and fixing the wobbly chair.", "body": "At gatherings you ask, \"Does everyone have a drink?\" and when something breaks, you calmly go fix it. Trusting facts and experience runs through both sides of you. Solo focus and enjoying a crowd, cool logic and reading everyone's feelings, flexibility and thoughtful planning all work together to make a comfortable space.", "say": "\"That light's not working. I'll go take a look.\"", "do": "At a dinner party, you serve food to suit everyone's taste while secretly fixing a wobbly chair.", "worry": "While you're looking after everyone, your quiet time disappears and you suddenly feel drained. Torn between saying what's right and keeping the mood, you tend to just stay quiet.", "karai": "After taking care of everyone, the walk home alone is your favorite part of the night."}, "ISTP>ISTP": {"title": "Your hands know the answer before the manual does.", "body": "You say \"Let me see that,\" and a few minutes later it comes back fixed. Testing things with your own hands, thinking with logic, and moving freely without rules have exactly the same shape in what you were born with and what you grew into. Give you room and you shine. Too many detailed instructions, and you start to feel a little boxed in.", "say": "\"Let me see that. …There, fixed.\"", "do": "You've finished putting together a new shelf before even opening the instructions.", "worry": "Putting feelings into words is hard for you, so people often say they can't tell what you're thinking. Your tiredness usually comes less from you and more from places that don't let you move freely.", "karai": "Someone asks \"Are you okay?\" You say \"Yeah.\" Conversation complete."}, "ISTP>ISFP": {"title": "Strength fully calculated, corners nicely rounded.", "body": "You handle tools with precision, then at the finishing stage you suddenly start caring about color and texture. Recharging alone, trusting facts, and adapting to the moment share the same roots on both sides. Only one thing differs: cool logic sits beside a feel for beauty and emotion. That's how you make things that are easy to use and lovely to hold.", "say": "\"The strength is fine. But wouldn't the corners be cuter a bit rounder?\"", "do": "You build a shelf that fits the space perfectly, then pick out small decorations to match the wood.", "worry": "Even when logic says something is right, you can't move if your heart isn't in it. When you share an opinion, you go over it again and again, wondering if it sounded cold.", "karai": "You insist you're not picky, yet even the screw heads match in color."}, "ISTP>ESTP": {"title": "Skills that shine in a crowd and in a quiet workshop.", "body": "When trouble hits on a day out with friends, you're already moving before anyone starts discussing it. Trusting facts, deciding by logic, and moving lightly with the moment are exactly the same on both sides. What differs is where your energy comes from. Diving into a crowd recharges you, and so does polishing your skills alone. Speed and real skill live side by side in you.", "say": "\"Okay, let's go! Oh, let me just check the tire pressure.\"", "do": "When the barbecue just won't light and everyone's stuck, you quietly rearrange the charcoal and get it going on the first try.", "worry": "Being with people is fun, but after a while you suddenly need time alone. When people say \"You should've asked first,\" it's usually after you've already fixed everything.", "karai": "Your motto is \"act, don't think,\" yet you hold a thorough solo review meeting once you get home."}, "ISTP>ESFP": {"title": "Life of the trip, and the mechanic when the car stops.", "body": "On a trip you're snapping photos and having a blast, then the moment the car dies, you calmly pop the hood. Trusting facts and adapting on the spot don't change between your nature and your upbringing. Solo focus and the energy of a crowd, cool logic and warmth for everyone's feelings. People are often amazed at how fast you switch.", "say": "\"Wow, this place is amazing! Photo time! Wait, is the tripod loose?\"", "do": "The day after going all out at a festival, you're alone at home, absorbed in painting a model kit.", "worry": "The day after a big fun time, you're wiped out and don't want to talk to anyone. You're often torn between saying what you think and keeping the fun going.", "karai": "You were supposed to be the star of the party, yet there you are in the corner, fiddling with the speakers."}, "ISFP>INTJ": {"title": "Growing the beauty your heart picks into a long blueprint.", "body": "When you find a color scheme you love, you don't let it stay a whim. You start a plan to redo your whole room over years. Recharging alone is steady ground in both your temperament and your character. Savoring what feels good now and seeing far ahead, choosing by heart and deciding by logic, lightness and planning all work in pairs.", "say": "\"I love this palette. I've already planned to do my whole room in it by next year.\"", "do": "You turned redecorating your room into a year-long schedule and tackle one item a month.", "worry": "Making plans calms you, but as you follow them, the love you started with seems to fade. When asked why you chose something by feel, you get stuck for words.", "karai": "It was supposed to be a vague \"I just like it,\" and now it comes with a five-year plan."}, "ISFP>INTP": {"title": "Someone who has to know why you love what you love.", "body": "When you hear a song you love, your heart moves, and at the same moment you start wondering why that melody makes you tear up. Recharging alone and moving at your own pace, free of rules, stay steady on both sides. A feel for texture and color and a mind for invisible systems, gentle feeling and cool logic, take turns showing up.", "say": "\"Why do I like this song so much?\"", "do": "You start looking up how your favorite mug was made, and soon you're reading about the chemistry of glazes.", "worry": "Some days you overthink what you feel and can't just enjoy it. You don't talk until your thoughts are sorted, so people assume you aren't thinking at all.", "karai": "By the time you finish explaining why it moved you, your listener has completely stopped feeling moved."}, "ISFP>ENTJ": {"title": "A leader who puts care for people into every bold call.", "body": "You run the meeting with crisp efficiency, then carefully finish the cover of the handout in your favorite color. Your temperament and character share nothing, so your range is unusually wide. Calming yourself alone and leading others, savoring the present and reading ahead, feeling and logic, lightness and planning. That's why your decisions carry care for people, not just numbers.", "say": "\"The goal is end of month. Let's settle this much today, then everyone take a break.\"", "do": "You finalize your whole moving plan in a day, then spend a full week choosing curtains for the new place.", "worry": "The more you lead, the less time you have to lose yourself in what you love. When you have to be firm to get things moving, you keep wondering afterward if you hurt someone.", "karai": "On nights after giving tough orders, the person most full of regret is the one who gave them."}, "ISFP>ENTP": {"title": "Reading the room, then rolling the talk somewhere unexpected.", "body": "You were supposed to be listening to a friend's worries, and somehow the two of you are inventing a new game. Adapting flexibly to the moment is a strength shared by what you were born with and what you grew into. Quiet savoring and lively talk, feeling textures and picturing possibilities, gentle kindness and sharp logic carry every chat in surprising directions.", "say": "\"That's kind of sad. …Oh, but what if we flipped it like this?\"", "do": "When someone complains about a board game's rules, you propose three new ones on the spot.", "worry": "The more fun a conversation gets, the more tired you are afterward, and you want to hide away. On nights after you said too much in a debate, you replay it, thinking about the other person's feelings.", "karai": "Behind your \"Either is fine,\" three counterarguments are already lined up."}, "ISFP>INFJ": {"title": "Noticing small changes and caring a step ahead.", "body": "You catch a friend's small changes right away, stay gently by their side, and quietly think about what's ahead for them. Recharging alone and deciding with care for people's feelings are the same in your temperament and character. Savoring the moment and reading deeper meaning, moving freely and planning calmly, add depth to your kindness.", "say": "\"Let's take it easy today. We'll prep for next week's thing together, okay?\"", "do": "While arranging seasonal flowers, you've already decided what to display at the same time next year.", "worry": "You think so far ahead for others that your own feelings get pushed back. Even on days you want to follow your mood, you fill your schedule \"for the future.\"", "karai": "You can support others' worries ten years out, but you haven't told a soul about your own."}, "ISFP>INFP": {"title": "One small flower on a walk, one whole story.", "body": "A tiny flower you spot on a walk turns into a whole story. Recharging alone, valuing feelings, and moving at your own pace take the same shape on both sides. What differs is where you look. A sense that truly catches colors and sounds works together with an imagination that pictures worlds not yet formed. You can gently turn the beauty around you into stories.", "say": "\"This sunset feels like the start of a story from a faraway land.\"", "do": "In your favorite notebook, you alternate pages between a diary and stories you make up.", "worry": "The higher your ideals, the lonelier the gap with reality feels. You care about so many things that choosing just one is hard.", "karai": "In your imagination you can fly, but calling a restaurant to book a table takes an hour of worrying."}, "ISFP>ENFJ": {"title": "Staying by your side, and gently nudging you forward.", "body": "You sit down next to someone and say, \"I get it,\" and before long you're planning their next step together. Deciding with care for people's feelings is a perfect match between your temperament and character. Calming yourself alone and drawing energy from a group, savoring now and seeing ahead, easygoing lightness and planning give your encouragement real depth.", "say": "\"I totally get how you feel. …So let's try getting this far by next week.\"", "do": "You drop off a friend's favorite snack when they're down, and by the time you leave, the next fun outing is on the calendar.", "worry": "When you're the encourager for too long, your time for your own things disappears and your heart wears thin. Some days your mood can't keep up with plans you made for everyone.", "karai": "You're everyone's emotional care team, but your own self-care calendar is completely blank."}, "ISFP>ENFP": {"title": "Find a favorite, and you instantly want to show someone.", "body": "Some days you enjoy your favorite café alone. The next week you bring friends and find a new way to enjoy it. Valuing feelings and going with the flow have always been part of you, on both sides. Added to that are quiet solo fun and the energy of sharing, an eye for comfort right here and an eye for brand-new possibilities.", "say": "\"I love this place so much! Let's all come next ti… actually, I might want to come alone.\"", "do": "Every time you find a cute item, you send a photo, and somehow your plans for the next day off have tripled.", "worry": "On the way home from a fun time, you're thrown by how suddenly you want to be alone. New loves keep piling up, and your heart moves on before you can go deep with one.", "karai": "On the very day you decide to stay home, you're the one who sends out the most fun invite."}, "ISFP>ISTJ": {"title": "Careful, precise work, with a quiet touch of beauty.", "body": "The report you turned in right on time somehow has a cover in seasonal colors. Recharging alone and valuing facts and experience match up in your nature and upbringing. Gentle choices from the heart and calm decisions by logic, free movement and faithful follow-through. Your care shows through even in your most precise work.", "say": "\"I'll submit it on time. I just made the cover color a little autumn-ish.\"", "do": "You keep your budget book accurate to the cent, with favorite stickers in the corners of each page.", "worry": "On nights when you put being right first, you wonder if you left someone's feelings behind. Some days you realize that, while following the rules, you put your own likes on hold.", "karai": "You're super tidy, yet when it comes to stationery, the budget never survives."}, "ISFP>ISFJ": {"title": "Ready the night before, free to wander the next day.", "body": "You pack everyone's lunches the night before, then take whatever detour you feel like the next day. Recharging alone, valuing facts and experience, and caring about people's feelings are steady ground on both sides. The only difference is how you move: you can follow your mood lightly, and you can prepare well ahead too.", "say": "\"Tomorrow's stuff is ready, so I'm just going to wander out for a bit today.\"", "do": "You have a family member's birthday present ready a month early, then add a single flower picked on the day.", "worry": "The more carefully you prepare, the more a little guilt creeps into your free time. Fitting around other people's schedules, you forget what you wanted to do.", "karai": "You carry spares for everyone's forgotten stuff, yet your own umbrella stays at home."}, "ISFP>ESTJ": {"title": "Deadlines get kept, but nobody gets pushed too hard.", "body": "You keep things on schedule while quietly checking in on anyone who looks tired. To the people around you, you're great at balancing strictness and kindness. Trusting facts and experience is shared by your temperament and character. Calming yourself alone and organizing others, reading feelings and deciding firmly, lightness and solid planning hold it all up.", "say": "\"The deadline is Friday, no changes. But if it's too much, tell me early.\"", "do": "You build an event schedule down to the minute, and on the day people also praise your eye for decorations.", "worry": "On days you give clear orders, you lie awake wondering if you were too harsh. After leading for a while, you miss time alone with the things you love.", "karai": "The sterner your face was that day, the cuter the little treat you buy yourself on the way home."}, "ISFP>ESFJ": {"title": "The low-key organizer who makes room for everyone.", "body": "At gatherings you pay close attention so everyone feels at home, and afterward you let out a sigh of relief alone in your room. Valuing facts and experience and caring about feelings are the same in your temperament and character. Quiet solo time and the energy of a group, going with the flow and preparing ahead take turns, depending on the scene.", "say": "\"Everyone's seats are ready. I might sneak out a bit later, though.\"", "do": "You prepare birthday party decorations a week ahead, and afterward take the leftover flowers to decorate your own room.", "worry": "You love doing things for everyone, but after a while you suddenly need to be alone. When turning down an invite, you worry too much about letting someone down.", "karai": "The day after organizing a flawless event, you turn off every notification on your phone."}, "ISFP>ISTP": {"title": "Making the shapes you love even better, by hand.", "body": "One moment you're admiring the charm of an old chair, the next you're already holding sandpaper. Recharging alone, trusting facts, and adapting to the moment are the same on both sides. What differs is how you decide: a feel for beauty and emotion sits beside calm logic. The instant something moves you, your hands are already working out how to make it better.", "say": "\"This shape is beautiful. Shave a little here and it'll be easier to hold.\"", "do": "You swap the buttons on a vintage jacket you love for ones that keep its vibe.", "worry": "After calmly saying what's right, you keep replaying it, wondering if you hurt someone. Some days logic jumps ahead when you wanted to choose with your heart, and you can't simply be happy.", "karai": "People call you a bit cool, yet your handmade gifts usually make them cry happy tears."}, "ISFP>ISFP": {"title": "Someone who has grown your own loves, straight and true.", "body": "Even if you can't explain why, you know clearly what feels right. Your sense for what's pleasant, your gentle way of being there for people, and your easy, own-pace rhythm point exactly the same way in what you were born with and what you grew into. Surrounded by things you love, you flourish. When rushed, you tire a little more easily.", "say": "\"Yeah, this one. I can't really say why.\"", "do": "On an ordinary walk home, you notice the smell of the season and take the long way.", "worry": "It takes you time to put feelings into words, so you often swallow them before they come out. Your tiredness usually comes less from you and more from places that push a pace that doesn't fit.", "karai": "You said \"Anything's fine,\" yet you remember the restaurant that didn't get picked for quite a while."}, "ISFP>ESTP": {"title": "Diving straight into the places that catch your heart.", "body": "On a trip you duck into an alley that catches your eye, and if it's crowded, you're off to find the next spot. Trusting facts and moving lightly with the moment are in both your temperament and your character. Quiet savoring and diving into crowds, gentle feeling and quick logical calls, turn into the drive to enjoy every moment fully.", "say": "\"This place has such a nice vibe! Let's go in!\"", "do": "When rain ruins the plan, you quickly find a nearby art museum and bring everyone along.", "worry": "Later, decisions you made in the moment nag at you: did I think about how that person felt? When the lively times go on too long, exhaustion hits you all at once.", "karai": "You were the first to jump into everything, and the quietest on the way home."}, "ISFP>ESFP": {"title": "Sharing good times with everyone, and with yourself.", "body": "The day after throwing your all into a friend's birthday, you spend the whole day watching favorite movies in your room. Valuing facts, caring about feelings, and going with the flow look the same from either side. The only difference is where your energy comes from. Quiet fun alone and laughing in a crowd both recharge you, and you're good at sharing joy and savoring it alone.", "say": "\"Let's all go, it'll be so fun! …And then I'll look at the photos alone at home.\"", "do": "You end up chatting with the staff at a mall's free-sample stand, then enjoy the snacks you bought alone at home.", "worry": "The more fun the event, the more tired you are afterward. You find it hard to say no to invites, so your alone time runs short.", "karai": "You're the one who says \"Let's hang out again!\" most, yet the next message usually comes from them."}};
var LV={"questions": [{"ax": "EI", "p": "E", "q": "Dates are more fun with friends along than with just the two of us."}, {"ax": "SN", "p": "N", "q": "I've imagined a confession or proposal down to the place and the exact words."}, {"ax": "TF", "p": "T", "q": "After a fight, I first want to sort out what actually caused it."}, {"ax": "JP", "p": "J", "q": "I like to decide where and when we're going on a date ahead of time."}, {"ax": "EI", "p": "I", "q": "When I like someone, I only talk about it with one person I trust."}, {"ax": "SN", "p": "S", "q": "What makes me fall for someone is whether I can relax around them."}, {"ax": "TF", "p": "F", "q": "I quickly notice when the person I like is even a little bit down."}, {"ax": "JP", "p": "P", "q": "I'd rather come up with surprises on the day, depending on my mood."}, {"ax": "EI", "p": "E", "q": "When I'm interested in someone, I'm the one who goes up and starts talking."}, {"ax": "SN", "p": "N", "q": "I love talking with my partner about future dreams and \"what if\" scenarios."}, {"ax": "TF", "p": "T", "q": "When my partner comes to me with a problem, I tend to offer solutions more than feelings."}, {"ax": "JP", "p": "J", "q": "I like to agree early on how often we'll keep in touch and on our ground rules."}], "types": {"INTJ": {"t": "INTJ", "name": "Owl in Love", "tag": "Star-Map Maker for Two", "one": "You quietly scout the route before a date.", "desc": "You fall for someone slowly, and you rehearse a confession in your head many times first. On date day, you've already checked the way to the restaurant. Your texts are short and to the point, so people think you're cold. But you start planning anniversaries before anyone else, and you've been quietly choosing a gift for a month.", "good": ["The date route is already scouted", "You truly back your partner's dreams", "You keep even small promises", "You offer a fix right away", "Once you commit, no cheating, ever"], "care": ["Your texts read like work memos", "You win fights with pure logic", "You never admit you're jealous", "You plan the future alone", "You don't know when to lean in"], "tip": "In today's text, add one line after the main point: \"I was really happy to see you.\" That alone says so much.", "best": ["INTP", "You both spend weekends apart, then light up over deep talks at night. They add ideas to your plans that you'd never think of."], "hard": ["ISFJ", "They feel safe with a daily \"good morning\" and small kind gestures. If you keep sending short, to-the-point replies, they may hide how lonely they feel."], "words": [["Thinks long-term", 3], ["Falls slowly", 3], ["Only the one", 2], ["Bad at being babied", 2], ["Planned dates", 2], ["Wants the reason", 2], ["Needs alone time", 2], ["Devoted when serious", 2], ["Subtle affection", 1], ["Secret romantic", 1], ["Hides jealousy", 1], ["Deep talk first", 1], ["Opens up slowly", 1], ["Cheating? Never", 1], ["Solutions for problems", 1], ["Love in actions", 1], ["Patient in love", 1], ["Well-pondered confession", 1], ["Trust that lasts", 1]]}, "INTP": {"t": "INTP", "name": "Cat in Love", "tag": "Bashful Love Researcher", "one": "You remember every story the person you like tells you.", "desc": "You secretly check out every book and movie your crush mentions. Yet somehow, your reply comes three days later. Bookstores and museums make the best dates, and late-night calls never seem to end. When they ask, \"What do you like about me?\" you start a serious analysis, and sweet words come out sounding flat.", "good": ["You remember what they love", "You give freedom, never control", "Late-night calls are pure fun", "You think hard about their worries", "You never raise your voice in a fight"], "care": ["Three days from read to reply", "You forget anniversaries", "You explain who's right mid-fight", "You analyze why you like them", "You keep missing the moment to confess"], "tip": "When something reminds you of them, send one line right then: \"Saw this and thought of you.\" It's fine even before your thoughts are sorted.", "best": ["INTJ", "They plan the date, so all you do is enjoy the day. On the walk home, deep talks make you lose track of time."], "hard": ["ISFP", "They read feelings through faces and mood. When you go quiet to think, they may worry, \"Are you mad at me?\""], "words": [["Studying my crush", 3], ["Cuddly on a whim", 3], ["Forgets to reply", 2], ["Loves deep talks", 2], ["A bit too logical", 2], ["Freedom first", 2], ["Shy cover-up", 2], ["Loyal underneath", 2], ["Our own topics", 1], ["Answers with logic", 1], ["Late-night talks", 1], ["Home dates are fine", 1], ["Analyzes the attraction", 1], ["Aloof at first", 1], ["My own world", 1], ["Advice as analysis", 1], ["Slow-burn love", 1], ["Thinking over texting", 1], ["Nonstop on favorites", 1]]}, "ENTJ": {"t": "ENTJ", "name": "Lion in Love", "tag": "Reliable Romance Director", "one": "You're the one who makes the first move, from confession to date.", "desc": "When you like someone, you confess first, no hesitation. The anniversary dinner is booked a month ahead, and the date plan is flawless. If your partner has a problem, you start fixing it before they finish talking. But your texts end the second the business is done. Even mid-fight, you rush them with, \"So, what's the bottom line?\"", "good": ["You confess first, boldly", "You book anniversary dinners early", "You act fast when trouble hits", "You don't dodge talk of the future", "You're truly proud when they grow"], "care": ["Texts end once business is done", "You take charge even in love", "You set goals for romance too", "You rush to a verdict in fights", "You're terrible at being sweet"], "tip": "For the next date, let your partner choose just one place. The joy of being trusted stays with them for a long time.", "best": ["ENTP", "It's fun when they cut into your plan with, \"Wouldn't this be more fun?\" You two get closer after every debate."], "hard": ["ESFJ", "You both want to run the date plan. You choose by efficiency, they choose by everyone's feelings, so making plans can turn into a clash."], "words": [["Confesses first", 3], ["Future fully planned", 3], ["Leads the date", 2], ["Protector type", 2], ["Decide, then do", 2], ["Never shows weakness", 2], ["All-in on everything", 2], ["Thrives when relied on", 2], ["Hates dithering", 1], ["I'll book it", 1], ["Says it straight", 1], ["Proud of my partner", 1], ["Busy means \"seen\" only", 1], ["Cheers your growth", 1], ["Secretly gets lonely", 1], ["Clumsy when shy", 1], ["Walks the talk", 1], ["Efficient dates", 1], ["Grand anniversaries", 1]]}, "ENTP": {"t": "ENTP", "name": "Fox in Love", "tag": "Push-and-Pull Magician", "one": "The more you like someone, the more you tease them.", "desc": "The more you like someone, the more you tease them, and even your confession comes out like a joke. Changing plans mid-date with \"Actually, let's go there\" is just normal for you. Your banter is quick, and you're great at making a down partner laugh. But your replies depend on your mood, and being chased can make you cool off fast.", "good": ["You're never boring to be with", "A genius at cheering them up", "Every date is different", "You make their stories more fun", "Fight today, fine by tomorrow"], "care": ["Even your confession sounds like a joke", "You change plans mid-date", "Your replies depend on your mood", "You treat fights like debates", "Being chased cools you off"], "tip": "When your partner starts a serious talk, hold back one joke and just say, \"Yeah, and then?\"", "best": ["ENTJ", "They actually book the trip you threw out on a whim. Your jokes turn into real memories."], "hard": ["ESFP", "They want to take \"I like you\" straight. Each time you get shy and joke it off, they may feel brushed aside."], "words": [["Master of flirty games", 3], ["Falls through talk", 3], ["Lots of jokes", 2], ["Same date = boring", 2], ["Debate as a date", 2], ["Spontaneous trips", 2], ["Loves to tease", 2], ["Gets bored easily", 2], ["New-spot hunter", 1], ["Awkward when serious", 1], ["Hates being tied down", 1], ["Theorizes about love", 1], ["Last-minute plans", 1], ["Friends with exes", 1], ["Loves making you laugh", 1], ["Into smart people", 1], ["Shy about serious talks", 1], ["Love through banter", 1], ["Loves to surprise", 1]]}, "INFJ": {"t": "INFJ", "name": "Whale in Love", "tag": "Deep-Sea Lighthouse Keeper", "one": "You notice the smallest changes in your partner right away.", "desc": "You're the first to catch a change in their voice or a reply that's a little off. You reread every text several times before sending. You remember almost every special date, and it stings a little when they forget. But you hope they'll sense how you feel without saying it, and when you hit your limit, you may suddenly go silent.", "good": ["You notice their small changes", "Your texts always feel warm", "You remember every special date", "You listen deeply", "You love someone for a long time"], "care": ["You edit texts again and again", "You go quiet, hoping they'll guess", "You spot a lie in a second", "Your ideal partner bar is very high", "You vanish when you hit your limit"], "tip": "When you wish they'd just guess, send that feeling in one sentence. Putting it into words gets it across.", "best": ["INFP", "On late-night calls, they wait with \"And then?\" when you start to share what's really on your mind. You feel safe opening up."], "hard": ["ISTJ", "They feel safe with the same date at the same place every week. On nights you want to talk feelings, they may reply, \"So, what time tomorrow?\" and you drift apart."], "words": [["Reads feelings", 3], ["Believes in fate", 3], ["Heart-to-heart talks", 2], ["High ideals", 2], ["True feelings run deep", 2], ["Loyal for years", 2], ["Hopes you'll just know", 2], ["Loves writing letters", 2], ["Sensitive to my crush", 1], ["Suddenly closes off", 1], ["Finds meaning in us", 1], ["Quiet dates", 1], ["The love-advice listener", 1], ["Over-reads the room", 1], ["Dreams of the future", 1], ["Crowds are draining", 1], ["Careful with words", 1], ["Worn out from sensing", 1], ["Reads between the lines", 1]]}, "INFP": {"t": "INFP", "name": "Hedgehog in Love", "tag": "Shy Love-Letter Poet", "one": "You replay one thing they said, again and again.", "desc": "When your crush texts, you leave it on read and spend hours thinking up a reply. Around them you freeze up, and on the way home the \"I should've said that\" review begins. You'd rather confess in a letter, and you treasure even small anniversaries. After a fight, you may cry alone, replaying their words.", "good": ["You accept them as they are", "You write heartfelt letters", "You treasure small anniversaries", "Their happiness comes first", "All-in and loyal in love"], "care": ["Stuck on read, unsure what to say", "You freeze around your crush", "Your daydreams run ahead", "Every song becomes about them", "You idealize your ex"], "tip": "When you can't decide how to reply, just send one sticker first. The rest can come later, at your own pace.", "best": ["INFJ", "They put your hard-to-say feelings into words: \"You mean this?\" You can talk for hours in a quiet café."], "hard": ["ISTP", "They help with actions, like fixing your bike, more than with talk about feelings. On nights you want to hear \"I love you,\" they may feel distant."], "words": [["Great daydreamer", 3], ["Slow to open up", 3], ["Says it in letters", 2], ["Remembers every word", 2], ["Values matter", 2], ["Secretly devoted", 2], ["Feels every love song", 2], ["Gets close slowly", 2], ["Dreams of my crush", 1], ["Easily hurt", 1], ["Confessing takes courage", 1], ["A world for two", 1], ["Just as you are", 1], ["Small gifts", 1], ["Feelings in a notebook", 1], ["Avoids fights", 1], ["Late-night overthinking", 1], ["Cries alone", 1], ["Saves your messages", 1]]}, "ENFJ": {"t": "ENFJ", "name": "Dolphin in Love", "tag": "Your Personal Cheer Squad", "one": "You're your partner's biggest fan when it comes to their dreams.", "desc": "You prepare anniversary surprises weeks in advance. When your partner shares a dream, your eyes light up before theirs do. Your texts are always thoughtful, and you get along with their family and friends right away. But you don't want to be disliked, so you apologize first after fights, then later feel, \"Why is it always me?\"", "good": ["You never forget an anniversary", "All-in on planning surprises", "You praise them more than anyone", "You bond with their family", "Your texts are always thoughtful"], "care": ["You apologize first after fights", "Dates are always their pick", "You try to help them \"grow\"", "You even counsel their ex", "You expect something back for giving"], "tip": "For the next date, suggest just one place you want to go. It's okay to say, \"Will you come with me?\"", "best": ["ENFP", "They have the most fun on the dates you plan. You hype each other up, and talk of the next trip never stops."], "hard": ["ESTJ", "They value decisions and results over feelings. When you want to talk feelings, they reply, \"So, what will you do?\" and you don't quite click."], "words": [["Always on your side", 3], ["Grows you with praise", 3], ["Says it in words", 2], ["Backs your dreams", 2], ["Loves being needed", 2], ["Long calls OK", 2], ["Anniversary surprises", 2], ["Careful not to overgive", 2], ["Friends with your friends", 1], ["Always giving advice", 1], ["Thanks every day", 1], ["Expects too much", 1], ["Puts self last", 1], ["Loves future talk", 1], ["Brightens the mood", 1], ["Wants to change you", 1], ["The date planner", 1], ["Cries along", 1], ["Listens closely", 1]]}, "ENFP": {"t": "ENFP", "name": "Otter in Love", "tag": "Scenic-Route Love Explorer", "one": "Your feelings show on your face right away.", "desc": "You fall in love in an instant, and your crush can tell right away. When something good happens, you send text after text. Dates are often planned that same morning, and when you spot an interesting shop, you want to pop in. But a little silence makes you anxious fast, and jealousy shows all over your face.", "good": ["You say \"I like you\" with your whole heart", "Every day together feels like a festival", "You enjoy their dreams with them", "A master of detour dates", "You bounce back fast"], "care": ["Your texts come in endless bursts", "Silence makes you anxious fast", "Date plans get made that morning", "Jealousy shows all over your face", "Being tied down makes you want to run"], "tip": "When you feel anxious, before sending another text, try saying just one thing: \"I'm a little lonely right now.\"", "best": ["ENFJ", "They turn your spur-of-the-moment \"I want to go!\" into a plan right away. Your excitement becomes real trips and dates."], "hard": ["ESTP", "They want to enjoy the here and now. When you want to talk about the future at night, they brush it off with \"Why worry about later?\" and you feel lonely."], "words": [["All-in when in love", 3], ["Detour dates", 3], ["Feelings on my face", 2], ["Easily lonely", 2], ["Future daydreams", 2], ["Hates ruts", 2], ["Loves mutual praise", 2], ["Texting comes in waves", 2], ["Partner = best friend", 1], ["New-spot finder", 1], ["Midnight long calls", 1], ["Many reasons to love", 1], ["Plans change midway", 1], ["Feels fate easily", 1], ["Wants to hold hands", 1], ["Trips for two", 1], ["Shows you off", 1], ["Whole-body love", 1], ["Memories in photos", 1]]}, "ISTJ": {"t": "ISTJ", "name": "Beaver in Love", "tag": "Steady Nest Builder", "one": "You always get there before the meeting time.", "desc": "The night before a date, you look up the restaurant and the train home. Your texts are short and practical, yet you arrive 10 minutes early every time. You're too shy for sweet words, but you show love by always doing what you said. Still, if they say, \"Let's go somewhere else instead,\" you freeze a little inside without showing it.", "good": ["Always 10 minutes early", "Anniversaries are in your planner", "You remember every promise in texts", "No worries about cheating", "You quietly help when things go wrong"], "care": ["Always the same restaurant", "\"I love you\" is a rare, limited edition", "Sudden changes make you go quiet", "You corner them with logic after fights", "Your texts look like work memos"], "tip": "On the next date, let them pick one place. Leaving one thing undecided shows you what they really like.", "best": ["ISTP", "You plan the weekend, and they add a small detour on a whim. Even with few words, it never feels awkward, and just walking side by side feels calm."], "hard": ["INFJ", "They want to talk feelings slowly, like \"How do you feel lately?\" When you answer with actions, \"We meet, and I keep my promises,\" the talk can miss each other."], "words": [["Promises are sacred", 3], ["Slow and sure", 3], ["Always on time", 2], ["Classic dates", 2], ["Never cheats", 2], ["Solid future", 2], ["Love in actions", 2], ["Thrown by change", 2], ["Texts at set times", 1], ["Anniversaries in planner", 1], ["Saving for us", 1], ["No sudden plans", 1], ["Long relationships", 1], ["Too shy to say", 1], ["Shared chores", 1], ["Keeps every memento", 1], ["Trust first", 1], ["Practical gifts", 1], ["Same favorite spot", 1]]}, "ISFJ": {"t": "ISFJ", "name": "Bear in Love", "tag": "Warm Blanket Keeper", "one": "You remember every favorite food of the one you love.", "desc": "If your partner sneezes, there are throat drops in your bag next time you meet. You remember their favorite drink and the foods they dislike, and you quietly prepare before they ask. \"Don't push yourself\" is your go-to text. But even on lonely days you reply, \"I'm fine,\" and later sigh alone.", "good": ["You notice when they feel unwell", "You know all their favorite foods", "Perfect at-home dates", "Bandages and throat drops in your bag", "You listen to the very end"], "care": ["\"I'm fine\" hides how you feel", "You secretly wait for something back", "You can't choose where to go", "You suddenly cry at your limit", "You can't throw away old letters"], "tip": "Today, when you start typing \"I'm fine,\" add one honest word. Something like \"I was a little lonely\" is enough.", "best": ["ISFP", "When they invite you for a spontaneous walk or café, you come along with drinks and a blanket. You both dislike fights, so cozy time at home becomes your favorite."], "hard": ["INTJ", "They show love through future plans and efficiency. When they miss the small care you give every day, and your \"thank you\" never comes, you feel lonely."], "words": [["Quiet support", 3], ["Cozy home dates", 3], ["Thoughtful", 2], ["\"I'm fine\" habit", 2], ["Brings treats", 2], ["Knows your tastes", 2], ["Holds it in", 2], ["Here to stay", 2], ["\"Aren't you cold?\"", 1], ["Homemade lunches", 1], ["Can't say I'm lonely", 1], ["Waits for something back", 1], ["Wary of change", 1], ["Safety first", 1], ["Usually the listener", 1], ["Our usual spot", 1], ["Treasured keepsakes", 1], ["Shy", 1], ["Checks on your health", 1]]}, "ESTJ": {"t": "ESTJ", "name": "Elephant in Love", "tag": "Foreman of Promises", "one": "You set up every detail of the date, all at once.", "desc": "Once you decide to date someone, you set the next date, the booking, and the time to head home, right then. Your texts are short and exact: \"Sat 11am, station gate.\" Things just get done when you're around, so your partner relies on you a lot. But when they start sharing feelings after a fight, you rush with, \"So, what do you want?\"", "good": ["Your bookings are always perfect", "You always do what you say", "Clear about whether you're dating", "The most reliable in a crisis", "You don't dodge talk of the future"], "care": ["Dates turn into schedules", "You cut feelings short with conclusions", "Strict about being late", "You act fine even when tired", "Romantic gestures make you shy"], "tip": "Next time they start talking, listen to the end without cutting in. Before giving an answer, just say, \"Oh, I see,\" once.", "best": ["ESTP", "When they say, \"Let's go now!\" you look up trains and places in a flash. Their whims and your planning click, and dates move at a great pace."], "hard": ["ENFJ", "They want to put feelings into words and share them slowly. The more you wrap things up with plans and logic, the more they feel unheard."], "words": [["Clear lines matter", 3], ["I'll handle it", 3], ["Strict about time", 2], ["Marriage by plan", 2], ["Dependable", 2], ["Bottom line first", 2], ["Shy about romance", 2], ["Open about dating", 2], ["Reservations set", 1], ["Rule follower", 1], ["Runs the budget", 1], ["Can't help being right", 1], ["Fine even when tired", 1], ["Introduces you to family", 1], ["No lateness allowed", 1], ["\"Leave it to me\"", 1], ["Birthdays on schedule", 1], ["Promises in writing", 1], ["Someone to lean on", 1]]}, "ESFJ": {"t": "ESFJ", "name": "Penguin in Love", "tag": "Guardian of Anniversaries", "one": "You remember every single anniversary.", "desc": "One month, six months, even your first date, it's all in your calendar. You know their favorite foods and their friends' names, and you bake a homemade cake for their birthday. You reply fast and even check on how they're feeling. But when \"thank you\" doesn't come for days, you quietly start to build up frustration.", "good": ["You remember every anniversary", "Birthday prep starts a month early", "You make friends with their friends", "First to notice when they're sick", "You reply super fast"], "care": ["You give until you're worn out", "You wait for a \"thank you\"", "You want to know their schedule", "You save up complaints, then burst", "You worry about what others think"], "tip": "Today, ask them for one thing: \"Could you do this for me next time?\" Practice receiving, not just giving.", "best": ["ESFP", "They hype things up with \"I want to go here!\" and you save the day in photos and anniversaries. Lively, yet built to last."], "hard": ["ENTJ", "You both want to plan the dates yourselves. You pick by \"Will they be happy?\" and they pick by efficiency, so every trip plan becomes a fight over who leads."], "words": [["Remembers every anniversary", 3], ["Natural giver", 3], ["Sense of security", 2], ["Texts often", 2], ["Home cooking", 2], ["Wants a thank-you", 2], ["Partner first", 2], ["Close with your family", 1], ["Health check", 1], ["Makes our rules", 1], ["Swallows jealousy", 1], ["Cares what others think", 1], ["Thinking about marriage", 1], ["Caretaker", 1], ["Keeps promises", 1], ["Saves up complaints", 1], ["Wants to be needed", 1], ["Our shared calendar", 1]]}, "ISTP": {"t": "ISTP", "name": "Wolf in Love", "tag": "Quiet Spare-Key Maker", "one": "You don't say \"I love you,\" but you quietly help.", "desc": "If your partner says their bike has a flat, you show up with tools, no words needed. Your replies are often just one sticker, yet when they're in trouble, you move faster than anyone. You don't tie them down, so they say being with you feels easy. But when they ask, \"How do you feel about me?\" the words won't come, and you go quiet.", "good": ["You show up with tools when needed", "Easygoing, never controlling", "What you say is always true", "Comfortable silence side by side", "Leave driving and gadgets to you"], "care": ["Texts end with a sticker", "You almost never say \"I love you\"", "You go quiet without alone time", "You freeze when feelings come up", "You sometimes forget anniversaries"], "tip": "Today, after you help them, add one line: \"Because I love you.\" When they know why you act, they feel much safer.", "best": ["ISTJ", "You can follow the date plans they make without worry. You both talk little, so even a quiet drive feels comfortable."], "hard": ["INFP", "They want to share feelings in words, taking their time. Your easy \"Eh, it's fine\" can feel like you're taking their feelings lightly."], "words": [["Shows it in actions", 3], ["No control", 3], ["Few words", 2], ["Helps quietly", 2], ["The fix-it person", 2], ["Loyal at heart", 2], ["Short replies", 2], ["Alone time needed", 1], ["No lies", 1], ["Feelings talk? Hmm", 1], ["Fine with silence", 1], ["Handy", 1], ["Dependable", 1], ["Shy", 1], ["Forgets anniversaries", 1], ["Spare key = trust", 1], ["Replies with stickers", 1], ["Your seat is shotgun", 1]]}, "ISFP": {"t": "ISFP", "name": "Panda in Love", "tag": "Painter of Everyday Moments", "one": "You remember the views you saw together, forever.", "desc": "Your date plans are loose, and you love wandering into a café that catches your eye. Instead of saying \"I love you,\" you find a little thing that suits them and give it without a word. When a fight is coming, you laugh and change the subject. And when frustration builds, your replies slowly get later and later.", "good": ["Great taste in gifts", "You never rush their pace", "You enjoy simple walks", "You never put them down", "You quietly send photos of views"], "care": ["Tight schedules wear you out", "You go quiet and slip away in fights", "Frustration shows as slow replies", "You put off talk of the future", "You want to meet on a whim"], "tip": "When something bugs you, say one thing that same day. Something short like \"That made me a little lonely\" is fine.", "best": ["ISFJ", "When you want to head out on a whim, they come along with drinks and a blanket. You both dislike fights, so calm, gentle time just keeps going."], "hard": ["INTP", "They like to sort feelings with logic. When you say, \"I just didn't like it,\" they ask \"Why?\" and you get tired because you can't explain."], "words": [["My-pace romance", 3], ["Loves ordinary days", 3], ["Gifts with taste", 2], ["Avoids conflict", 2], ["Feelings through mood", 2], ["Hates being tied down", 2], ["Lazy dates", 2], ["Sharing the view", 2], ["Food dates", 1], ["Loose plans", 1], ["Few words", 1], ["Quietly steps back", 1], ["Loves holding hands", 1], ["Naps together", 1], ["Never judges", 1], ["Meets on a whim", 1], ["Future can wait", 1], ["Shy smile", 1], ["Five-senses dates", 1]]}, "ESTP": {"t": "ESTP", "name": "Cheetah in Love", "tag": "Instant-Date Sprinter", "one": "You're the first to send \"Free today?\"", "desc": "When you like someone, you text \"Wanna grab dinner today?\" before you can hesitate. A sudden weekend drive to the sea, a new activity, life with you is never dull. You don't dwell on small things, so after a fight you're fine by the next day. But when the talk turns to \"Where is this going?\" your replies suddenly get short.", "good": ["You ask them out clearly", "Spontaneous drives, anytime", "You don't carry fights to tomorrow", "You move fast in trouble", "You show them new ways to have fun"], "care": ["You get close too fast", "You change the subject when it's heavy", "Bored means more left-on-read", "Future plans are mostly TBD", "You forget promises made on a whim"], "tip": "On the way home from a fun date, ask one thing: \"How was today for you?\" Knowing how they feel makes the next date even better.", "best": ["ESTJ", "When you say, \"Let's go now,\" they look up bookings and the train home right away. Your energy and their planning click, so whims become fun memories."], "hard": ["ENFP", "They want to slowly talk about future dreams and what your relationship means. The more you say, \"As long as now is fun,\" the lighter your feelings look to them."], "words": [["Instant approach", 3], ["Active dates", 3], ["Spur-of-the-moment trips", 2], ["No mind games", 2], ["Living for now", 2], ["Bored means \"seen\"", 2], ["Quick to act", 2], ["Not into heavy talk", 2], ["Sports dates", 1], ["Fired up by games", 1], ["Surprise trips", 1], ["Never dwells", 1], ["Promises on a whim", 1], ["Confident", 1], ["Brings friends along", 1], ["Quick to bounce back", 1], ["Future plans TBD", 1], ["Love through touch", 1], ["\"Free today?\"", 1]]}, "ESFP": {"t": "ESFP", "name": "Parakeet in Love", "tag": "Heart-Flutter Fireworks Artist", "one": "Every time you meet, you throw a little party.", "desc": "When you fall for someone, you go all in, with matching items and small surprises on date days. Your phone fills with photos after every date, and on the way home you text, \"That was so fun!\" You show love straight through words and actions, so your partner really feels loved. But if a reply is a little late, you worry, \"Did they lose interest?\"", "good": ["You say \"I like you\" straight", "Date photos keep piling up", "You notice and praise their changes", "You make them laugh when they're down", "Spontaneous dates are a blast"], "care": ["Slow replies make you anxious", "You promise on impulse, then regret it", "You laugh fights away", "You go quiet when the future comes up", "Days apart feel very lonely"], "tip": "Tonight, spend an evening doing nothing together. When quiet time feels \"calm\" too, love lasts longer.", "best": ["ESFJ", "They save your \"I want to go here!\" moments in anniversaries and photo albums. Fun and security together, lively and lasting."], "hard": ["ENTP", "They enjoy bringing debate and mind games into love. When you share, \"I was lonely,\" and get logic back, you can feel left alone."], "words": [["All-out love", 3], ["Loves surprises", 3], ["Love gives me energy", 2], ["Lonely when apart", 2], ["Spontaneous dates", 2], ["Great at praise", 2], ["Sweet and clingy", 2], ["Photos pile up", 1], ["Every day's an event", 1], ["Lots of touch", 1], ["Jealousy shows", 1], ["Loves love talk", 1], ["Falls at first sight", 1], ["Instant replies", 1], ["Future talk is hard", 1], ["Bright even in fights", 1], ["Friend-approved couple", 1], ["Easily moved to tears", 1], ["Moody", 1], ["Life of the party", 1]]}}};
var D={"NICK": {"INTJ": "Has the answer before speaking", "INTP": "Lost down a search rabbit hole", "ENTJ": "\"Fine, I'll decide\"", "ENTP": "\"But what if...\" on repeat", "INFJ": "Notices without being told", "INFP": "A movie theater in their head", "ENFJ": "Can't help taking care of people", "ENFP": "Excitement comes first", "ISTJ": "Turns it in before the deadline", "ISFJ": "Already helping before anyone asks", "ESTJ": "Makes the schedule first", "ESFJ": "Somehow always the organizer", "ISTP": "Touches it before reading the manual", "ISFP": "Picks whatever they love", "ESTP": "Moving before thinking", "ESFP": "Decides on a whim"}, "ARUARU": {"INTJ": ["Already knows the answer in meetings, but stays quiet", "Gets quietly annoyed when plans fall apart", "Would rather skip small talk and get to the point", "Works fastest on tasks they can finish alone", "Can't understand people who decide \"just because\""], "INTP": ["Starts looking something up and ends up somewhere else entirely", "Wants to ask, \"But how do we define that?\"", "Things they don't care about just won't stick", "Thinks more clearly at night", "Explanations tend to run long"], "ENTJ": ["Can't stand meetings that never decide anything", "Ends up running the show without noticing", "Hates wasted time more than anything", "The bigger the goal, the more fired up", "Can't say no when people count on them"], "ENTP": ["Says the idea out loud, then thinks about it", "Grows every conversation with \"But what if...\"", "Gets bored fast", "Debating isn't fighting, it's playing", "Downloads every new app just to try it"], "INFJ": ["Notices someone's off before they say a word", "Rarely shows their real feelings", "Needs alone time after crowds", "Can't spend time on things that feel pointless", "Everyone comes to them for advice, but they never ask for any"], "INFP": ["Rehearses conversations in their head", "Suddenly talks a lot when it's about something they love", "Practical talk wears them out", "Remembers things people said years ago", "Won't give up on what feels right inside"], "ENFJ": ["Watches everyone's faces while talking", "Can't say no when asked", "Puts themselves last", "Brings up a topic when the room goes quiet", "Feels as happy about others' growth as their own"], "ENFP": ["Conversations jump three topics at once", "So many things to do, they're stuck in traffic", "Cleans their room right before a deadline", "Gets close with people they just met", "Loses interest all at once when bored"], "ISTJ": ["Finishes plans ahead of schedule", "Bothered by people who break the rules", "Everything has its set place", "Quietly thrown off by sudden changes", "Doesn't want to change a method once it's set"], "ISFJ": ["Notices first and acts first", "Says \"I'm fine\" while holding it in", "Remembers what people like", "Doesn't want the spotlight", "Happy when people count on them"], "ESTJ": ["Settles the plan before anything else", "Vague instructions are irritating", "Strict about time", "Sees every job through to the end", "Can sound harsh with people close to them"], "ESFJ": ["Somehow ends up organizing the get-together", "Keeps an eye on everyone's health and mood", "Gets lonely after too much time alone", "Remembers anniversaries", "Wants to check that nobody dislikes them"], "ISTP": ["Touches it before reading the manual", "Reads the group chat but never replies", "Not into pointless chatter", "When something breaks, tries fixing it first", "Stops dead the moment interest runs out"], "ISFP": ["Can't choose something that doesn't click", "Their own taste over the latest trend", "Hates being rushed", "Particular about photos and how things are arranged", "Doesn't get angry, but inside won't budge"], "ESTP": ["Body moves before the brain does", "Boredom is the worst", "Reads the room in seconds", "Better at handling things on the spot than planning", "Cleanup can wait"], "ESFP": ["Makes plans on a whim", "Loves taking photos", "Feeling down? A good sleep fixes it", "Often the one who lights up the room", "Can't keep at dull tasks for long"]}, "TCOMPAT": {"INTJ": {"m": "ENTP", "why": "An idea person who brings fresh air to your strategy."}, "ENTP": {"m": "INTJ", "why": "Turns your sparks into a solid plan."}, "INTP": {"m": "ENTJ", "why": "The doer who shapes your ideas and moves them forward."}, "ENTJ": {"m": "INTP", "why": "The brains who widens your thinking with fresh views."}, "INFJ": {"m": "ENFP", "why": "Brightly draws out the feelings you keep inside."}, "ENFP": {"m": "INFJ", "why": "Quietly deepens the dreams you spread wide."}, "INFP": {"m": "ENFJ", "why": "A reassuring guide who truly cheers on your ideals."}, "ENFJ": {"m": "INFP", "why": "A sincere person who needs your kindness."}, "ISTJ": {"m": "ESTP", "why": "Brings spark and drive to your steady ways."}, "ESTP": {"m": "ISTJ", "why": "Backs up your momentum with solid ground."}, "ISFJ": {"m": "ESFP", "why": "The mood-lifter who brightens your seriousness."}, "ESFP": {"m": "ISFJ", "why": "A reassuring presence who quietly supports your fun."}, "ISTP": {"m": "ESTJ", "why": "Sets up the place where your skills can shine."}, "ESTJ": {"m": "ISTP", "why": "A calm expert you can count on when it matters."}, "ISFP": {"m": "ESFJ", "why": "Warmly supports you as you go at your own pace."}, "ESFJ": {"m": "ISFP", "why": "Easygoing and real, their honest sense of things is soothing."}}, "GAP_USE": {"IE": {"h": "充電｜内向き → 外向き に変身", "t": "ほんとうは一人で充電する人が、人と関わる力を装備した状態。人前のあとにどっと疲れるのは、気のせいじゃなく装備の重さです。予定のあとに“ひとり時間”を確保すると、回復が一気に速くなります。"}, "EI": {"h": "充電｜外向き → 内向き に変身", "t": "ほんとうは人といて充電する人が、今はひとりモード。最近なんとなく元気が出ないなら、原因は“人との時間の不足”かも。気のおけない人と会う予定をひとつ入れるだけで、驚くほど復活します。"}, "SN": {"h": "見方｜現実派 → 直感派 に変身", "t": "地に足のついた現実派が、ひらめきで動く力を獲得。アイデアが浮かんでも「ほんとに大丈夫？」と不安になるのは、素の現実感覚が生きている証拠。ひらめきを素の現実力で検算すれば最強です。"}, "NS": {"h": "見方｜直感派 → 現実派 に変身", "t": "本来ひらめき型のあなたが、現実的にふるまう力を装備。ときどき無性に“夢の話”がしたくなるのは、素の顔の呼吸です。空想の時間はサボりじゃなく、あなたの充電です。"}, "TF": {"h": "決め方｜論理派 → 共感派 に変身", "t": "本来スジで決める人が、人に合わせて受け止める力を獲得。合わせたあとに「本音を言えばよかった」とモヤモヤしやすいタイプ。大事な決断だけは、素のロジックに戻って決めると後悔しません。"}, "FT": {"h": "決め方｜共感派 → 論理派 に変身", "t": "本来は気持ちで決める人が、冷静に判断する鎧を装備。クールに見えて、内側では感情がちゃんと動いています。ときどき“好きか嫌いか”だけで選ぶと、心の疲れがすっと取れます。"}, "JP": {"h": "動き方｜計画派 → 自由派 に変身", "t": "本来は計画派なのに、流れに乗る柔軟さを獲得。自由に見えて、心のどこかで“決まっていない不安”を感じやすい人です。ざっくりでも予定を置くと、安心して楽しめます。"}, "PJ": {"h": "動き方｜自由派 → 計画派 に変身", "t": "本来は自由派なのに、段取りの力を身につけた人。きっちりこなせるのに、たまに全部投げ出したくなるのはこのせい。“予定のない日”を先にカレンダーに入れておくのがコツです。"}}, "COLOR": {"INTJ": {"name": "深い藍", "hex": "#27406B", "line": "夜明け前の藍。静かに全体を見渡す色。"}, "INTP": {"name": "アイスブルー", "hex": "#79B6D9", "line": "澄んだ氷の青。思考が透きとおる色。"}, "ENTJ": {"name": "クリムゾン", "hex": "#C8102E", "line": "燃える深紅。目標へ突き進む色。"}, "ENTP": {"name": "エレクトリックオレンジ", "hex": "#FF6A2C", "line": "火花のオレンジ。刺激を生み出す色。"}, "INFJ": {"name": "アメジスト", "hex": "#6A4C93", "line": "神秘の紫。静かな理想を秘めた色。"}, "INFP": {"name": "ラベンダー", "hex": "#B79CE0", "line": "淡い藤色。やさしく夢みる色。"}, "ENFJ": {"name": "コーラル", "hex": "#FF8364", "line": "夕日のコーラル。人を照らすあたたかな色。"}, "ENFP": {"name": "ビビッドイエロー", "hex": "#FFD23F", "line": "弾ける黄色。その場を明るくする色。"}, "ISTJ": {"name": "ディープグリーン", "hex": "#2F6B5E", "line": "落ち着いた深緑。ぶれない芯の色。"}, "ISFJ": {"name": "ソフトピーチ", "hex": "#F4C9A8", "line": "やわらかな桃色。そっと包む色。"}, "ESTJ": {"name": "ロイヤルブルー", "hex": "#2457C5", "line": "堂々のブルー。頼れる芯の色。"}, "ESFJ": {"name": "ウォームローズ", "hex": "#F77FA1", "line": "あたたかな薔薇色。みんなを和ませる色。"}, "ISTP": {"name": "ガンメタル", "hex": "#8C97A0", "line": "クールな銀。無駄のない色。"}, "ISFP": {"name": "セージグリーン", "hex": "#8FBF9F", "line": "やさしい若草。自然体でいられる色。"}, "ESTP": {"name": "ネオンレッド", "hex": "#FF3B30", "line": "躍動の赤。動くほど光る色。"}, "ESFP": {"name": "ホットピンク", "hex": "#FF2E9A", "line": "華やぐマゼンタ。主役のオーラの色。"}}, "URA": {"INTJ": "じつは、頭の中では何手も先まで読んで、もう一人で完結している。", "INTP": "じつは、「なんで？」が止まらず、夜中に関係ない調べ物で時間が溶ける。", "ENTJ": "じつは、任されないとソワソワ。仕切りたくて手がうずうずしている。", "ENTP": "じつは、思いつきを口に出してから「どうしよう」と考えはじめる。", "INFJ": "じつは、ニコニコしながら相手の本音を静かに見抜いている。", "INFP": "じつは、頭の中で壮大なストーリーが毎日上映されている。", "ENFJ": "じつは、みんなを気づかうあまり、自分のことは後回しにしがち。", "ENFP": "じつは、やりたいこと多すぎて、半分は途中で次へ移っている。", "ISTJ": "じつは、段取りを乱す人に、心の中でこっそりイラッとしている。", "ISFJ": "じつは、「大丈夫」と言いながら、いちばん我慢している。", "ESTJ": "じつは、ゆるい計画を見ると、つい口を出したくてうずうず。", "ESFJ": "じつは、嫌われてないかな…と、こっそり空気を確認している。", "ISTP": "じつは、興味ないことには無関心。好きなことには無限に集中する。", "ISFP": "じつは、マイペースに見えて、譲れない美学はかなり頑固。", "ESTP": "じつは、退屈がいちばん苦手。刺激がないと自分で作りにいく。", "ESFP": "じつは、楽しそうにしながら、場の空気をいちばん読んでいる。"}, "QUOTE": {"INTJ": ["So what's the end goal?", "There's a more efficient way to do that", "All within expectations"], "INTP": ["Well, that depends on the definition", "Let me look into it", "I get the logic. But why?"], "ENTJ": ["Bottom line:", "Who does it, and by when?", "Leave it to me. I'll decide"], "ENTP": ["Okay, but what if", "Isn't that interesting?", "Let me play devil's advocate"], "INFJ": ["What do you really want?", "I kind of knew already", "Won't that hurt them?"], "INFP": ["Is that really me?", "Let me think about it", "Isn't \"because I love it\" enough?"], "ENFJ": ["What does everyone think?", "It's okay, let's do it together", "You can do it"], "ENFP": ["That's so good!", "So I just had an idea", "Let's just try it!"], "ISTJ": ["Last time, we did it like this", "I'll confirm and get back to you", "Those are the rules"], "ISFJ": ["Are you okay? Not overdoing it?", "I'll take care of it", "If everyone's fine with it, so am I"], "ESTJ": ["Let's set the schedule first", "So what's the deadline?", "Rules are rules"], "ESFJ": ["Let's all do it together", "I brought snacks!", "Isn't that unfair to her?"], "ISTP": ["You'll see once you try", "Either way is fine", "Hand it over, I'll fix it"], "ISFP": ["It just felt nice", "I'll go at my own pace", "It's hard to put into words"], "ESTP": ["Let's just go", "Moving beats thinking", "It'll work out"], "ESFP": ["If it's fun, isn't that enough?", "How about right now?", "Let's take a photo!"]}};
var QZ={"Q": [{"ax": "EI", "p": "E", "q": "After a few weekends with no plans, I want to reach out to someone", "ex": "On Sunday night after a whole weekend at home, I'm the one texting \"Dinner next week?\""}, {"ax": "SN", "p": "S", "q": "When I start something new, I check the steps and how-to first", "ex": "With a new appliance, I read the manual or watch a how-to video before using it"}, {"ax": "TF", "p": "T", "q": "When someone comes to me with a problem, I start thinking of solutions", "ex": "While a friend vents, I'm already working out \"What if you tried this?\" in my head"}, {"ax": "JP", "p": "J", "q": "I finish my tasks before the deadline", "ex": "Work due Friday is already done by Wednesday"}, {"ax": "AT", "p": "A", "q": "Even when I fail, I can move on fairly quickly", "ex": "If I make a mistake at work, I don't carry it past that day"}, {"ax": "EI", "p": "I", "q": "I make sure to have time alone before and after seeing people", "ex": "The day after a night out, I keep my schedule empty and stay home"}, {"ax": "SN", "p": "N", "q": "When I talk, the topic keeps branching out", "ex": "We start on travel plans and somehow end up on where we want to live someday"}, {"ax": "TF", "p": "F", "q": "When someone comes to me with a problem, I take in their feelings first", "ex": "After listening, the first thing I say is \"That sounds really hard\""}, {"ax": "JP", "p": "P", "q": "When plans suddenly change, I actually enjoy it", "ex": "When I hear \"Today's plans are off,\" I get excited about what to do instead"}, {"ax": "AT", "p": "T", "q": "I keep going back over things that are already done", "ex": "After a conversation, I wonder, \"Was that the right way to say it?\""}, {"ax": "EI", "p": "E", "q": "Even at gatherings where I know few people, I start conversations", "ex": "At a party with new faces, I'm the one asking the person next to me questions"}, {"ax": "SN", "p": "S", "q": "When I talk, I include concrete numbers and facts", "ex": "I say \"We waited 40 minutes\" instead of \"It was super crowded\""}, {"ax": "TF", "p": "T", "q": "For big decisions, I weigh the pros and cons", "ex": "When moving or changing jobs, I write out the conditions and compare them"}, {"ax": "JP", "p": "J", "q": "I feel calmer when my weekend plans are set in advance", "ex": "If it's Friday night and the weekend still has no plans, I get restless"}, {"ax": "AT", "p": "A", "q": "I don't really worry about what people think of me", "ex": "If my posts get few reactions, it doesn't bother me much"}, {"ax": "EI", "p": "I", "q": "Before speaking, I sort out my thoughts in my head first", "ex": "When asked for my opinion in a meeting, I want a moment to think"}, {"ax": "SN", "p": "N", "q": "I care about \"what it all comes down to\" before the details", "ex": "During a long explanation, I want to sum it up: \"So basically...\""}, {"ax": "TF", "p": "F", "q": "When I decide, I think about how the people involved will feel", "ex": "Even if a plan is right, I drop it if it might hurt someone"}, {"ax": "JP", "p": "P", "q": "I really get going only when the deadline is close", "ex": "Work I had two weeks for, I finish in a focused push over the last three days"}, {"ax": "AT", "p": "T", "q": "I easily notice changes in people's reactions or expressions", "ex": "If a reply feels curt, I worry I've upset them"}, {"ax": "EI", "p": "E", "q": "My thoughts come together as I talk them through with someone", "ex": "When I'm torn, my answer becomes clear while I'm talking to a friend"}, {"ax": "SN", "p": "S", "q": "I trust what I've tried and checked for myself", "ex": "Even if a restaurant gets great reviews, I won't call it good until I've been"}, {"ax": "TF", "p": "T", "q": "When we disagree, I explain my reasons rather than go along", "ex": "If I'm not convinced by a plan, I say \"That would cause trouble for X\""}, {"ax": "JP", "p": "J", "q": "I decide what to buy before I go shopping", "ex": "I take a list to the supermarket and buy exactly what's on it"}, {"ax": "AT", "p": "A", "q": "I don't second-guess decisions I've made myself", "ex": "After choosing something while shopping, I don't think \"I should've gotten the other one\""}, {"ax": "EI", "p": "I", "q": "Deep talks with a few people are more fun than a big group", "ex": "I'd pick a long chat with two or three people over a party of ten"}, {"ax": "SN", "p": "N", "q": "I often imagine \"What if...\"", "ex": "On my commute, I think \"What if I weren't in this job?\""}, {"ax": "TF", "p": "F", "q": "When the mood around me is tense, I can't settle either", "ex": "If someone's in a bad mood, I can't focus on my own stuff"}, {"ax": "JP", "p": "P", "q": "For trips, I plan roughly and figure things out once I'm there", "ex": "I book only the place to stay and decide where to go based on how I feel that day"}, {"ax": "AT", "p": "T", "q": "Even after deciding, I wonder if it was really the right choice", "ex": "After ordering, I keep eyeing the other dishes on the menu"}, {"ax": "EI", "p": "E", "q": "After seeing people, I have more energy", "ex": "On the way home from three hours of talking, \"I want to talk more\" beats feeling tired"}, {"ax": "SN", "p": "S", "q": "I'm better at improving the current way than inventing a new one", "ex": "Rather than rethinking from scratch, I cut the waste from the current steps"}, {"ax": "TF", "p": "T", "q": "If I'm praised, \"reliable\" makes me happier than \"kind\"", "ex": "Hearing \"You saved me, as expected!\" makes me feel most rewarded"}, {"ax": "JP", "p": "J", "q": "I finish one thing before moving on to the next", "ex": "While I'm in the middle of a book, I don't open the next one"}, {"ax": "AT", "p": "A", "q": "Even with something new, I feel it'll work out somehow", "ex": "When I'm handed a new kind of job, excitement wins over worry"}, {"ax": "EI", "p": "I", "q": "I reply to messages when it suits me rather than right away", "ex": "Even when I see a message, I wait until I've settled down to reply"}, {"ax": "SN", "p": "N", "q": "I'd rather try a new way than stick to the usual one", "ex": "Even though I have my usual route, I try a street I don't know"}, {"ax": "TF", "p": "F", "q": "When I team up with someone, I choose by personality over ability", "ex": "I'd rather work with someone pleasant than someone who's just good at the job"}, {"ax": "JP", "p": "P", "q": "Working on several things at once suits me", "ex": "I switch back and forth between three tasks depending on my mood"}, {"ax": "AT", "p": "T", "q": "Before important moments, I want to check things again and again", "ex": "I reread an email three times before sending it"}, {"ax": "EI", "p": "E", "q": "In group conversations, I find I'm the one doing the talking", "ex": "In a group of five, I'm more often the talker than the listener"}, {"ax": "SN", "p": "S", "q": "When I learn something, I want the steps in order first", "ex": "For a new app, I'd rather learn one action at a time than get the big picture"}, {"ax": "TF", "p": "T", "q": "When I hear someone's opinion, I first wonder whether it's correct", "ex": "While a friend talks, I'm thinking, \"Is that really true?\""}, {"ax": "JP", "p": "J", "q": "I check my belongings before I leave the house", "ex": "Every time, I check my wallet, keys and phone one by one"}, {"ax": "AT", "p": "A", "q": "When I'm praised, I can simply accept it", "ex": "When someone says \"That's amazing,\" I can just say \"Thank you\""}, {"ax": "EI", "p": "E", "q": "I'm fairly excited to go to gatherings full of people I don't know", "ex": "I happily join events I'm invited to, even if I won't know anyone"}, {"ax": "SN", "p": "S", "q": "I start with the way that worked before", "ex": "When planning a trip, I follow the route and booking method that went well last time"}, {"ax": "TF", "p": "T", "q": "For important things, I set my feelings aside before deciding", "ex": "Even when I'm angry, I sleep on it before deciding"}, {"ax": "JP", "p": "J", "q": "I like writing out my to-dos and crossing them off", "ex": "I jot down my plans for the day and draw a line through each one I finish"}, {"ax": "AT", "p": "T", "q": "Even when I'm praised, I notice where I fell short", "ex": "Even when told \"That was great,\" I remember the parts that didn't go well"}, {"ax": "EI", "p": "I", "q": "After a full day of talking with people, I want time alone at night", "ex": "Even after a fun night out, I want to walk home quietly by myself"}, {"ax": "SN", "p": "N", "q": "When I hear someone's story, other ideas pop up right away", "ex": "From a friend's story, I'm already thinking \"Then you could also do X\""}, {"ax": "TF", "p": "F", "q": "When someone's in trouble, I help before taking care of my own things", "ex": "Even when I'm busy, I find myself helping a coworker"}, {"ax": "JP", "p": "P", "q": "When plans get too detailed, I actually lose motivation", "ex": "When someone makes a minute-by-minute plan, it suddenly feels like a chore"}, {"ax": "AT", "p": "A", "q": "I don't get very nervous speaking in front of people", "ex": "Even when suddenly asked for my opinion, I can speak calmly"}, {"ax": "EI", "p": "I", "q": "Texting feels easier than calling", "ex": "When I need something, I send a message rather than call"}, {"ax": "SN", "p": "N", "q": "I'm drawn to things nobody has done yet", "ex": "I'm more curious about what's coming next than what's popular now"}, {"ax": "TF", "p": "F", "q": "If I'm praised, \"kind\" makes me happier than \"reliable\"", "ex": "Hearing \"Thanks for always looking out for me\" makes me feel most rewarded"}, {"ax": "JP", "p": "P", "q": "When an idea hits, I start even if I'm not fully ready", "ex": "I start cooking a dish I'm curious about even if I'm missing a few ingredients"}, {"ax": "AT", "p": "T", "q": "My mood goes up and down quite a lot", "ex": "Within the same week, I have very upbeat days and days when I feel low"}], "TB": {"EI": {"q": "At the end of a tiring week, what recharges you on Friday night?", "a": ["Dinner with friends", "E"], "b": ["Time alone at home", "I"]}, "SN": {"q": "When you get a new job to do, what do you want to know first?", "a": ["The exact steps and past examples", "S"], "b": ["The goal and the big picture", "N"]}, "TF": {"q": "A friend is about to make a clearly wrong choice. What do you do?", "a": ["Tell them my reasons clearly", "T"], "b": ["Ask how they feel first, then think", "F"]}, "JP": {"q": "You get a week off. What do you do?", "a": ["Plan things out in advance", "J"], "b": ["Decide nothing and go with the mood each day", "P"]}, "AT": {"q": "A big presentation is tomorrow. How are you the night before?", "a": ["Trust it'll work out and go to bed early", "A"], "b": ["Keep going over my prep again and again", "T"]}}};
var COMBO={"ISTJ>INTJ": {"karai": "You play the far-sighted one, but when the unexpected hits, you're the first to freeze.", "name": "The Visionary Who Loves Precedent", "atari": ["[[今:You talk up the five-year plan]], but [[本:deep down, last year's way of doing things is what feels safest]].", "[[今:Even in a brainstorm for fresh ideas]], [[本:part of your brain is quietly opening the old files folder]]."]}, "ISTJ>INTP": {"karai": "You call yourself a free spirit, yet your desk drawers have been labeled and lined up for years.", "name": "The Lost Researcher Who Never Runs Late", "atari": ["[[今:Once you start digging into something, you can't stop]], yet [[本:your body somehow never forgets a due date]].", "[[今:You say \"eh, it'll work out\"]], then [[本:go home and lay out tomorrow's things in a neat little row]]."]}, "ISTJ>ENTJ": {"karai": "Every time someone calls you a dependable leader, you trudge home and buy yourself a sweet treat to recover.", "name": "The Backstage Pro Turned Leader", "atari": ["[[今:You run the meeting with total confidence]], while [[本:inside you're screaming \"let me be alone\" the second it ends]].", "[[今:You set big, bold goals]], but [[本:what really fires you up is knocking out the small steps one by one]]."]}, "ISTJ>ENTP": {"karai": "You sell yourself as a rule-breaker, but you memorized every rule before breaking it. Classic honor student.", "name": "The Very Orderly Contrarian", "atari": ["[[今:You kick off a debate with \"okay, but what if\"]], while [[本:secretly hoping it lands on the usual conclusion]].", "[[今:After jumping on a new project on a whim]], [[本:you lie awake at midnight listing every possible risk]]."]}, "ISTJ>INFJ": {"karai": "You say feelings matter most, but if someone's excuse for being late is \"feelings,\" they are not forgiven.", "name": "The Good Listener With a Manual", "atari": ["[[今:You nod deeply as a friend shares their worries]], while [[本:your brain is already bullet-pointing the solutions]].", "[[今:You've learned to read the room and act on it]], but [[本:what you do next still goes by the manual]]."]}, "ISTJ>INFP": {"karai": "People think you're dreamy, but you remember every cent you've ever lent, and the date.", "name": "The Dreamy Accountant", "atari": ["[[今:You lose yourself in your favorite movie's world]], yet [[本:you've already worked out the runtime and the train home]].", "[[今:The day after writing \"I want to live as myself\" in your journal]], [[本:you still take the usual route to work at the usual time]]."]}, "ISTJ>ENFJ": {"karai": "You're great at guiding people, but mess with your schedule and your smile stays while your eyes stop smiling.", "name": "The Meticulous Caretaker", "atari": ["[[今:You take on everyone's problems]] while [[本:secretly wishing you were home eating your usual dinner]].", "[[今:Your pep talks for juniors are full of heart]], and [[本:you wrote them down in advance]]."]}, "ISTJ>ENFP": {"karai": "After a day of playing the fun one, all you can handle that night is your usual dinner and your usual videos.", "name": "Excitement, Pending Paperwork", "atari": ["[[今:Right after a quick \"That sounds fun, I'm in!\"]], [[本:you go home and research the packing list and budget with a straight face]].", "[[今:You pick up new hobbies one after another]], but [[本:you read every manual from page one before starting]]."]}, "ISTJ>ISTJ": {"karai": "\"That's how we did it last time\" is your ultimate catchphrase. New ideas usually get ignored at least once.", "name": "The Unshakable Human Timetable", "atari": ["Your morning routine hasn't changed in ten years, and you even know what you'll grab at the checkout.", "Turning work in three days early is just normal to you, so last-minute people are a total mystery."]}, "ISTJ>ISFJ": {"karai": "They call you thoughtful, but every thoughtful gesture comes with a reason and a precedent.", "name": "Kindness, Running on Schedule", "atari": ["[[今:You've learned to go along and say \"sure, that's fine\"]], but [[本:your mental notebook logs it as an exception]].", "[[今:You've gotten good at handing out snacks]], yet [[本:the count and the order were planned to perfection]]."]}, "ISTJ>ESTJ": {"karai": "You look like the steady organizer, but every time you speak in front of a group, you quietly lose a year of your life.", "name": "The Craftsperson Who Does Social", "atari": ["[[今:After running the party flawlessly]], [[本:you skip the after-party, head straight home, and feel quietly satisfied]].", "[[今:You're used to giving instructions in front of people]], but [[本:every time, you wish you could just send it all by email]]."]}, "ISTJ>ESFJ": {"karai": "You're the kind party planner, but you remember exactly who bailed last minute when next year's guest list comes around.", "name": "The Thoughtful Host Who's a Craftsperson", "atari": ["[[今:You keep the birthday party lively]] while [[本:silently calculating when the cake needs to come out to stay on schedule]].", "[[今:Your group-chat replies are fast and warm]], but [[本:you reread each one three times for typos first]]."]}, "ISTJ>ISTP": {"karai": "You act like you go with the flow, but change your plans suddenly and your bad mood shows all day.", "name": "The Toolbox That Ditched the Plan", "atari": ["[[今:You think you've become a no-plans person]], yet [[本:somehow you've already looked up where the restrooms are on your trip]].", "[[今:You work by feel now]], but [[本:you can't relax until every tool is back in its spot]]."]}, "ISTJ>ISFP": {"karai": "You think you live by feel, but at your favorite café it's always the same seat, same order.", "name": "Picking Favorites by Timetable", "atari": ["[[今:You choose clothes because you love them now]], but [[本:you still check the care label and compare prices first]].", "[[今:After rearranging your room on a whim]], [[本:you quietly decide the old layout was best and put it back]]."]}, "ISTJ>ESTP": {"karai": "You look like a person of action, but your bold moves often just retrace past successes, step by step.", "name": "The Cautious Thrill-Seeker", "atari": ["[[今:You charge ahead with \"let's just try it\"]] while [[本:mentally lining up insurance and three escape routes]].", "[[今:You can say yes to last-minute plans now]], but [[本:you open your budget app at home and have a small regret session]]."]}, "ISTJ>ESFP": {"karai": "People peg you as a party lover, but deep down you'd rather rewatch the same show from episode one.", "name": "The Life of the Party Keeping the Books", "atari": ["[[今:After warming up karaoke by singing first]], [[本:you casually handle the entire bill split too]].", "[[今:The morning after \"let's just enjoy the moment!\"]], [[本:you're up thirty minutes early making up for yesterday]]."]}, "ISFJ>INTJ": {"karai": "You play the cool strategist, yet everyone's birthday is saved in your phone calendar.", "name": "The Caretaker Playing It Cool", "atari": ["[[今:That errand you logically cut]]? [[本:You end up quietly doing it for them that night]].", "[[今:In meetings you can flatly say \"this is inefficient\"]], yet [[本:you're still worrying about how they took it once you're home]]."]}, "ISFJ>INTP": {"karai": "You're great at acting uninterested in people. But we all know you leave messages on read and agonize over a reply for thirty minutes.", "name": "The Busybody Hiding Behind Logic", "atari": ["[[今:You start with \"logically speaking\"]], but [[本:you always end up siding with whoever's struggling most]].", "[[今:You can't stop researching what interests you]], but [[本:you've never once forgotten your friends' favorite foods]]."]}, "ISFJ>ENTJ": {"karai": "You wear the face of a tough leader, but you lie awake replaying every harsh word you said.", "name": "The Pushy Nurse", "atari": ["[[今:You can lead a team and press people on the numbers now]], then [[本:rush out to buy them snacks afterward]].", "[[今:The moment you declare \"I'll decide\"]], [[本:you're scanning every face for anyone who disagrees]]."]}, "ISFJ>ENTP": {"karai": "You've gotten good at running the room with clever arguments, but really you just don't want anyone to dislike you.", "name": "The Wisecracking School Nurse", "atari": ["[[今:After getting a debate going with \"okay, but what if\"]], [[本:you privately message the one person you went too hard on]].", "[[今:You've become the one who jumps on new things]], yet [[本:you're the first to notice when the miso soup at home tastes different]]."]}, "ISFJ>INFJ": {"karai": "People call you deep, but honestly, your list of worries just keeps getting longer.", "name": "Worrying All the Way Into the Future", "atari": ["[[本:It's not just your friend's worries today]] — [[今:you picture three years ahead and ache over it on your own]].", "[[今:You've started talking about ideals]], but [[本:your hands are somehow already washing the dishes in front of you]]."]}, "ISFJ>INFP": {"karai": "You play the sensitive artist, but you can't relax unless you're being useful to someone.", "name": "The Dreamer Who Forgot the Plan", "atari": ["[[今:You get absorbed in a favorite story]], but [[本:if family is late coming home, you're too restless to read]].", "[[今:You decided to go at your own pace]], yet [[本:the moment someone asks, you clear your whole schedule]]."]}, "ISFJ>ENFJ": {"karai": "The reliable-mentor role suits you now. Your biggest weakness: never telling anyone how tiring it is to be relied on.", "name": "The Unsung Helper, Now Center Stage", "atari": ["[[今:You can give pep talks in front of everyone now]], but [[本:you'd really rather be quietly pouring tea in the back]].", "[[今:Every time you take on leading the group]], [[本:you get home and sit in the dark for a while]]."]}, "ISFJ>ENFP": {"karai": "You look like you live on vibes, but when plans change suddenly, you're the first to panic inside.", "name": "The Bubbly Guardian", "atari": ["[[今:You look like you're having more fun than anyone]], yet [[本:you keep scanning for whoever's left out of the circle]].", "[[今:You planned the trip on a whim]], but [[本:the night before, you packed motion-sickness pills for everyone]]."]}, "ISFJ>ISTJ": {"karai": "You're known as the strict one, but after being tough on someone, you rehearse your excuses to them a hundred times in your head.", "name": "The Stickler Who Locked Away Their Heart", "atari": ["[[今:You can turn people down by the rules now]], but [[本:watching them walk away still stings a little]].", "[[今:At work you say \"those are the rules\" without blinking]], yet [[本:at home you change the menu every day to suit everyone]]."]}, "ISFJ>ISFJ": {"karai": "\"I'm fine\" is your catchphrase. But you say it with the same face when you're not, so nobody ever notices.", "name": "The Born Guardian Angel", "atari": ["The moment someone sneezes, you've already pulled a tissue from your bag. Hands first, thinking later.", "You remember a friend saying \"I love this\" a year ago and casually hand it over on their birthday, to their surprise."]}, "ISFJ>ESTJ": {"karai": "You look like the capable one, but really you're working this hard to hear someone say \"thank you.\"", "name": "The Soothing Type Who Runs the Show", "atari": ["[[今:You make the schedule and tell everyone what to do]], while [[本:rewording the ends of your sentences so they don't sound harsh]].", "[[今:You're in a position to say \"stick to what we agreed\"]], yet [[本:you can't help asking why someone couldn't]]."]}, "ISFJ>ESFJ": {"karai": "People mistake your inability to say no for being social, and suddenly every weekend is booked.", "name": "The Tea-Maker at a Busy Party", "atari": ["[[今:On the way home from hosting a perfect night out]], [[本:you put in earbuds and desperately reclaim some time to talk to no one]].", "[[今:You're laughing at the center of the group]], but [[本:tea with a couple of people is really more your speed]]."]}, "ISFJ>ISTP": {"karai": "You seem cool and independent, but your happiest moment is when everyone comes to you for help.", "name": "The Quiet Fix-It Person", "atari": ["[[今:You say \"I don't really care\" without much warmth]] while [[本:silently fixing your friend's broken bike]].", "[[今:You've learned the freedom of not planning]], but [[本:you know every expiration date in the fridge]]."]}, "ISFJ>ISFP": {"karai": "You declared you'd go at your own pace, but after fitting around everyone's plans, you're the organizer again.", "name": "The Free Spirit Who Still Gives It All", "atari": ["[[今:You go with your mood these days]], but [[本:when someone's in trouble, your body moves before your mood does]].", "[[今:You finally feel okay putting what you like first]], but [[本:the knickknacks you pick are usually gifts for someone]]."]}, "ISFJ>ESTP": {"karai": "You pass as bold and carefree, but one mistake can haunt you for years.", "name": "The Worrier Who Dives In Headfirst", "atari": ["[[今:Right after diving in full force]], [[本:you quietly ask, \"Was the way I said that okay?\"]]", "[[今:You wear the face of a thrill-seeker]], but [[本:your pouch is always stocked with bandages and antacids]]."]}, "ISFJ>ESFP": {"karai": "Everyone thinks you're the cheerful mood-maker, but at home you hold a solo review of everything you said today.", "name": "The Party Starter on First-Aid Duty", "atari": ["[[今:You're dancing and hyping up the room]] while [[本:arranging water and a cab for whoever drank too much]].", "[[今:You say \"tonight, whoever has the most fun wins\"]], but [[本:you can't stop thinking about tomorrow's prep you haven't done]]."]}, "INFJ>INTJ": {"karai": "You've gotten good at seeming cold, but a movie trailer alone can make you cry.", "name": "The Empath in Armor Made of Logic", "atari": ["[[今:After a meeting where you said \"let's leave feelings out of it\"]], [[本:you can't stop thinking about the person who looked close to tears]].", "[[今:You think you decide on efficiency]], but [[本:the deciding factor is always \"will this hurt them?\"]]"]}, "INFJ>INTP": {"karai": "You act uninterested in others while spending three days decoding what someone really meant by one remark.", "name": "The Researcher of Human Hearts", "atari": ["When a friend comes to you about love, [[今:you catch yourself analyzing it like a psychology paper]].", "[[今:You get so lost in thought that plans slip by]], yet [[本:for promises with people, you start preparing your heart the day before]]."]}, "INFJ>ENTJ": {"karai": "You pass as a confident leader, but a single cold look can sink you for a week.", "name": "The Commander Carrying Ideals", "atari": ["[[今:You can move people with numbers now]], but [[本:what you really want to hear is \"this work matters\"]].", "[[今:Making bold calls suits you well]], but [[本:afterward you replay it alone, checking no one got left behind]]."]}, "INFJ>ENTP": {"karai": "You throw out sarcasm, but you can't relax until you've confirmed the other person laughed.", "name": "The Secret Saint Who Loves a Debate", "atari": ["[[今:You play devil's advocate to get the debate going]] while [[本:secretly hoping it ends with everyone getting along]].", "[[今:You're chatty and light in public]], but [[本:some nights you end up searching things like \"the meaning of life\"]]."]}, "INFJ>INFJ": {"karai": "You hold it in and hold it in, then one day silently drift out of someone's life. That's the scary part.", "name": "The Quiet One Who Sees Everything", "atari": ["The moment you walk in, you know who isn't getting along, and you quietly pick your seat accordingly.", "You notice what people want before they say it, so your gifts almost never miss."]}, "INFJ>INFP": {"karai": "You think you're living freely, but every glance at your messy room brings a wave of quiet self-loathing.", "name": "The Prophet Who Lost the Plan", "atari": ["[[本:You're great at seeing what's coming]], but [[今:when you're not in the mood, nothing gets done]], so you can't catch up to the future you saw.", "[[今:You spend more time in your own world now]], but [[本:you'll notice from miles away when someone you love is off]]."]}, "INFJ>ENFJ": {"karai": "You look like you love being relied on, but you listen to everyone so thoroughly that you're wiped out every day.", "name": "Everyone's Counselor, Closed at Night", "atari": ["[[今:By day, you're everyone's go-to listener]], [[本:but at night you need notifications off and no one to talk to]].", "[[今:You're great at cheering people on]], yet [[本:you call your own worries \"no big deal\" and tell no one]]."]}, "INFJ>ENFP": {"karai": "After years of being called the cheerful one, you act cheerful even on your down days, out of sheer habit.", "name": "The Observer Disguised as Sparkle", "atari": ["[[今:You make friends with anyone in no time]], but [[本:the people allowed deep inside fit on one hand]].", "[[今:You seem to act on a whim]], but [[本:that whim has been warming in your head for days]]."]}, "INFJ>ISTJ": {"karai": "You play the rule-following model student, but you've never really bought into how the world works.", "name": "The Idealist Hiding Behind Precedent", "atari": ["[[今:You work through the set procedure step by step]] while [[本:thinking \"this could be so much better\"]].", "[[今:People see you as practical]], but [[本:you're dreaming up epic stories while staring out the train window]]."]}, "INFJ>ISFJ": {"karai": "You seem modest and gentle, but you hold the most stubborn \"this is how it should be\" of anyone.", "name": "The Down-to-Earth Dreamer", "atari": ["[[今:You calmly get through chores and favors]] while [[本:picturing your ideal life ten years from now]].", "[[今:Taking care of people comes naturally now]], and [[本:while you do, you're quietly reading their true feelings]]."]}, "INFJ>ESTJ": {"karai": "You play the high performer flawlessly, then spend your days off with the curtains shut, ignoring every message.", "name": "The Philosopher With a Planner", "atari": ["[[今:You keep the meeting perfectly on time]] while [[本:suddenly wondering what this meeting is even for]].", "[[今:You can give crisp instructions now]], but [[本:before bed you keep replaying the face of the person you were firm with]]."]}, "INFJ>ESFJ": {"karai": "You're so good at going along with everyone that you lose track of what you actually want.", "name": "The Sage at the Banquet", "atari": ["[[今:When you plan the seating for a party]], [[本:you instantly see who needs to sit apart, and arrange it]].", "[[今:You nod along at the center of the noisy circle]] while [[本:your mind wanders off to somewhere far and quiet]]."]}, "INFJ>ISTP": {"karai": "You act detached, but secretly you want just one person to truly understand you.", "name": "The Quiet, Deep Maker", "atari": ["[[今:You look like the cool one quietly working with your hands]], but [[本:you're picking up every shift in the room]].", "[[今:You act breezy, like it'll all work out]], but [[本:at night you lie awake pondering the meaning of life]]."]}, "INFJ>ISFP": {"karai": "You may call yourself a free spirit, but you still put everyone's feelings first and your own likes last.", "name": "The Foreseer Who Lives by Feel", "atari": ["[[今:You give yourself over to the music and views you love]], but [[本:you can't help thinking about the meaning underneath]].", "[[今:You've learned to enjoy the moment]], yet [[本:even mid-fun you're thinking \"this will end someday\"]]."]}, "INFJ>ESTP": {"karai": "You laugh big, but inside you're locked up like a diary no one gets to read.", "name": "The Overthinker Running on Momentum", "atari": ["[[今:After diving in on the vibe of the moment]], [[本:you spend the walk home wondering if they actually hated it]].", "[[今:People call you a doer]], but [[本:before you move, you've already predicted several ways they might react]]."]}, "INFJ>ESFP": {"karai": "After a day of lighting up the room, you need three days of hiding at home to feel like yourself again.", "name": "The Watcher on Stage", "atari": ["[[今:You hype up the room as the star]] while [[本:still spotting the person looking bored outside the circle]].", "[[今:You say \"if it's fun, who cares?\"]] while [[本:quietly wondering whether the fun means anything]]."]}, "INTJ>INTJ": {"karai": "You're so sure you're right that you skip the explaining, and people misunderstand you constantly.", "name": "Shortest Route, Always", "atari": ["You reached the conclusion long ago and are just quietly waiting for the other person to get there too.", "You plan your days off for efficiency, so friends often say, \"This isn't a trip, it's a mission.\""]}, "INTJ>INTP": {"karai": "You play the laid-back type, but nobody roasts other people's slacking harder than you.", "name": "The Strategist Letting Answers Simmer", "atari": ["[[本:You can already see the answer]], yet [[今:you keep opening more search tabs, saying \"just a little more research\"]].", "[[今:You dream of a free life without plans]], and [[本:before you know it, you're drafting a plan for not planning]]."]}, "INTJ>ENTJ": {"karai": "You nail the sociable-leader role, but small talk is secretly torture every single time.", "name": "The Strategist Sent to the Front Line", "atari": ["[[今:You can speak confidently as a leader now]], but [[本:you'd really rather hand over the slides and go home]].", "[[今:You've gotten good at rallying people]], but [[本:every time, you mutter inside, \"it'd be faster alone\"]]."]}, "INTJ>ENTP": {"karai": "You look like you're winging it, but you've already prepared answers to every possible counterargument.", "name": "The Strategically Spontaneous", "atari": ["[[今:You freely spin ideas with \"okay, but what if\"]], but [[本:even the tangents are detours toward your final conclusion]].", "[[今:You toss out new ideas one after another]], while [[本:having decided from the start you'll only act on one]]."]}, "INTJ>INFJ": {"karai": "You play the great listener, but by the third time someone repeats the same complaint, your eyes glaze over.", "name": "The Rationalist Who Learned Kindness", "atari": ["[[今:You can stand by people's feelings now]], but [[本:your head is calculating the shortest path to a solution]].", "[[今:You can say \"that must have been hard\" now]], though [[本:you can't resist adding three ideas for improvement]]."]}, "INTJ>INFP": {"karai": "You may call yourself a sensitive dreamer, but your face can't hide it when someone's being inefficient.", "name": "The Efficient Romantic", "atari": ["[[今:You've come to love talking about dreams and ideals]], but [[本:somehow they end up as a project timeline]].", "[[今:You enjoy a day off going wherever your mood takes you]], while [[本:secretly counting what you could've done with that time]]."]}, "INTJ>ENFJ": {"karai": "People adore you as a caring mentor, but honestly, you'd be happiest if everyone just figured things out themselves.", "name": "The Cheer Captain With a Battle Plan", "atari": ["[[今:You cheer on your juniors with passion]] while [[本:coolly calculating whether that's the most effective way to do it]].", "[[今:You're at the center of the group]], but [[本:you're really just observing who to pair up for the best results]]."]}, "INTJ>ENFP": {"karai": "You're great at seeming carefree, but any plan built on vibes alone gets an instant \"fail\" in your head.", "name": "The One Who Analyzes the Sparkle", "atari": ["[[今:Right after gushing \"that's amazing!\"]], [[本:you spot three weak points in the idea]].", "[[今:You play the one who jumps on every fun thing]], but [[本:you've basically run the cost-benefit math before you jump]]."]}, "INTJ>ISTJ": {"karai": "You're known as the steady, serious one, but in your head you're redesigning the entire company.", "name": "The Revolutionary Following Precedent", "atari": ["[[今:You work strictly by the set procedure]] while [[本:rewriting your improvement plan for it again and again in your head]].", "[[今:You're trusted for your practical work]], but [[本:you'd rather be sketching the big picture five years out]]."]}, "INTJ>ISFJ": {"karai": "People call you kind, but sometimes that kindness is a strategy to keep hassle to a minimum.", "name": "The Quiet Genius Strategist Who Serves", "atari": ["[[今:You take on requests with a smile]] while [[本:calmly grading them: \"what an inefficient way to ask\"]].", "[[今:You keep a low profile to fit in]], but [[本:you're itching to redo it all your way]]."]}, "INTJ>ESTJ": {"karai": "You look like a by-the-book operator, but most rules make you think, \"What's the point?\"", "name": "The Strategist Down on the Ground", "atari": ["[[今:You build detailed schedules and keep everyone moving]], but [[本:you'd rather be talking big-picture direction]].", "[[今:Giving instructions in front of people is routine now]], but [[本:you've decided lunch break is spent alone, talking to no one]]."]}, "INTJ>ESFJ": {"karai": "You're kind to everyone on the outside, but your mental notebook of snark is getting pretty thick.", "name": "Smiling Host, Secret War Room", "atari": ["[[今:You ask everyone's preferences and set up the event]], while [[本:knowing it'd be faster to decide everything yourself]].", "[[今:You send cheerful stickers in the group chat]] while [[本:already predicting who won't show]]."]}, "INTJ>ISTP": {"karai": "You pretend to wing it, but you can't sleep unless you've thought ten steps ahead.", "name": "The Tinkerer Who Tossed the Blueprint", "atari": ["[[今:You build on a whim now]], but [[本:as you go, you're mapping every step to the finish in your head]].", "[[今:You enjoy days with no plans]], but [[本:you can't help noticing when someone else's planning is sloppy]]."]}, "INTJ>ISFP": {"karai": "People say you have a soft vibe, but get you into a real debate and you're merciless.", "name": "The Theorist Armed With Taste", "atari": ["[[今:You seem to pick what you love on instinct]], but [[本:you've actually spent days reading reviews and comparison charts]].", "[[今:You can go along with people kindly now]], but [[本:inside, you're quietly correcting anything that doesn't add up]]."]}, "INTJ>ESTP": {"karai": "You're proud of being called a go-getter, but surprises are what you hate most.", "name": "The Doer Who Did the Homework", "atari": ["[[今:You look like you're going with the flow]], but [[本:you actually simulated it all the night before]].", "[[今:You can enjoy a rowdy night out now]], but [[本:on the way home you're sorting the intel from today's conversations]]."]}, "INTJ>ESFP": {"karai": "After going all-out as the life of the party, you go silent the moment you're alone, like someone flipped a switch.", "name": "The Cool Brain Behind the Party", "atari": ["[[今:You're the one having the most fun at the party]], yet [[本:part of your brain is still working backward from the last train and tomorrow's plans]].", "[[今:You laugh, \"as long as it's fun right now\"]], but [[本:you can't help wondering where that fun leads in the future]]."]}, "ISTP>INTJ": {"karai": "You talk like a strategist, but often you just want fewer annoying steps.", "name": "The Craftsperson Who Writes Plans Too", "atari": ["[[本:You'd really rather learn by touching things]], but [[今:these days you draw the full blueprint before you move]].", "[[今:The same weekend you make a five-year plan]], [[本:you impulse-buy a tool that caught your eye and wreck the schedule]]."]}, "ISTP>INTP": {"karai": "Once you've researched everything, you're satisfied, and the tool you ordered is still in its box.", "name": "The Craftsperson Who Googles First", "atari": ["[[本:You used to take things apart to find out]], but [[今:now you read reviews for three hours before you even start]].", "[[本:\"Let's just try it\" used to be your catchphrase]], but [[今:now your hands stop until the logic checks out]]."]}, "ISTP>ENTJ": {"karai": "You lead mainly because waiting on other people stresses you out more than anything.", "name": "The Lone Wolf Who Took the Lead", "atari": ["[[今:In meetings you say \"fine, I'll decide\"]], then [[本:want to slip back to working alone the moment it's over]].", "[[今:You get fired up talking team goals]], but [[本:every party invite gets a plausible-sounding excuse]]."]}, "ISTP>ENTP": {"karai": "Now that you're a smooth talker, your excuses for not doing the work have gotten smoother too.", "name": "The Quiet Craftsperson Who Can Argue", "atari": ["[[今:After livening things up with \"okay, but what if\"]], [[本:you don't want to talk to anyone on the way home]].", "[[本:You could just quietly fix it]], but [[今:now you can't help explaining the theory behind the fix]]."]}, "ISTP>INFJ": {"karai": "You seem perceptive, but some days you're quiet only because putting what you sensed into words is a hassle.", "name": "The Fix-It Person Who Learned Tact", "atari": ["[[今:You listen quietly to people's worries]] while [[本:a corner of your brain asks, \"so where's the actual fault?\"]]", "[[今:You've started reading people's feelings in advance]], but [[本:it'd be so much easier if they just said it]]."]}, "ISTP>INFP": {"karai": "You're out there \"finding yourself,\" but if you just got your hands busy, you'd find it in three days.", "name": "The Craftsperson Who Started Dreaming", "atari": ["[[本:You used to be great at practical calls]], but [[今:now some nights you freeze, wondering \"what's the point?\"]]", "[[今:You light up when talk turns to your favorite movies]], but [[本:repair videos were always more your thing]]."]}, "ISTP>ENFJ": {"karai": "Every time you're called caring, you mutter three times inside: \"It'd be faster to do it myself.\"", "name": "The Lone Wolf Who Became a Caretaker", "atari": ["[[今:You take juniors' problems to heart]] while [[本:thinking, \"just poke at it and you'll figure it out\"]].", "[[今:You coordinated everyone's schedules to plan the event]], yet [[本:you're the one who most wants to leave early]]."]}, "ISTP>ENFP": {"karai": "You pass as the high-energy one, but only your family has seen your battery-dead face.", "name": "The Quiet One Who Found Sparkle", "atari": ["[[今:You gush \"this is the best!\" about every new hobby]], but [[本:the only ones that stick are the hands-on kind]].", "[[今:You can make friends with anyone now]], but [[本:your texts still end in one word]]."]}, "ISTP>ISTJ": {"karai": "You look meticulous, but the back of your planner is covered in \"if I feel like it.\"", "name": "The Free-Spirited Maker With a Schedule", "atari": ["[[今:You hand things in neatly before the deadline]], but [[本:a last-minute burst of focus suits you better]].", "[[今:You follow the manual step by step]] while [[本:thinking every time, \"we could skip two of these\"]]."]}, "ISTP>ISFJ": {"karai": "They say you're considerate, but you're much better at fixing machines than reading the room.", "name": "The Toolbox Powered by Kindness", "atari": ["[[今:You can't say no to favors anymore]], but [[本:you'd rather just be handed the instructions and do it alone]].", "[[今:You keep an eye on everyone's health]] while [[本:writing off your own aches with \"it'll pass\"]]."]}, "ISTP>ESTJ": {"karai": "You're strict about rules now, but you used to be the one hunting for loopholes.", "name": "The Free Spirit Turned Site Manager", "atari": ["[[今:You track the team's progress in detail]], yet [[本:you want to do your own work however the mood strikes]].", "[[今:After giving brisk instructions at the morning meeting]], [[本:you spend lunch holed up alone in your car]]."]}, "ISTP>ESFJ": {"karai": "You look like everyone's caretaker, but really you're just enjoying the puzzle called logistics.", "name": "The Hidden Craftsperson Who Hosts Too", "atari": ["[[今:You nail everything from picking the venue to splitting the bill]], then [[本:slip away from the after-party]].", "[[今:You politely react with stickers in the group chat]], but [[本:honestly you think \"you saw I read it, right?\"]]"]}, "ISTP>ISTP": {"karai": "You're dependable, but ask \"How'd you do that?\" and all you get is \"I just did.\"", "name": "The Born Fixer", "atari": ["You build things without reading the instructions and somehow end up with the cleanest result.", "When you see someone struggling, your hands move before your words and you've already fixed it."]}, "ISTP>ISFP": {"karai": "You call yourself the artsy type, but you secretly read every spec sheet too.", "name": "The Craftsperson Who Picks by Taste", "atari": ["[[本:You used to choose tools by performance]], but [[今:lately you choose them by color and feel]].", "[[本:Even when you could argue back with logic]], [[今:you look at their face and let it go with \"eh, fine\"]]."]}, "ISTP>ESTP": {"karai": "The action-hero role suits you now, but part of you is waiting for a weekend when nobody invites you anywhere.", "name": "The Craftsperson in the Spotlight", "atari": ["[[今:You pack your calendar with fun plans on a whim]], but [[本:around the third one, you suddenly crave time alone]].", "[[今:Speaking to a crowd doesn't faze you anymore]], but [[本:once the toast is done, you quietly drift to a corner seat]]."]}, "ISTP>ESFP": {"karai": "You look like you're having fun, but 80% of that smile is \"an awkward silence would be worse.\"", "name": "The Craftsperson Who Can Work a Room", "atari": ["[[今:You play the mood-maker]] while [[本:thinking, \"I want to go home and get back to my project\"]].", "[[今:You react big to your friend's story]], but [[本:you already have a one-line answer to their problem]]."]}, "ISFP>INTJ": {"karai": "You act like a cool-headed decision-maker, but the deciding factor is usually \"I just like it.\"", "name": "The Sensitive Soul Who Makes Plans", "atari": ["[[今:You move things forward on efficiency and evidence]], but [[本:you will never compromise on the fonts and colors of the slides]].", "[[今:You made the perfect long-term plan]], but [[本:the moment your heart is moved, you want to scrap it all]]."]}, "ISFP>INTP": {"karai": "You call yourself logical, but your face reacts to opinions you dislike before any reasoning does.", "name": "The Free Spirit Wrapped in Logic", "atari": ["When you talk about what you love, [[今:the analysis of why you love it now comes out before the feeling]].", "[[今:You browse comparison sites just to pick one piece of furniture]], then [[本:buy the first one you fell for]]."]}, "ISFP>ENTJ": {"karai": "Wanting to look strong sometimes turns into doing an impression of a strong person.", "name": "The Sensitive Soul Turned Leader", "atari": ["[[今:You make firm calls in meetings]], yet [[本:at home a solo \"did I say too much?\" review begins]].", "[[今:You move people with goals and numbers]], but [[本:what you really care about is whether everyone feels comfortable]]."]}, "ISFP>ENTP": {"karai": "You've become the one who calls people out, but when you get seriously shot down, it stings for a week.", "name": "The Artist Who Learned to Talk Back", "atari": ["[[今:You cut in with \"okay, but what if\" in debates]], yet [[本:you replay the face of the person you out-argued all night]].", "[[今:You fire off ideas and keep the energy up]], but [[本:you'd rather take one and slowly shape it with your hands]]."]}, "ISFP>INFJ": {"karai": "After saying something cryptic, you're left figuring out what you meant too.", "name": "The Free Spirit Who Now Plans Ahead", "atari": ["[[今:You've started smoothing out people's feelings in advance]], but [[本:you'd rather just move with the mood of the moment]].", "[[今:You're filling in next month's planner]] while [[本:your heart gets stolen by \"wow, look at that sunset\"]]."]}, "ISFP>INFP": {"karai": "The more time you spend talking about ideals, the less time you spend making things with your hands like you used to.", "name": "The Here-and-Now Type Who Daydreams", "atari": ["[[本:You used to be great at enjoying what's right in front of you]], but [[今:now you tend to get lost in \"what's this all for?\"]]", "[[本:From a single flower spotted on a walk]], [[今:you somehow dream up an epic saga by the time you get home]]."]}, "ISFP>ENFJ": {"karai": "Being needed makes you so happy that you take on too much and keep putting what you love on hold.", "name": "The Loner Working Hard for Everyone", "atari": ["[[今:You take on being everyone's counselor]] while [[本:really wanting to be alone with your favorite music]].", "[[今:You throw a friend's birthday party and it's a huge hit]], [[本:yet the next day you're in bed, seeing no one]]."]}, "ISFP>ENFP": {"karai": "You seem outgoing, but you still can't message the one person you really want to invite.", "name": "The Artist Who Jumped Into the Crowd", "atari": ["[[今:You can smile and chat with strangers now]], but [[本:your earbuds on the way home are a lifeline]].", "You've always followed your heart. It's just that [[本:you used to do it alone]], and [[今:now somehow you do it with a crowd]]."]}, "ISFP>ISTJ": {"karai": "People say you're diligent, but that diligence is mostly made of not wanting to get scolded.", "name": "The Free Spirit Playing Tidy", "atari": ["[[今:Your paperwork goes in perfect and early]], yet [[本:your desk is buried in cute knickknacks you love]].", "[[今:You've learned to follow procedures]], but [[本:every time you think \"there's a lovelier way to do this\"]]."]}, "ISFP>ISFJ": {"karai": "They say you notice everything, but you've also gotten good at bottling up everything you notice.", "name": "The Free Spirit Who Got Organized", "atari": ["[[今:You remember how everyone takes their tea]], yet [[本:you still want to change your own plans on a whim]].", "[[今:You've started preparing before anyone asks]], but [[本:it's really so you never have to see yourself panic]]."]}, "ISFP>ESTJ": {"karai": "Your capable-person mask has gotten so thick that when someone asks what you like, you freeze for a second.", "name": "The Artist Put in Charge", "atari": ["[[今:You call people out when things fall behind schedule]], yet [[本:your happiest days off have no plan at all]].", "[[今:On the way home from a day of giving clear instructions]], [[本:you clutch your phone, wondering \"was I too harsh?\"]]"]}, "ISFP>ESFJ": {"karai": "You're so good at fitting in that your own tastes have wandered off on a trip somewhere.", "name": "The Free Spirit Elected Party Planner", "atari": ["[[今:You check everyone's availability and book the place]], then [[本:spend the night taking photos of the cute interior]].", "[[今:You can't leave someone sitting alone anymore]], but [[本:on days you want to be alone, you can't say so]]."]}, "ISFP>ISTP": {"karai": "You act unsentimental, but every letter you've ever received is saved in a box.", "name": "The Artist Who Learned to Be Cool", "atari": ["[[今:People think you don't show emotion]], but [[本:one second of your favorite song's intro has you close to tears]].", "[[今:You answer people's problems with logic now]], but [[本:you'd rather say \"I get it\" and feel down with them]]."]}, "ISFP>ISFP": {"karai": "You seem like you never get angry, but your mental \"never seeing them again\" list is surprisingly long.", "name": "True to What You Love", "atari": ["You keep choosing what you love over what's trendy, and your room has quietly become a tiny art museum.", "You don't say when you hate something, but your face and feet are already leaving the room."]}, "ISFP>ESTP": {"karai": "You act tough, but you've reread that slightly cold text three times.", "name": "The Sensitive Soul Turned Doer", "atari": ["[[今:You dive in on momentum now]], but [[本:after deciding, you're alone with a nervous \"is this okay?\"]]", "[[今:You can take charge with on-the-spot calls]], yet [[本:one sad face is all it takes to make you waver]]."]}, "ISFP>ESFP": {"karai": "Your cheerful persona is so established that even when you're down, people just ask, \"Doing good?\"", "name": "The Secret Introvert Who Shines on Stage", "atari": ["[[今:At parties you're practically the main event]], yet [[本:back home you head straight to bed without turning on the lights]].", "[[今:You hop on every fun thing]], but [[本:the best part was the little shop you stopped at alone on the way home]]."]}, "INFP>INTJ": {"karai": "You reach conclusions coolly, but your ideals sneak into every one of them.", "name": "The Dreamer Who Drew Up Blueprints", "atari": ["[[今:You plan rationally and execute]], but [[本:what drives you is a big dream you can't tell anyone]].", "[[今:You can calmly handle other people's opinions now]], yet [[本:you still sob at the touching scenes in movies]]."]}, "INFP>INTP": {"karai": "Acting all logical is really just armor so you don't get hurt.", "name": "The Dreamer Wrapping Feelings in Logic", "atari": ["[[今:You write a logical deep-dive on your favorite work]], but [[本:really you just want to say \"it's so precious\"]].", "[[今:You answer people's worries with analysis now]], but [[本:you're ready to cry with them, too]]."]}, "INFP>ENTJ": {"karai": "You take charge boldly, but you might be the most easily hurt person on the team.", "name": "The Dreamer Leading for an Ideal", "atari": ["[[今:You lead and deliver results]] while [[本:\"does this work even mean anything?\" plays on repeat in your head]].", "[[今:On nights after making a tough call]], [[本:you write long excuses and reflections in your journal]]."]}, "INFP>ENTP": {"karai": "Your sarcasm is just a cover for being a hopeless romantic.", "name": "The Daydreamer Who Learned to Talk Back", "atari": ["[[今:You've started enjoying a good argument]], but [[本:late at night you keep imagining how the person you went too far with felt]].", "[[今:You toss out ideas one after another]], but [[本:the dream that really matters, you've told no one]]."]}, "INFP>INFJ": {"karai": "You look put-together, but half your plans exist just to make you look put-together.", "name": "The Romantic Who Learned to Plan", "atari": ["[[今:You can read people's feelings and act on them now]], but [[本:you can never schedule your own]].", "[[今:You fill your planner neatly now]], yet [[本:the best part is the doodles in the margins]]."]}, "INFP>INFP": {"karai": "Your ideals are so high that most real-life invitations end with \"maybe next time.\"", "name": "The Dreamer Who Lives in a Movie Theater", "atari": ["In a fifteen-minute commute, you finish an entire saga in your head where the hero grows three times.", "When you find a lyric you love, that one line decides your mood for the whole day."]}, "INFP>ENFJ": {"karai": "You work hard to be needed, but when you're needed too much, you suddenly want to run from everything.", "name": "The Daydreamer Guarding Everyone's Heart", "atari": ["[[今:You've become the one who keeps the group's mood in balance]], but [[本:at home you can't keep up with caring for your own heart]].", "[[今:Encouraging words for others flow easily]], yet [[本:you can't think of a single one for yourself]]."]}, "INFP>ENFP": {"karai": "You think you've become social, but the moment you make plans, a little \"I don't want to go\" starts growing.", "name": "The Dreamer Who Stepped Outside", "atari": ["[[今:You can have fun talking with anyone now]], but [[本:there are still only about two people you're truly honest with]].", "[[今:You tell people right away about what excites you]], but [[本:the most precious excitement is still tucked in your chest]]."]}, "INFP>ISTJ": {"karai": "You play the sensible one, but your plan for after you win the lottery is weirdly detailed.", "name": "The Dreamer Who Landed in Reality", "atari": ["[[今:After neatly wrapping up your expense reports]], [[本:you secretly plot the next chapter of your novel under the desk]].", "[[今:You work by precedent]] while [[本:asking yourself every day, \"is this really right?\"]]"]}, "INFP>ISFJ": {"karai": "They call you considerate, but all the favors you couldn't refuse have your dreams stuck in traffic.", "name": "The Gentle Dreamer Who Gets Things Done", "atari": ["[[今:You remember everyone's favorite snacks and bring them in]], but [[本:you really want time to sink into your own world]].", "[[今:You quietly get through every request]] while [[本:a totally unrelated story plays out in your head]]."]}, "INFP>ESTJ": {"karai": "You look like a dependable boss, but nobody feels worse about your harsh words than you do.", "name": "The Dreamer Playing the Responsible One", "atari": ["[[今:You move people with numbers and deadlines]] while [[本:constantly wondering, \"is everyone happy?\"]]", "[[今:You manage the schedule perfectly]], yet [[本:some days one glance at the sky makes you want to drop it all]]."]}, "INFP>ESFJ": {"karai": "You say fitting in feels safe, but deep down you want to be someone special.", "name": "The Daydreamer Making Room for Everyone", "atari": ["[[今:You host the night out flawlessly]], then [[本:wonder on the train home, \"was that the real me today?\"]]", "[[今:You remember everyone's birthday]], yet [[本:you still can't recall what you really want to do]]."]}, "INFP>ISTP": {"karai": "You pass as easygoing, but that old heartbreak is still on repeat in your head.", "name": "The Daydreamer With a Cool Face", "atari": ["[[今:You calmly work through tasks now]], but [[本:while your hands move, a different story is playing in your head]].", "[[今:Because you don't show your feelings]], [[本:you start talking fast the moment your favorite artist comes up]]."]}, "INFP>ISFP": {"karai": "You've gotten good at living in the moment, but half your mind is still in \"what if\" land.", "name": "The Dreamer Who Lives by Feel", "atari": ["[[今:You pick what you love on instinct now]], but [[本:ask why and an epic tale begins]].", "[[今:Taking photos at cafés became your hobby]], but [[本:you give every single shot its own backstory]]."]}, "INFP>ESTP": {"karai": "You look like you run on momentum, but without it, your ideals are too heavy to move.", "name": "The Dreamer Turned Doer", "atari": ["[[今:You've become a \"just try it\" person]], but [[本:afterward you need time alone to figure out what it meant]].", "[[今:You go out on a whim now]], yet [[本:on the night after a fun day, you feel a little lonely somehow]]."]}, "INFP>ESFP": {"karai": "Being called fun makes you happy, but part of you sulks: \"That's not the real me.\"", "name": "The Dreamer Who Picked Up Sunshine", "atari": ["[[今:You've gotten good at livening up the room]], but [[本:on the way home you put your favorite song on repeat to find yourself again]].", "[[今:You throw yourself into fashion and events]], yet [[本:there's a notebook in your heart you show no one]]."]}, "INTP>INTJ": {"karai": "You think you've gotten decisive, but really you just decide the moment you're bored of thinking.", "name": "The Explorer Who Learned to Wrap It Up", "atari": ["[[今:You set deadlines and reach conclusions now]], but [[本:the research in the middle is the best part]].", "[[今:Everything's going to plan]], yet [[本:at midnight you find an unrelated question and lose three hours]]."]}, "INTP>INTP": {"karai": "You've figured it all out in your head, yet deadlines and replies remain untouched.", "name": "The Researcher With Endless Questions", "atari": ["You start looking up a \"but why?\" that hit you before bed, and suddenly the birds are singing.", "Mid-conversation, you get stuck on how they defined a word and miss the rest completely."]}, "INTP>ENTJ": {"karai": "You act like a leader, but you never know what to do with yourself during small talk.", "name": "The Researcher Who Picked Up the Flag", "atari": ["[[今:You lead the team and get results]], but [[本:you'd really rather dig into root causes alone]].", "[[今:You can make snap decisions in meetings now]], yet [[本:at home you re-verify the reasoning behind that call by yourself]]."]}, "INTP>ENTP": {"karai": "You think you've become a great talker, but you watch your own logic more than the other person's face.", "name": "The Talking Search Engine", "atari": ["[[本:You used to keep what you learned to yourself]], but [[今:now you can't get through a night out without giving a lecture]].", "[[今:Debating with people is fun now]], but [[本:once there are three or more, your battery starts draining fast]]."]}, "INTP>INFJ": {"karai": "You've become empathetic, but about half of it comes from observation and calculation.", "name": "The Researcher Who Studies Hearts Too", "atari": ["[[今:You've started sensing how people feel]], but [[本:you write up your findings as a paper in your head]].", "[[今:You gently stand by people with their worries]], while [[本:deep down you want to say, \"I've got three solutions, by the way\"]]."]}, "INTP>INFP": {"karai": "You say you've become sensitive, but you still start by analyzing why you got hurt. Same old you.", "name": "The Researcher Who Discovered Feelings", "atari": ["[[本:You've lived by logic]], but [[今:lately you cry reading analyses of your favorite works]].", "[[今:You want to value feelings over being right]], but [[本:you still can't help noticing the contradictions]]."]}, "INTP>ENFJ": {"karai": "Now that you look after everyone, your curiosity gets about thirty minutes a week.", "name": "The Thinker Who Started Guiding People", "atari": ["[[今:You can really be there for your juniors now]], but [[本:at home you just want to solve puzzles in silence]].", "[[今:You offer words that boost everyone's motivation]], while [[本:secretly testing how well those words work]]."]}, "INTP>ENFP": {"karai": "You seem to live on impulse, but every impulse has passed three checks beforehand.", "name": "The Logician Who Runs on Sparkle", "atari": ["[[今:You've started gushing over things you love]], but [[本:later you analyze, alone, why you gushed]].", "[[今:You enjoy meeting new people now]], yet [[本:you're more interested in the patterns of their verbal tics than in what they're saying]]."]}, "INTP>ISTJ": {"karai": "You look like a creature of routine, but you only follow precedent on days you can't be bothered to think.", "name": "The Explorer Who Picked Up Neatness", "atari": ["[[今:You run things by the manual]] while [[本:itching to rebuild the whole procedure from scratch]].", "[[今:You wake up at the same time every morning now]], but [[本:your bedtime searching is still off the rules]]."]}, "INTP>ISFJ": {"karai": "People call you kind, but honestly, you'd rather be left alone than go along with others.", "name": "The Thinker Who's Great at Caring", "atari": ["[[今:You meet requests with a smile]] while [[本:redesigning them in your head because there's a more efficient way]].", "[[今:You've started remembering people's preferences]], but [[本:the way you do it is basically a database]]."]}, "INTP>ESTJ": {"karai": "You play the responsible one, but your real talent isn't making plans. It's poking holes in them.", "name": "The Thinker Running the Floor", "atari": ["[[今:You manage schedules and keep people moving]], but [[本:on days off you'd love to read papers in your pajamas all day]].", "[[今:You tell people \"follow precedent\"]] while [[本:already spotting three holes in that precedent]]."]}, "INTP>ESFJ": {"karai": "You've gotten good at reading the room, thanks to studying it as a research subject.", "name": "The Researcher Turned Party Planner", "atari": ["[[今:You gather everyone's schedules and book the place]] while [[本:secretly working out an algorithm for the optimal date]].", "[[今:You can chat brightly with anyone now]], but [[本:what you really enjoy is digging into questions alone]]."]}, "INTP>ISTP": {"karai": "You think you're a doer now, but you still read every warning in the manual before touching anything.", "name": "The Researcher Who Got Hands-On", "atari": ["[[本:You used to just think about things]], but [[今:now if you're curious, you take it apart to check]].", "[[今:People say you've become so practical]], but [[本:even mid-task, \"why does it do that?\" never stops]]."]}, "INTP>ISFP": {"karai": "You seem easygoing, but one remark that caught your attention gets three days of analysis.", "name": "The Logician Who Chooses by Feel", "atari": ["[[今:You can pick what you love on instinct now]], but [[本:afterward you make a comparison chart to convince yourself]].", "[[今:You've learned to be there for people's feelings]], yet [[本:every so often, a contradiction in their story nags at you]]."]}, "INTP>ESTP": {"karai": "People say you're a go-getter, but that's just the backlash from years of overthinking and never moving.", "name": "The Rabbit-Hole Dweller on the Move", "atari": ["[[今:You act before you think now]], but [[本:the solo review afterward takes two hours]].", "[[今:You join in on the fun on a whim now]], but [[本:the best part is finding loopholes in the rules of the game]]."]}, "INTP>ESFP": {"karai": "Your cheerful persona is flawless, but you wrote the script alone at home after careful research.", "name": "The Logician Who Learned to Smile", "atari": ["[[今:You've become the one who livens up the room]], but [[本:on the way home you coolly analyze why the joke landed]].", "[[今:You can ride the trends and enjoy them now]], but [[本:how things become trendy interests you more]]."]}, "ESTP>INTJ": {"karai": "You stay silent like a strategist, but half that silence is \"Can we wrap this up?\"", "name": "The Daredevil With a Business Plan", "atari": ["[[今:In meetings you say \"in the long run\"]], but [[本:your feet are itching to rush out to the field right now]].", "[[今:You planned your day off perfectly, all by yourself]], yet [[本:that morning you want to flip it all with \"actually, let's hit the beach\"]]."]}, "ESTP>INTP": {"karai": "You pretend to analyze carefully, then always decide with \"Eh, sounds fun.\"", "name": "The Doer Who Overthinks", "atari": ["[[今:After three hours of reading gadget comparison articles]], [[本:you decide to buy the moment you touch one in the store]].", "[[今:You put a party invite on hold with \"I'll think about it\"]], but [[本:you're secretly the type who wants to be there first]]."]}, "ESTP>ENTJ": {"karai": "You may look like a calm commander, but the moment your competitive streak shows, the act is over.", "name": "The CEO Hopeful Who Sealed Away the Fun", "atari": ["[[今:You preach \"planning is everything\" to your team]], yet [[本:you come most alive the moment trouble hits]].", "[[今:You set goals by the year]] while [[本:thinking \"next week is next week's me's problem\"]]."]}, "ESTP>ENTP": {"karai": "You start talking like a big thinker, and three minutes later you've landed on \"Let's just try it.\"", "name": "The Hands-On Type Who Can Split Hairs", "atari": ["[[今:You started the debate with \"okay, but what if\"]], but [[本:you're dying to just test it and get the answer]].", "[[今:Halfway through passionately pitching an idea]], [[本:you're already figuring out where to buy the materials]]."]}, "ESTP>INFJ": {"karai": "You've mastered the meaningful silence, but what's inside is usually \"I'm hungry.\"", "name": "Quick Reflexes, Quiet Face", "atari": ["[[今:You nod deeply as your friend shares their problem]], while [[本:mentally lacing up your sneakers: \"so when do we move?\"]]", "[[今:Every day you read people's feelings ahead of time and tiptoe around them]], but [[本:you'd really rather just say what you think on the spot]]."]}, "ESTP>INFP": {"karai": "The sensitive persona suits you now, yet in an argument you're still the first to fire back.", "name": "The Dreamy Speed Demon", "atari": ["[[今:You were supposed to be lost in your favorite movie's world]], but [[本:you've already looked up how to get to the filming location and booked it]].", "[[今:You choose your words so you won't hurt anyone]], but [[本:honestly you're thinking, \"wouldn't it be faster to just say it?\"]]"]}, "ESTP>ENFJ": {"karai": "You look like you're doing it all for everyone, but you're the one having the most fun.", "name": "The Caretaker Who Charges In", "atari": ["[[今:You listen kindly to your juniors' worries]], but [[本:you're itching to push them with \"just try it once and you'll see\"]].", "[[今:You coordinated everyone's schedules to plan the trip]], yet [[本:you're the one itching for an unplanned detour once you're there]]."]}, "ESTP>ENFP": {"karai": "You act deeply moved, but by the next day you've forgotten the plot of the movie that moved you.", "name": "The Dreamer Who Already Pressed Go", "atari": ["[[今:You talk about dreams with \"this is so exciting!\"]], but [[本:you've already hit the sign-up button on ninety percent of them]].", "[[今:You line up comforting words for your friend's feelings]] while [[本:three solutions are already ready in your head]]."]}, "ESTP>ISTJ": {"karai": "You follow the rules only because you know breaking them is more hassle.", "name": "The Gambler Who Follows the Manual", "atari": ["[[今:You work by the manual]] while [[本:counting, \"I could skip two of these steps\"]].", "[[今:The same weekend you make a strict savings plan]], [[本:one glimpse of \"limited-time sale\" melts your willpower instantly]]."]}, "ESTP>ISFJ": {"karai": "You want to be the humble nice person, but one compliment and you're chasing the next job at double speed.", "name": "The Show-Off Working Backstage", "atari": ["[[今:You quietly take care of every favor]], but [[本:your mouth is itching to say \"look, isn't this amazing?\"]]", "[[今:You gave up your day off to fit the family's plans]], yet [[本:the second you get time alone, you're off on a drive]]."]}, "ESTP>ESTJ": {"karai": "You look organized, but your schedule exists not to be kept, but for the thrill of breaking it.", "name": "The Wild Child With a Planner", "atari": ["[[今:You tell the team \"let's hit our deadlines\"]], yet [[本:you burn brightest during the night-before crunch]].", "[[今:You're the one who made the trip itinerary]], yet [[本:you're the first to ignore it and get sucked into the food stalls]]."]}, "ESTP>ESFJ": {"karai": "You pass as nice to everyone, but with buzzkills you draw a line while still smiling.", "name": "The Considerate Risk-Taker", "atari": ["[[今:As party host you look after everyone]], but [[本:secretly you want to belt it louder than anyone at karaoke afterward]].", "[[今:You reply politely with stickers in the group chat]], but [[本:you'd really rather just send \"ok\"]]."]}, "ESTP>ISTP": {"karai": "You act like a cool lone wolf, but when nobody invites you, you quietly get lonely.", "name": "The Doer Gone Shy", "atari": ["[[今:You're content spending a day off quietly tinkering with your bike]], but [[本:part of you wants someone to say \"wow, that's cool\"]].", "[[今:You stay quiet when meeting people for the first time]], yet [[本:once you warm up, you're laughing louder than anyone]]."]}, "ESTP>ISFP": {"karai": "You pose as a laid-back artist, but the moment there's a competition, your eyes change.", "name": "The Athlete Who Runs on Taste", "atari": ["[[今:You enjoy picking out clothes you love on your own]], but [[本:you really want someone to notice them when you go out]].", "[[今:You swallow your words to put others' feelings first]], then [[本:kick pebbles on the way home thinking \"I should've said it\"]]."]}, "ESTP>ESTP": {"karai": "No one beats your drive, but someone else usually cleans up after you.", "name": "Landed Before You Could Hesitate", "atari": ["When you spot a store that looks interesting, you've opened the door and asked \"what do you recommend?\" before looking anything up.", "The more trouble hits, the sharper you get; while everyone's panicking, you've solved it and moved on."]}, "ESTP>ESFP": {"karai": "You're known as up for anything, yet when there's money to lose, you're the coolest head in the room.", "name": "Quick Reflexes Fueled by the Vibe", "atari": ["[[今:You play the one who livens things up]] while [[本:thinking \"this event could run way more efficiently\"]].", "[[今:You go all in on your friend's love story]], while [[本:itching to make them set a date: \"so when are you confessing?\"]]"]}, "ESFP>INTJ": {"karai": "You act like you see everything coming, but invite you to something fun and you toss the whole plan.", "name": "The Party Lover Wearing Cool Well", "atari": ["[[今:After stating your opinion logically]], [[本:you get home and hold a solo review: \"was I too harsh?\"]]", "[[今:Behind the serious face planning five years ahead]], [[本:you'd rather be figuring out where to dance tonight]]."]}, "ESFP>INTP": {"karai": "You call yourself logical, but your deciding factor is always \"It's cute\" or \"It looks fun.\"", "name": "The Party Crew Lost in a Rabbit Hole", "atari": ["[[今:You research what interests you alone]], but [[本:when you find something cool, you end up calling someone to tell them]].", "[[今:You insist \"logic over feelings\"]], yet [[本:you're the first to cry when the movie credits roll]]."]}, "ESFP>ENTJ": {"karai": "You may wear a capable leader's face, but your craving for praise shows more honestly than anyone's.", "name": "The Popular One Now Running the Show", "atari": ["[[今:You manage projects by the numbers]], but [[本:you're really doing it for the wrap party with the team]].", "[[今:On the night after giving someone tough feedback]], [[本:you're secretly picking out snacks to bring them]]."]}, "ESFP>ENTP": {"karai": "You pass as the quick-witted one, but after winning an argument, you keep worrying they hate you now.", "name": "The Mood-Maker Who Can Debate", "atari": ["[[今:You pick fights with \"okay, but what if\"]], but [[本:you go easy halfway because you want it to end with both of you laughing]].", "[[今:You talk up new ideas nonstop]], but [[本:your head is really full of whatever fun thing is in front of you]]."]}, "ESFP>INFJ": {"karai": "You may come off as mysterious, but you're pretty simple inside. Good food fixes any mood.", "name": "The Party Lover Lost in Thought", "atari": ["[[今:You spend your days trying to read people deeply]], but [[本:you'd rather just laugh with everyone without overthinking]].", "[[今:You decided to treasure your alone time]], yet [[本:when a weekend invite comes, you reply \"I'm in!\" in a second]]."]}, "ESFP>INFP": {"karai": "You say you've turned introverted, but drop you into a fun party and you're the loudest one in three minutes.", "name": "The Spotlight That Stayed Home", "atari": ["[[今:You're supposed to be alone in your room, lost in daydreams]], but [[本:somehow you're waiting for someone to react on social media]].", "[[今:You have more days frozen by caring too much about your feelings]], but [[本:you're really someone who wants to act on what you feel right away]]."]}, "ESFP>ENFJ": {"karai": "You play the admirable mentor, but you haven't planned a single thing for tomorrow.", "name": "The Fun-Seeker Who Became the Organizer", "atari": ["[[今:You run events with everyone's growth in mind]], yet [[本:what you're most looking forward to is the entertainment part]].", "[[今:You talk seriously about your friend's future]] while [[本:thinking, \"more importantly, where are we going this week?\"]]"]}, "ESFP>ENFP": {"karai": "You've become someone who talks about possibilities, but those possibilities mostly boil down to \"sounds fun.\"", "name": "The Fun One Who Started Daydreaming", "atari": ["[[今:You talk about grand dreams like \"someday I'll travel the world\"]], but [[本:next week's barbecue is what you're really excited for]].", "[[今:A new hobby thrilled you and you bought all the gear]], but [[本:you found a new thrill before using any of it]]."]}, "ESFP>ISTJ": {"karai": "You may think you've become sensible, but you're powerless against \"limited edition\" and \"today only.\"", "name": "The Goofball Who Got Serious", "atari": ["[[今:You take the same train every morning]] while [[本:secretly fighting the urge to hop off at some unfamiliar station]].", "[[今:You've started keeping a strict budget]], but [[本:half the receipts are \"it was fun, so it's fine\" spending]]."]}, "ESFP>ISFJ": {"karai": "You think you're low-key, but in group photos you somehow always end up dead center.", "name": "The Star Working Behind the Scenes", "atari": ["[[今:You quietly make tea for everyone at work]] while [[本:wishing a little, \"someone notice and praise me\"]].", "[[今:You put family plans first and push your own fun back]], but [[本:you really want to be the first one out the door]]."]}, "ESFP>ESTJ": {"karai": "You act organized, but in the face of a fun invite, your planner is just paper.", "name": "The Cheerful One Laying Down the Rules", "atari": ["[[今:After warning someone \"rules are rules\"]], [[本:if they look down, you carry it with you all day too]].", "[[今:You keep work running exactly to plan]] while [[本:waiting for the moment someone invites you out for an unplanned drink]]."]}, "ESFP>ESFJ": {"karai": "You call yourself a meticulous organizer, yet someone else always has to split the bill.", "name": "The Party Boss Who Learned to Plan", "atari": ["[[今:You planned the birthday party to perfection]], yet [[本:on the day you add surprise touches on the spot]].", "[[今:You're now in charge of the group's schedule]], but [[本:being the one who's invited and tags along is more fun]]."]}, "ESFP>ISTP": {"karai": "You insist you've become unsentimental, but one kitten video breaks the whole act.", "name": "The Mood-Maker Who Builds in Silence", "atari": ["[[今:You spend a day off lost in a quiet DIY project]], then [[本:snap a photo the moment it's done and send it to your friends]].", "[[今:You've learned to stay cool and not show emotion]], but [[本:inside you're riding every high and low of their reactions]]."]}, "ESFP>ISFP": {"karai": "You say you hate crowds, yet you always manage to snag presale festival tickets.", "name": "The Popular One Who Fell for Solitude", "atari": ["[[今:You meant to enjoy some alone time at your favorite café]], but [[本:you've made friends with the staff and become a regular]].", "[[今:You avoid big gatherings these days]], yet [[本:in a small group, you're the one keeping the conversation going]]."]}, "ESFP>ESTP": {"karai": "You claim to be totally chill, but get left on read and you're guessing why until bedtime.", "name": "The Mood-Maker Who Got Competitive", "atari": ["[[今:You play aggressive when there's something to win]], yet [[本:if the loser looks down, you can't help going to cheer them up]].", "[[今:You say \"let's think about what we gain\"]], but [[本:you end up prioritizing requests from people who are fun to be with]]."]}, "ESFP>ESFP": {"karai": "You're a genius at enjoying the moment, but future you is picking up the whole tab.", "name": "Born to Party", "atari": ["You reply \"I'm in!\" before even hearing the details, so your calendar is always triple-booked.", "You go all out making everyone laugh and only notice how tired you are on the way home."]}, "ENFP>INTJ": {"karai": "You play the logical one, but ask why you decided and it's \"It just felt like fate.\"", "name": "The Strategist Who Locked Up the Sparkle", "atari": ["[[今:You build your schedule for efficiency]], yet [[本:one poster you happen to see makes you want to rearrange everything]].", "[[今:You can calmly state hard facts now]], but [[本:inside you keep worrying about how the other person feels]]."]}, "ENFP>INTP": {"karai": "You say logic beats feelings, but your logic only shines when you're justifying something you love.", "name": "In Love, Down a Rabbit Hole", "atari": ["[[今:You research the things you love inside and out, alone]], and [[本:soon you know more than anyone and are dying to talk about it]].", "[[今:You find socializing a hassle]], yet [[本:the moment you meet someone on your wavelength, you talk until dawn]]."]}, "ENFP>ENTJ": {"karai": "You wear the face of a disciplined boss, but the margins of your plan are full of doodles about what to do next.", "name": "The Commander Who Put Dreams in Numbers", "atari": ["[[今:You set goals and deadlines and lead the team]], but [[本:you'd really rather everyone take off just because it sounds fun]].", "[[今:After sending tough feedback]], [[本:you keep checking your phone until they reply]]."]}, "ENFP>ENTP": {"karai": "You've started playing the tough critic, but when someone shoots down your idea, you sulk more visibly than anyone.", "name": "The Romantic in Logical Armor", "atari": ["[[今:You've become the one asking \"is there any evidence for that?\"]], yet [[本:the only evidence for your own project is \"it just clicked\"]].", "[[今:You're great at coming up with ideas]], but [[本:you'd rather choose by \"I just like it\" than by logic]]."]}, "ENFP>INFJ": {"karai": "People call you calm, except on nights your favorite star drops big news. Then you're the loudest one around.", "name": "The Talker Who Became the Listener", "atari": ["[[今:You stick to listening and sense what people really feel]], but [[本:you'd really love to spend three hours talking about what excites you]].", "[[今:Writing future plans in a notebook has become a daily habit]], but [[本:the dream changes on every page]]."]}, "ENFP>INFP": {"karai": "You call yourself an introvert, but around kindred spirits you talk so much you wear them out.", "name": "Promoter of a One-Person Film Festival", "atari": ["[[今:You've come to enjoy getting lost alone in the stories in your head]], but [[本:you're really someone whose stories feel complete only once you share them]].", "[[今:You get worn out by plans and hole up at home]], yet [[本:three days later you're desperate to see someone]]."]}, "ENFP>ENFJ": {"karai": "You look like the responsible one, but cleaning your room has been \"someday\" for about three years.", "name": "The Free Spirit Carrying Responsibility", "atari": ["[[今:You look after everyone and run the events]], but [[本:you'd really rather be the one heading out on a whim]].", "[[今:You're so reliable when juniors come to you]], yet [[本:you might be keeping your own worries to yourself]]."]}, "ENFP>ENFP": {"karai": "Nobody starts things like you do, but your closet is overflowing with gear from hobbies you abandoned.", "name": "Too Honest About What Excites You", "atari": ["You fall for new people and hobbies so fast that your camera roll looks like a different person every month.", "You're a genius at seeing the good in people, and thirty minutes after meeting someone you're saying \"this might be fate.\""]}, "ENFP>ISTJ": {"karai": "You pass as meticulous, but your planner holds more daydreams than plans.", "name": "The Daydreamer Following the Manual", "atari": ["[[今:You follow the set procedures at work]] while [[本:ten totally different projects swell up in your head]].", "[[今:You feel safe sticking to the same routine every day]], but [[本:deep down something stirs: \"is this really it?\"]]"]}, "ENFP>ISFJ": {"karai": "You seem modest and sincere, yet get on a topic you love and you talk faster and faster, unstoppable.", "name": "The Traveler in Steady Mode", "atari": ["[[今:You carefully handle the work you're given]], but [[本:you're itching to say \"it'd be more fun if we did it this way\"]].", "[[今:You put family and friends' plans first]] while [[本:imagining setting off alone for some faraway city]]."]}, "ENFP>ESTJ": {"karai": "You keep close tabs on everyone's progress, yet the deadline for your own dream keeps getting pushed back.", "name": "Writing Dreams Into the Planner", "atari": ["[[今:You lock down the team's plans]] while [[本:wanting to try much wilder ideas]].", "[[今:\"Let's be realistic\" has become your catchphrase]], but [[本:before bed you're daydreaming the next chapter of a big dream]]."]}, "ENFP>ESFJ": {"karai": "You look like the sensible organizer, but by the after-party you've given up organizing anything.", "name": "The Dreamer Turned Party Planner", "atari": ["[[今:You nail everything from picking the place to splitting the bill]], but [[本:you'd really rather invite someone on a trip with no destination]].", "[[今:You bring everyone's opinions together and keep things smooth]], while [[本:thinking \"a weirder idea would be fine too\"]]."]}, "ENFP>ISTP": {"karai": "You've become the quiet, cool type, but your inner monologue is louder than anyone's.", "name": "The Chatterbox Brain Playing Quiet", "atari": ["[[今:Calm, unemotional replies come naturally to you now]], but [[本:inside, one word from someone can toss you around all day]].", "[[今:You get lost in hands-on work alone]], and [[本:before you know it, you've named what you made and started talking to it]]."]}, "ENFP>ISFP": {"karai": "For someone who claims to be a free spirit, a weekend with zero messages hits you surprisingly hard.", "name": "The Social Butterfly Who Found Solitude", "atari": ["[[今:You spend more time alone enjoying the music and clothes you love]], but [[本:when you find something great, you have to show someone]].", "[[今:You decided to \"live in the moment\"]], yet [[本:you've just spent an hour daydreaming about ten years from now]]."]}, "ENFP>ESTP": {"karai": "You pose as a no-nonsense doer, but compliments make you visibly giddy.", "name": "The Dream-Chaser Who Got Practical", "atari": ["[[今:You make snap \"let's just move\" decisions now]], but [[本:afterward you look back wondering \"what did they think?\"]]", "[[今:You've gotten tough about competition and what's in it for you]], but [[本:you really fire up for challenges with meaning and romance]]."]}, "ENFP>ESFP": {"karai": "You're known as the fun one, but you overanalyze what all that fun meant and wear yourself out alone.", "name": "Living for Now, Dreaming of Next", "atari": ["[[今:You go all in on the event in front of you]], yet [[本:on the way home you're already planning \"next time, let's do this\"]].", "[[今:Your days are spent hopping between trendy spots]], but [[本:you really want to find places nobody knows yet]]."]}, "ENTP>INTJ": {"karai": "You look like a calm strategist, but you leave openings on purpose because you want someone to argue with you.", "name": "The Contrarian Who Made a Plan", "atari": ["[[今:You crafted a meticulous plan all by yourself]], yet [[本:the moment it's done you think, \"what if we broke it instead?\"]]", "[[今:You seem to be listening quietly in meetings]], but [[本:inside you're poking holes in everyone's points one by one]]."]}, "ENTP>INTP": {"karai": "You claim to be a quiet thinker, but with no one to talk to, you start debating yourself out loud.", "name": "The One Who Keeps Comebacks Inside", "atari": ["[[今:You spend more time thinking alone now]], but [[本:when you come up with a good argument, you're dying to throw it at someone]].", "[[今:You silently watch debates on social media]] while [[本:you've already written three long rebuttals in your head]]."]}, "ENTP>ENTJ": {"karai": "People call you decisive, but your decision is often just the most fun idea you had last night.", "name": "The Trickster in Charge", "atari": ["[[今:You set goals and deadlines and move the team]], but [[本:the most fun is the moment you flip the plan midway]].", "[[今:You run efficient meetings]], yet [[本:when small talk starts derailing things, you're the first to join in instead of stopping it]]."]}, "ENTP>ENTP": {"karai": "You're a fountain of ideas, but when it's time to execute, you've already moved to a different fountain.", "name": "The Inventor Whose Hobby Is Arguing", "atari": ["The second someone says \"that's impossible,\" you've thought of ten reasons to do it.", "Even when you totally agree, you can't resist taking the other side just to start a debate."]}, "ENTP>INFJ": {"karai": "That thoughtful silence? You're working out how to disagree without ruffling any feathers.", "name": "The Debater Who Learned Kindness", "atari": ["[[今:You read people's feelings and choose your words]], while [[本:thinking \"but that doesn't really add up, does it?\"]]", "[[今:You're quietly playing the listener]], yet [[本:when the debate heats up, you can't help leaning in]]."]}, "ENTP>INFP": {"karai": "You call yourself sensitive, but on days you lose an argument, you hold a grudge all night.", "name": "The Debate Champ Posing as a Poet", "atari": ["[[今:You savor your favorite work's world on your own]], and [[本:before you know it you're noting plot holes in a notebook]].", "[[今:You swallow your opinions so you won't hurt anyone]], then [[本:rehearse the perfect comeback in the bath at home]]."]}, "ENTP>ENFJ": {"karai": "You've settled into the nice-person role, but your occasional sharp tongue is the real you.", "name": "The Caring Prankster", "atari": ["[[今:You comfort and encourage juniors with their worries]], but [[本:you really want to say \"have you tried questioning the premise?\"]]", "[[今:You plan everything so everyone can have fun]], while [[本:sneaking in one unexpected twist]]."]}, "ENTP>ENFP": {"karai": "You pass as emotional, but after a tearjerker your review is usually \"Great screenplay.\"", "name": "The Empathetic Hair-Splitter", "atari": ["[[今:You say \"I totally get it!\" to your friend's story]] while [[本:calmly counting its contradictions in the back of your mind]].", "[[今:You look like you're running on excitement]], but [[本:you calculated how fun it'd be with logic before jumping in]]."]}, "ENTP>ISTJ": {"karai": "Under the skin of a serious, steady person, you're always drafting reforms.", "name": "The Honor Student Who Doubts the Manual", "atari": ["[[今:You work strictly by the rules]], but [[本:you're dying to ask \"who decided this rule, anyway?\"]]", "[[今:You've found comfort in following the same steps every day]], but [[本:sometimes you take a different way home for no reason, as a tiny rebellion]]."]}, "ENTP>ISFJ": {"karai": "You seem thoughtful, but you're itching to optimize even the logistics of being thoughtful.", "name": "The Rebel Who Went Quiet", "atari": ["[[今:You quietly take on what you're asked]] while [[本:three easier ways to do it pop into your head]].", "[[今:You keep a low profile to fit in]], but [[本:you really want to be first to say \"okay, but what if\" in meetings]]."]}, "ENTP>ESTJ": {"karai": "You play the rule enforcer, but for rules that don't suit you, you've got sharp excuses ready.", "name": "The Reformer Defending Precedent", "atari": ["[[今:You wrap up meetings with \"let's go with precedent\"]], but [[本:you're the one who most wants to propose breaking it]].", "[[今:You've mastered your task app]], yet [[本:you switch every time a new one comes out]]."]}, "ENTP>ESFJ": {"karai": "You're known as everyone's ally, but inside you're quietly scoring everything everyone says.", "name": "The Sharp Tongue That Reads the Room", "atari": ["[[今:As host you nod along with everyone's opinions, smiling]], while [[本:holding back the most twisted comment in the room]].", "[[今:You shift your opinions to match how people feel]], but [[本:at home you check: \"wait, that logic was off\"]]."]}, "ENTP>ISTP": {"karai": "You look like a quiet craftsman, but the moment you spot something to call out, you suddenly can't stop talking.", "name": "The Logician Who Tests in Silence", "atari": ["[[今:You work with your hands more than you argue now]], but [[本:while you work, you're debating yourself nonstop]].", "[[今:You take machines and tools apart to see how they work]], and [[本:the daydreams of \"I could mod this into something more fun\" never stop]]."]}, "ENTP>ISFP": {"karai": "You seem laid-back, but when you speak, you hit a nerve with the gentlest face.", "name": "The Gentle Cynic", "atari": ["[[今:You enjoy a life of choosing what you love by feel]], but [[本:ask why and you suddenly start explaining with theory]].", "[[今:You keep things calm so you never clash with anyone]], but [[本:just once, you'd love to start a real debate]]."]}, "ENTP>ESTP": {"karai": "You present as a doer, but nobody has ever beaten you at getting bored fast.", "name": "The Debater Who Tests Before Thinking", "atari": ["[[今:You try things before arguing about them now]], but [[本:when it works, you spend thirty minutes explaining why]].", "[[今:You act like you decided on a whim]], but [[本:you actually simulated five possible outcomes in your head]]."]}, "ENTP>ESFP": {"karai": "You pass as happy-go-lucky, but boring talk doesn't even get a polite laugh out of you.", "name": "The Schemer Hiding Behind Fun", "atari": ["[[今:You're goofing around with everyone]], yet [[本:out of nowhere you say \"wouldn't this game be more fun if we changed the rules?\"]]", "[[今:You look like you put fun first]], but [[本:you're coolly reading who to team up with for the most fun]]."]}, "ESTJ>INTJ": {"karai": "Once you realized doing it yourself was faster than delegating, you just stopped relying on anyone.", "name": "The Foreman Who Directs in Silence", "atari": ["[[今:You listen quietly in meetings]], yet [[本:on the way home you're reassigning everyone's roles in your head]].", "[[本:Where you once would've barked the orders]], [[今:now you prepare flawless materials and sit in the back row]]."]}, "ESTJ>INTP": {"karai": "You act like a free spirit, but you still get properly mad at people who show up late.", "name": "The Ex-Organizer Who Tossed the Planner", "atari": ["[[本:You're supposed to be the one who loves a plan]], but [[今:now you start researching \"do we even need this?\" until the sun goes down]].", "[[今:You turn down being the party host]], yet [[本:somehow your restaurant comparison chart is more detailed than anyone's]]."]}, "ESTJ>ENTJ": {"karai": "You love proposing new things, but someone else's new idea first gets \"Has anyone done this before?\"", "name": "Running the Floor and the Vision", "atari": ["[[今:While you talk about big dreams]], [[本:your notes are filling up with dates and names of who's responsible]].", "[[本:Your old self is the most surprised of all]] that [[今:you can now say \"let's do it precisely because it's never been done\"]]."]}, "ESTJ>ENTP": {"karai": "You call yourself a rule-breaker, but when others break the rules you set, you get pretty grumpy.", "name": "The Hall Monitor Itching to Break Rules", "atari": ["[[今:You're the one saying \"okay, but what if\" in meetings]], yet [[本:once it's decided, you track progress more seriously than anyone]].", "[[本:You used to be the one enforcing the rules]], but [[今:now finding a loophole makes you oddly happy]]."]}, "ESTJ>INFJ": {"karai": "You play the gentle listener, but the third time someone brings the same problem, you start taking minutes in your head.", "name": "The Drill Sergeant Who Reads Every Face", "atari": ["[[今:You listen and nod silently to your junior's worries]] while [[本:breaking the fix into three steps in your head]].", "[[本:You're the type who wants things black and white]], but [[今:now you read their face and push the decision to next week]]."]}, "ESTJ>INFP": {"karai": "You cherish your sensitive side, but other people's excuses still get your old strictness.", "name": "The Dreamy Planning Boss", "atari": ["[[今:On weekends you sink into your favorite stories]], but [[本:Monday morning, the planning monster suddenly wakes up]].", "[[本:\"If I say it, I do it\" used to be your creed]], but [[今:now you're practicing forgiving yourself on days you're not feeling it]]."]}, "ESTJ>ENFJ": {"karai": "You're known as caring, but you stop caring for people who won't listen pretty fast.", "name": "The Caretaker Who Presses Gently", "atari": ["[[今:Right after saying \"you okay? don't push yourself\"]], [[本:you double-check their deadline]].", "When your team reports in, you're sometimes surprised that [[今:\"great job\" comes out before the numbers]]."]}, "ESTJ>ENFP": {"karai": "You try hard to seem easygoing, but after the third change of plans, your face goes blank.", "name": "The Manager Pretending to Be Carefree", "atari": ["[[今:You act like the trip was decided on a whim]], but [[本:before leaving, you've sent everyone a packing list and meet-up time]].", "[[本:Holding back your wish to stick to the plan]], [[今:you're trying to enjoy going along with spur-of-the-moment ideas]]."]}, "ESTJ>ISTJ": {"karai": "You act reserved, but when someone runs things sloppily, you redo it all in your head.", "name": "The Team Lead Who Stopped Giving Orders", "atari": ["[[本:You tuck away your urge to lead everyone]], and [[今:now you nail your own part and quietly leave right on time]].", "When no one in the group chat will decide, [[今:you hold out on \"read\"]], and [[本:end up dropping a proposed date in the middle of the night]]."]}, "ESTJ>ISFJ": {"karai": "You look devoted, but you keep devoting yourself until they do things your way.", "name": "The Organizer Who's Great at Saying Yes", "atari": ["[[今:You take on requests with a smile]] while [[本:reworking the plan in your head: \"you could've told me sooner\"]].", "[[本:Where you'd like to say \"this is how it should be done\"]], [[今:now you think of a gentle way to say it three times before speaking]]."]}, "ESTJ>ESTJ": {"karai": "When you say \"Normally, you'd do it this way,\" \"normal\" usually means your own rules. You haven't noticed.", "name": "The Born Schedule Master", "atari": ["The moment someone mentions a trip, you've made a spreadsheet and shared the hotel and meet-up time before anyone else.", "You always do what you say, and you always remember who doesn't. No hidden sides, and proud of it."]}, "ESTJ>ESFJ": {"karai": "You say you value everyone's opinions, but somehow your original idea always wins.", "name": "The Class Rep Who Leads With a Smile", "atari": ["[[本:Before you can say \"that's wrong\"]], [[今:you now physically can't speak without slipping in a \"love that!\" first]].", "[[今:As party host you ask everyone's likes and dislikes]] while [[本:calculating the budget and timing in seconds]]."]}, "ESTJ>ISTP": {"karai": "You act like you go at your own pace, but disrupt that pace and you complain in more detail than anyone.", "name": "The Craftsperson Who Doesn't Make Plans", "atari": ["[[本:You used to plan before you moved]], but [[今:now you just get your hands going before reading the instructions]].", "[[今:On days off you fix things around your room and see no one]], yet [[本:somehow you come up with ways to improve weekday work]]."]}, "ESTJ>ISFP": {"karai": "You act like you don't fuss over things, but you're still strict with anyone who sorts the recycling wrong.", "name": "The Ex-Class President Who Wants Freedom", "atari": ["[[本:You're the type who likes things done properly]], but [[今:now you're trying to choose clothes and work just because you like them]].", "[[今:From the day you decided to take life easy]], [[本:you've somehow been drafting a plan for taking life easy]]."]}, "ESTJ>ESTP": {"karai": "Adaptability is your selling point, but when someone else changes plans on the spot, it's \"Nobody told me.\"", "name": "The One Who Runs Things on the Run", "atari": ["[[今:You've started acting first and thinking later]], yet [[本:you never skip the review session afterward]].", "[[今:Since learning that plans made on the spot often work better]], your planner has a little more white space."]}, "ESTJ>ESFP": {"karai": "You say all that matters is having fun, but when someone plans something un-fun, you critique it for real.", "name": "The Director Who Hypes the Room", "atari": ["[[今:At parties, you're the biggest hype person there]], yet [[本:you've neatly sorted out who's sharing which cab home]].", "[[本:Someone for whom results were everything]] [[今:can now end the day with \"it was fun, so it's fine\"]]."]}, "ESFJ>INTJ": {"karai": "You insist you're not driven by emotion, but if someone forgets your birthday, you hold it against them all day.", "name": "The Host Playing It Cool", "atari": ["[[今:You act like you turned down the invite for logical reasons]], but [[本:you worry about the person you turned down all night]].", "[[今:\"It's faster to do it alone\" is your catchphrase]], yet [[本:you're always the one handing out snacks to the team]]."]}, "ESFJ>INTP": {"karai": "You act detached, but you can't hide how your voice goes up a notch the moment someone needs you.", "name": "The Popular One Hiding Behind Logic", "atari": ["[[本:Before your true wish to be useful to someone kicks in]], [[今:now you find yourself thinking \"what's the point of that?\"]]", "[[今:Even when you're deep in research alone]], [[本:you reply in seconds when a friend messages for advice]]."]}, "ESFJ>ENTJ": {"karai": "You think you're being firm, but when someone disagrees, your first move is \"You're not mad, right?\"", "name": "The Big-Hearted One-Person Show", "atari": ["[[今:After giving tough instructions]], [[本:you can't stop yourself from quietly leaving snacks as a follow-up]].", "[[本:Deep down you want everyone to like you]], but [[今:now you'll play the bad guy if that's what gets results]]."]}, "ESFJ>ENTP": {"karai": "You enjoy playing the debate champ, but when you really win, you send an apology emoji afterward.", "name": "The Host Who Brings the Comebacks", "atari": ["[[今:You stir up the debate with \"okay, but what if\"]], then [[本:the moment the mood cools, you hurry to compliment everyone]].", "[[本:You're supposed to be happy with the usual place and the usual crew]], but [[今:now you're the one saying \"let's try something new\"]]."]}, "ESFJ>INFJ": {"karai": "You play the quiet one, but a group chat buzzing without you still makes you uneasy.", "name": "The Host Who Cares From Afar", "atari": ["[[今:You skip big parties]], yet [[本:you still prepare a little gift for the people who couldn't come]].", "[[本:You're someone who likes being in the middle of everyone]], but [[今:now you watch over everyone's faces from a little distance]]."]}, "ESFJ>INFP": {"karai": "You say you like being alone, but you're always waiting for someone to ask, \"How've you been?\"", "name": "The Caretaker Who Went Indoors", "atari": ["[[今:You sink into story worlds alone at home]], yet [[本:every friend's birthday is in your calendar]].", "[[今:You lie awake alone wondering \"what does being myself even mean?\"]], and [[本:by morning you're back to listening to your friends' worries]]."]}, "ESFJ>ENFJ": {"karai": "You say it's for their sake, but you're happiest when they grow into the ideal you pictured.", "name": "The Host Who Looks After Dreams Too", "atari": ["[[本:You were only supposed to listen to your friend vent]], but [[今:somehow you're planning their future with them]].", "[[本:It used to be enough to see the person in front of you smile]], but [[今:now you can see their whole potential]]."]}, "ESFJ>ENFP": {"karai": "You seem to live freely, but posts with too few likes get quietly deleted at midnight.", "name": "The Party Starter Who Forgot the Plan", "atari": ["[[今:You invite everyone on a whim with \"let's meet up now!\"]] while [[本:quietly checking everyone's last train]].", "[[今:Every time you find a new place]], [[本:you think \"would everyone like this?\" before snapping a photo]]."]}, "ESFJ>ISTJ": {"karai": "You say \"Rules are rules,\" but half those rules are really \"so nobody gets stuck.\"", "name": "The Caring One With a Poker Face", "atari": ["[[今:You seem to just calmly get through your work]], but [[本:you're the first to notice a coworker feeling down]].", "[[今:In meetings you say only what's necessary]], yet [[本:your voice suddenly brightens during break-time chat]]."]}, "ESFJ>ISFJ": {"karai": "You say you don't need to stand out, but when no one notices your thoughtfulness, you sulk a little.", "name": "The Host Who Moved Backstage", "atari": ["[[今:At the after-party you sit in the corner]], but [[本:your eyes never stop checking that no one's glass is empty]].", "[[本:You used to love thanks from a crowd]], but [[今:now one person's words can keep you going for a week]]."]}, "ESFJ>ESTJ": {"karai": "You push through with logic, but the second they look close to tears, you're ready to reverse everything.", "name": "The Host in Business Mode", "atari": ["[[今:After a meeting where you pressed people on the numbers]], [[本:you hold a solo review in the restroom: \"was I too much?\"]]", "[[今:The efficiency-first persona suits you now]], but [[本:even with someone who missed a deadline, you start with \"are you feeling okay?\"]]"]}, "ESFJ>ESFJ": {"karai": "You say it's all for everyone, but when nobody thanks you, it quietly hurts, and you remember it forever.", "name": "The Born Host", "atari": ["The moment someone says \"where should we go?\", you've got three options and their open reservations ready.", "You're great at remembering birthdays and favorite foods, and you start prepping the celebration before the person does."]}, "ESFJ>ISTP": {"karai": "You act uninterested in people, but you know the office relationship map better than anyone.", "name": "The Craftsperson Who Put Away the Charm", "atari": ["[[今:Working quietly alone feels easy now]], yet [[本:when someone's struggling, your hands go to help on their own]].", "[[今:You deliberately set aside days off to talk to no one]], yet [[本:by evening you somehow want to call someone]]."]}, "ESFJ>ISFP": {"karai": "You say you'll go with the flow, but you've already got three possible dates in mind for hanging out.", "name": "The Caring One at Their Own Pace", "atari": ["[[今:You want to live choosing only what you love]], yet [[本:when picking a gift, you research their tastes thoroughly]].", "[[今:You're starting to like the you who can say \"let's go with the mood\"]], but [[本:right after saying it, you feel a little uneasy]]."]}, "ESFJ>ESTP": {"karai": "You think you're breezy, but get left on read and you reopen the chat about three times.", "name": "The Caretaker Who Goes With the Flow", "atari": ["[[今:You jump on invites in the heat of the moment]] while [[本:keeping a side eye out for anyone about to be left behind]].", "[[今:Saying \"let's just go\" feels weirdly good]]. But [[本:once you arrive, you've ordered everyone's drinks first]]."]}, "ESFJ>ESFP": {"karai": "You say you live on vibes, but if the party fell flat, you analyze why the whole way home.", "name": "The Party Captain Who Let Go of the Plan", "atari": ["[[今:You've come to love meeting up on the day's vibe]], yet [[本:you always take photos for the people who couldn't come]].", "[[今:Days you dive into any open place without a reservation are more fun]]. But [[本:you're the first to check there are enough seats for everyone]]."]}, "ENFJ>INTJ": {"karai": "You decided to stop expecting things from people, yet you keep expecting too much and getting let down.", "name": "The Strategist Hiding Their Ideals", "atari": ["[[今:After coldly stating the hard truth]], [[本:you keep telling yourself \"it was for their own good\"]].", "[[本:You're someone who wants to encourage and lead people]], but [[今:now you'd rather craft the perfect plan alone]]."]}, "ENFJ>INTP": {"karai": "You say relationships are a hassle, but maybe you just don't have anyone to fuss over right now.", "name": "The Researcher Hiding Their Fire", "atari": ["[[今:You love time alone mulling over theories]], yet [[本:the moment someone asks for life advice, the heartfelt quotes won't stop]].", "When a friend shares their dream, [[今:\"is there any basis for that?\" comes out before any encouragement]]."]}, "ENFJ>ENTJ": {"karai": "You play the rational leader, but behind the scenes, worrying about everyone's reactions wears you out.", "name": "The Leader Who's a Little Too Fired Up", "atari": ["[[今:You press your team on the numbers]], yet [[本:in one-on-ones you draw out everyone's dreams and remember them all]].", "[[本:You're someone who wants to put feelings first]], but [[今:now you say \"so what's the bottom line?\" before they finish talking]]."]}, "ENFJ>ENTP": {"karai": "You pose as a contrarian, but one \"thank you\" and you're sincere again in seconds.", "name": "The One Who Shows Love Through Debate", "atari": ["[[今:You argue the other side on purpose to liven up the debate]], but [[本:you always wrap it up in a way everyone can accept]].", "[[今:When a junior pitches an idea, you look for holes first]], then [[本:hurry to list five good points after]]."]}, "ENFJ>INFJ": {"karai": "You think you're just watching over them, but you're on edge until they pick the path you had in mind.", "name": "The Cheer Captain Watching Quietly", "atari": ["[[本:Rather than giving a speech to a crowd]], [[今:listening to one person for three hours at a diner feels right these days]].", "[[今:Even when you notice someone struggling, you don't say anything]], but [[本:you set up an atmosphere where they'll find it easy to talk]]."]}, "ENFJ>INFP": {"karai": "You say you'll live true to yourself, but you check how \"you\" you are by other people's reactions.", "name": "The Dreamer on a Break From Caretaking", "atari": ["[[今:You decided to value your own feelings]], yet [[本:your journal ends up being all about other people's]].", "[[今:On a free day you watch a movie alone and cry]], then [[本:genuinely worry about the side characters' futures]]."]}, "ENFJ>ENFJ": {"karai": "You love the version of you who works hard for others so much that a \"no thanks\" hurts you more than them.", "name": "The Born Cheer Captain", "atari": ["You applaud your friends' smallest challenges with your whole heart, and you're close to tears before they are.", "Nobody asked, but you help a junior think through their career, and suddenly you've scheduled a meeting."]}, "ENFJ>ENFP": {"karai": "You look like a free spirit, but you keep glancing back to make sure everyone's keeping up.", "name": "The Caretaker Who Follows the Sparkle", "atari": ["[[今:You start new things on a whim]], and [[本:before long you're looking after the friend who started with you]].", "[[本:You're someone who wants to make a plan and guide everyone]], but [[今:now you change direction on every spark of inspiration]]."]}, "ENFJ>ISTJ": {"karai": "You say you keep emotions out of work, but at farewell parties you're usually the first to cry during the speech.", "name": "The Tidy One Who Put Away the Passion", "atari": ["[[今:You work calmly by the manual]], yet [[本:you secretly keep notes on how the new hires are growing]].", "[[本:You're someone who wants to talk about big ideals]], but [[今:now saying \"let's follow precedent\" feels safer]]."]}, "ENFJ>ISFJ": {"karai": "You think you're quietly supporting, but you have plenty to say about other people's big life decisions.", "name": "The Great Manager Behind the Scenes", "atari": ["[[今:You stepped down from giving pep talks in front of everyone]], yet [[本:you attach a different note for each person to the snacks you bring]].", "[[本:Rather than chasing a big dream together]], [[今:these days you care more about whether the one person in front of you is really smiling]]."]}, "ENFJ>ESTJ": {"karai": "You play the strict boss, but when someone pleads, you end up bending the rules.", "name": "Writing Ideals Into the Schedule", "atari": ["[[本:You're someone who wants to believe in people's potential]], but [[今:now you start with the deadline: \"so when can you have it done?\"]]", "[[今:You manage the team's goals by the numbers]], yet [[本:on the day you hit them, you give everyone a handwritten message]]."]}, "ENFJ>ESFJ": {"karai": "You think you're taking care of everyone, but you're taking away quite a bit of their freedom too.", "name": "The Caretaker Who Lives for Right Now", "atari": ["[[本:Instead of talking about big dreams]], [[今:now you pour everything into picking this week's dinner spot]].", "[[本:Rather than mapping out someone's future with them]], [[今:your days are busy sending \"did you eat today?\" texts]]."]}, "ENFJ>ISTP": {"karai": "You think you live unsentimentally, but feel-good videos make you cry faster than anyone.", "name": "The One Who Packed Love Into a Toolbox", "atari": ["[[今:You've stopped cheering people on with words]], yet [[本:when a friend's bike breaks, you quietly go fix it]].", "[[本:You're someone who wants to light a fire in people's hearts]], but [[今:now you find yourself saying \"either is fine\" more often]]."]}, "ENFJ>ISFP": {"karai": "You say you never meddle, but when someone you love is struggling, you dive in headfirst.", "name": "The Cheer Captain Blooming Solo", "atari": ["[[本:Since stepping down from guiding people]], [[今:you're finally enjoying time spent picking out knickknacks and music you love]].", "[[今:You don't stand in front of crowds anymore]], but [[本:you quietly give handmade things to the people you like]]."]}, "ENFJ>ESTP": {"karai": "You play it light and breezy, but bring you a serious problem and you'll still talk until dawn.", "name": "The One Who Turned Passion Into Action", "atari": ["[[今:Your body moves before any words of encouragement]], and [[本:soon you're carrying all of someone's bags]].", "[[本:You're someone who wants to move people by talking about ideals]], but [[今:now you push through with \"let's just try it\"]]."]}, "ENFJ>ESFP": {"karai": "You laugh and say fun is all that matters, but secretly you're scheming to make everyone's life a little better.", "name": "The Mood-Maker Lighting Up the Room", "atari": ["[[今:You decided to enjoy today without thinking ahead]], yet [[本:on the way home you're worrying about everyone's plans for tomorrow]].", "[[今:You make the whole party laugh]], and [[本:when someone's left out in the corner, you go sit right next to them]]."]}, "ENTJ>INTJ": {"karai": "You stay out of the spotlight not out of humility, but because you can't be bothered to explain.", "name": "The Commander Who Stays Out of Front", "atari": ["[[今:You don't say a word in the meeting]], yet [[本:by the end, it wraps up with the conclusion you prepared]].", "[[今:You say it doesn't matter who decides]], but [[本:on days your idea doesn't win, you rework your strategy on the way home]]."]}, "ENTJ>INTP": {"karai": "You say you'll go with the flow, but anything decided without you always gets a \"Why?\"", "name": "The CEO With a Decision on Hold", "atari": ["[[本:You're someone who wants to reach conclusions fast]], but [[今:now the more you research, the more options pile up and you can't decide]].", "[[今:You're happily toying with hypotheses on your own]], yet [[本:when someone rambles, you suddenly start running the conversation]]."]}, "ENTJ>ENTJ": {"karai": "When you ask \"Any thoughts?\", you're really just counting who agrees with your plan.", "name": "The Born Decision-Maker", "atari": ["When everyone's stuck choosing a lunch spot, you decide in three seconds and have ordered for the whole table.", "Working backward from goals is just normal to you; honestly, a life without a plan makes no sense to you."]}, "ENTJ>ENTP": {"karai": "You think you've become flexible, but to everyone else, you decide just as fast as ever.", "name": "The Leader Who Keeps Going Off Track", "atari": ["[[本:You're supposed to be the one who lands the conclusion]], but [[今:every time you think of something fun, you add another agenda item]].", "[[本:You made a plan to win]], but [[今:you're itching to try another strategy that came to you halfway]]."]}, "ENTJ>INFJ": {"karai": "People think you're gentle, but you quietly cut ties with anyone who doesn't make sense.", "name": "The Commander Who Leads by Sensing", "atari": ["[[今:You listen with care for how they feel]], while [[本:you've already decided where this will land]].", "[[本:You're someone who wants to step up and take command]], but [[今:now you try to lead by helping people realize things themselves]]."]}, "ENTJ>INFP": {"karai": "You say you hate conflict, but years later you still remember every match you lost, in detail.", "name": "The Ex-CEO Who Talks About Dreams", "atari": ["[[今:You tell yourself \"just do what you love\"]], yet [[本:you want to be number one even at what you love]].", "[[今:Even when you're lost in daydreams alone]], [[本:in those daydreams you're firmly leading an organization]]."]}, "ENTJ>ENFJ": {"karai": "You aim to be a leader with heart, but behind every compliment is the next target.", "name": "The Meritocrat Who Speaks From the Heart", "atari": ["[[今:While giving a speech to encourage the team]], [[本:you're already planning the next reshuffle]].", "[[本:You're someone who'd rather win with hard facts]], but [[今:now you choose words that won't kill their motivation]]."]}, "ENTJ>ENFP": {"karai": "You look like you live freely, but the moment you realize you're falling behind, you go full throttle.", "name": "Ambition Wrapped in Sparkle", "atari": ["[[今:Something you started with \"this looks fun, let's do it!\"]] [[本:somehow becomes a business plan six months later]].", "[[今:You say you decided on \"does it excite me?\"]], but [[本:behind the scenes you've calculated your odds of winning]]."]}, "ENTJ>ISTJ": {"karai": "You call yourself steady, but when a promotion opens up, your hand shoots up first.", "name": "The Ambitious One Who Follows Procedure", "atari": ["[[今:You quietly work through the set procedures]] while [[本:thinking \"if it were me, here's how I'd change this department\"]].", "[[本:You're someone who wants to announce huge goals]], but [[今:now you only say what you know you can deliver]]."]}, "ENTJ>ISFJ": {"karai": "You say you're suited to supporting roles, but nobody gets a say in how you support.", "name": "The CEO in an Apron", "atari": ["[[今:You carefully handle the chores you're asked to do]], and [[本:before long you've redesigned the whole system behind them]].", "[[今:You've started asking \"what would you like to do?\" first]], but [[本:you usually prepared the options yourself]]."]}, "ENTJ>ESTJ": {"karai": "You say you've become realistic, but inside you haven't given up on conquering the world.", "name": "The Visionary Who Went Practical", "atari": ["[[本:Instead of talking about dreams ten years out]], [[今:now you're fired up about hitting this month's numbers]].", "When you hear a new idea, [[今:you start a responsibility chart with \"so who's doing it, and when?\"]]."]}, "ENTJ>ESFJ": {"karai": "You say you value the mood in the room, but you never let go of the final say.", "name": "The Commander Who Wants to Be Liked", "atari": ["[[今:You host the party flawlessly]] while [[本:also memorizing a map of everyone's connections]].", "[[今:Every time a meeting drags on hunting for an idea that saves everyone's face]], [[本:you think your old self would've decided in five minutes]]."]}, "ENTJ>ISTP": {"karai": "You pose as a lone wolf, but tell you to build a pack and you'd draw up an org chart overnight.", "name": "The Hands-On Type Who Stopped Commanding", "atari": ["[[本:You're someone who wants to move people toward big results]], but [[今:now you're satisfied with what you can do with your own hands]].", "[[今:You've decided not to butt in]], yet [[本:when someone's working inefficiently, you silently take the tool from them]]."]}, "ENTJ>ISFP": {"karai": "You say you're not interested in competing, but your need to win hasn't faded one bit.", "name": "The Free Spirit With Ambition on Pause", "atari": ["[[今:You meant to enjoy your hobby casually]], but [[本:somehow you've become the one running the hobby group]].", "[[今:You decided not to compare yourself and cut back on social media]], yet [[本:news of a friend's promotion strangely sticks with you]]."]}, "ENTJ>ESTP": {"karai": "You look like you're winging it, but in your mind, it was all part of the plan.", "name": "The General Who Moves Before Planning", "atari": ["[[本:You're someone who wants a long-term strategy before attacking]], but [[今:now you've learned you win more by deciding on the ground]].", "[[今:Even with a game started on a whim]], [[本:before long you've made rules and are keeping score]]."]}, "ENTJ>ESFP": {"karai": "You pretend to live on vibes, but you always go after the spotlight.", "name": "The Ambitious One Who Knows How to Party", "atari": ["[[今:You look like you're having more fun than anyone at the party]], and [[本:by the end, you've been named host of the next event]].", "[[今:You now pick people to work with by \"are they fun to be around?\"]], but [[本:the ones you pick are usually great at the job too]]."]}};
var PS={"INTJ": {"catch": "You already have the answer before the discussion even starts.", "overview": "By the time everyone else starts talking it over, you can already see the shape of the answer in your head. You look at things over the long run, asking “Where is this going?”, and you build a path with little waste. You stay quiet through a meeting, then wrap the whole thing up with one last comment. That probably sounds familiar. You don't say much, but when people come to you for help, your answers are surprisingly on point.", "strengths": ["You plan ahead｜You picture six months or a year from now and act on it. You deal with trouble before it starts, so your plans hold steady.", "You think things all the way through｜You keep at a problem until you reach an answer. You don't get swept along by others. You check for yourself before you decide.", "You spot waste and clean it up｜You're quick to ask, “Do we even need this step?” You rethink how things work and save everyone time and effort."], "pitfalls": ["You skip the explanation｜It's all connected in your head, so you tend to share only the conclusion. Adding one “because…” makes you much easier to follow.", "Other people's detours frustrate you｜You see the waste so clearly that it can make you impatient. It helps to remember that others have their own order of what matters.", "You carry it all yourself｜“It's faster if I just do it,” so you put off asking for help. Try handing off small tasks first. It gives you breathing room."], "relationships": "You're fine without a lot of friends. You may be quiet in the group chat, but when someone asks you for advice one-on-one, you think hard and send back a long, thoughtful reply. Once you trust someone, the friendship runs long and deep. You get along best with people who respect your time alone.", "love": "It takes you a while to fall for someone, but once you decide, you're deeply sincere. You show your feelings less with words and more by talking seriously about the future. On the way home from a date, you might be quietly reviewing “what went well today.” Saying “I had fun” out loud puts the other person much more at ease.", "work": "You do your best where the goal is clear and you're trusted to choose how to get there. People often say, “Ask them and you'll see the way forward.” Rules with no clear reason and meetings that never decide anything wear you out. Block off focus time first, and your results go up.", "jobs": ["Corporate planning / business strategy", "Systems design", "Research", "Data analyst"], "growth": "Your conclusions are usually right. Today, when you share one, try adding a single sentence about why you think so.", "A": "When assertive, once you decide, you go straight for it. Pushback doesn't shake you, and you move your plans forward calmly.", "T": "When cautious, your care in checking your plans for gaps again and again really shines. When you feel anxious, try writing it all down on paper. It helps."}, "INTP": {"catch": "One “But why?” and suddenly it's midnight.", "overview": "When a small question catches your interest, you can end up researching it for hours. You'd rather think until you truly understand why something works than just memorize the answer. You start looking something up in bed, and suddenly it's 2 a.m. You've probably had nights like that. You may seem to move at your own pace, but when people talk with you, you come up with interesting answers from unexpected angles.", "strengths": ["You see how things work｜Even in a complicated topic, you find the key part. You're good at laying out the frame: “So basically, it's this.”", "You don't go along with assumptions｜You don't decide just because “everyone says so.” You check for yourself, so you catch problems others missed.", "You focus deeply on what you love｜You can get completely absorbed in a topic that interests you. Before long, you know more about it than anyone."], "pitfalls": ["You overthink and get stuck｜“There might be a better way” keeps you from deciding. Set yourself a rough deadline, and the first step comes easier.", "Feelings talk is hard for you｜Sometimes you offer a fix when the other person just wants sympathy. Start with “That sounds rough,” and you'll get through.", "Your interest jumps to the next thing｜New questions pull at you, and unfinished projects pile up. Write down just one of them, and it becomes easier to finish."], "relationships": "You enjoy talking deeply about your favorite topics with a few people more than hanging out in a big group. Friends count on you for the “I looked it up for you” knowledge you bring when they're stuck. You click with people who don't mind when you suddenly go quiet to think, and who say, “Ooh, that's interesting.”", "love": "Love starts for you with “I want to know more about this person.” You grow closer the more you talk. You might spend so long deciding how to reply to your crush's text that three days go by. Even a short “Here's what happened today” goes a long way to make them feel secure.", "work": "You do your best where you can think at your own pace and try new things. You tend to shine in roles where you dig into causes or build systems. Repeating the same steps and writing reports that seem pointless wear you out. Once you know why something matters, you can focus amazingly well.", "jobs": ["Programmer", "Researcher", "Data scientist", "Game designer"], "growth": "You don't have to wait until an idea is finished to share it. Today, try telling one person about an idea that's only half done.", "A": "When assertive, you feel free to say your ideas out loud as they come. You don't dwell on mistakes, and you go deeper by trying things out.", "T": "When cautious, you check again and again for anything missing, so your answers get more precise. When you're unsure, share what you know so far."}, "ENTJ": {"catch": "One “Okay, let's do this” from you and things start moving.", "overview": "When everyone is unsure and the talk stalls, you're the one who says, “Okay, let's do this,” and points the way. Once you see the goal, you lay out the steps in one go, bring people together, and make it happen. The group chat stuck on “Where should we go?” gets settled in five minutes once you offer three options. Even when you seem strict, it's because you really want a good result.", "strengths": ["You decide and get things moving｜Even when others hesitate, you set the criteria and make the call. A stalled conversation starts moving again with one comment from you.", "You're great at planning steps｜You break a big goal into what to do today and what to do next week. Everyone knows clearly who does what.", "You enjoy big goals｜The harder the challenge, the more fired up you get. Even things people call “impossible,” you keep working at until you get close."], "pitfalls": ["You expect others to keep your pace｜You tend to assume everyone can move as fast as you. Ask about their situation before you ask for help, and they'll be happier to pitch in.", "You're bad at resting｜You love moving forward, so resting makes you restless. Put rest on your schedule ahead of time, and you can keep going longer.", "Your words land hard｜What you mean as clear can sound harsh. Mention one thing that went well before you point something out, and it'll be easier to hear."], "relationships": "Somehow you always end up planning the trip or organizing the get-together. You're good at being relied on. But sometimes, take time to really listen to the other person, and their trust in you grows even deeper. You get along well with people who give you straight answers, or who get a kick out of your energy.", "love": "You tell the person you like how you feel, straight out. You plan dates perfectly and show your love through action. It's common for you to be listening to their worries and suddenly realize you've offered three ways to fix it. Sometimes, skip the answer and just say, “I see.” It puts them at ease.", "work": "You do great things where the goal is clear and you're given a lot of room. You tend to shine in roles that pull projects together or lead a team. Organizations that take forever to decide, or work where results are hard to see, wear you out. The more results you deliver, the more you're trusted with.", "jobs": ["Business owner / founder", "Project manager", "Consultant", "Sales manager"], "growth": "When you go quiet, the quieter people start to talk. At the end of today's discussion, try asking just once, “Any other thoughts?”", "A": "When assertive, you decide fast and lead people with confidence, even under pressure. When you fail, you bounce back quickly.", "T": "When cautious, you aim high while still noticing small risks. If you start chasing perfection, try counting what you've already done."}, "ENTP": {"catch": "Your go-to phrase is “What if we flip it?” You turn ideas upside down.", "overview": "When everyone thinks “That's just how it is,” you bring in another angle: “What if we flip it and try this?” The more you talk, the more your ideas grow. You start out just chatting, and suddenly it's a plan for a new project. You probably make moments like that a lot. You may seem to love a debate, but you're not out to win. You just want to find a better answer together.", "strengths": ["You switch angles fast｜You come up with many ways to see a problem and many ways to solve it. When things are stuck, you find a new path.", "Your ideas grow as you talk｜In conversation, your ideas keep getting bigger. A passing thought in small talk can turn into a big project.", "You're not easily intimidated｜You can talk to the boss or a total stranger without feeling nervous. You connect people and start something new."], "pitfalls": ["Great at starting, not at finishing｜You tend to get bored in the slow, steady finishing stage. Team up with someone who's good at wrapping things up, and your ideas take shape.", "Debates get too heated｜You're having so much fun that you may not notice the other person is tired. Give them a turn with “What do you think?” and it stays enjoyable.", "You overbook yourself｜You say yes to every fun invite and end up stretched thin. Sleep on it before you reply, and you'll pick what you really want to do."], "relationships": "You slip easily into any group, toss out topics, and liven things up. You're also good at texting a random thought and getting a whole conversation going. You get along with people who enjoy your stories but sometimes push back, too. The more you can enjoy a friendly argument, the longer the friendship lasts.", "love": "You're drawn to people who are fun to talk to and who show you worlds you don't know. You invite them to new places and try to keep your time together exciting. Sometimes a teasing comment you meant as a joke really hurts them. When things get serious, start with a few words that show you care about how they feel.", "work": "You do your best where you can take on new challenges and share ideas freely. You tend to shine in roles that launch projects or find new ways to solve problems. Doing the same task every day, or being tied down by small rules, wears you out. The more things change, the more your quick, light footwork pays off.", "jobs": ["New business / planning roles", "Startup founder", "Marketer", "Advertising planner"], "growth": "You already have plenty of ideas. Today, pick just one thing you thought of and write its “first step” in one line.", "A": "When assertive, you have the boldness to act the moment inspiration hits. Your charm is that you can laugh off a failure and move on.", "T": "When cautious, you add a calm check to your ideas: “Will this really work?” You're also tuned in to how people react, so you know how to put things."}, "INFJ": {"catch": "You notice the small ripples in people's hearts, even when no one says a word.", "overview": "You notice tiny changes: someone's expression, their tone of voice, the pause before a text reply. When a friend says “I'm fine,” you can tell they're not. People often ask you, “How did you know?” Deep down, you hold a quiet ideal of how things could be, and moving toward it gives you a strong sense of purpose. You're gentle and a good listener, but you have a firm core.", "strengths": ["You notice small changes｜You pick up early on the mood in a room or when someone's feeling low. You can quietly reach out before they ask for help.", "You listen with patience｜You don't interrupt, and you take in feelings along with words. People often trust you with things they'd tell no one else.", "You stay true to what matters｜You know clearly what you value. Even when it would be easy to go along, you quietly hold on to what you believe."], "pitfalls": ["You carry other people's feelings｜Because you understand them, you take them on as your own. Drawing a quiet line in your mind, “This is their problem,” makes it a little easier.", "You hold it in until you can't｜You don't want to make waves, so small frustrations pile up. Before they do, try saying lightly, “Something's been on my mind.”", "Your ideals can get too high｜Because your ideals are so clear, the gap with reality can bring you down. Telling yourself “60% is enough for today” helps you keep going."], "relationships": "Even if you don't have many friends, you value bonds that are deep and lasting. In a group, you often end up as the listener, and people say talking to you calms them down. It's not how often you meet that fills you up, but how deep the talk goes when you do. You click with people who don't find silence awkward.", "love": "As you talk, you find yourself thinking, “I really like the way this person thinks,” and your heart starts to move. You notice small changes in them and show love more through actions than words. You often try so hard to read their wishes that you never mention the restaurant you wanted to try. Put a little of “I wish you'd notice” into words, and you'll grow closer.", "work": "You do your best in work that feels meaningful, where you can sense you're helping people. You tend to shine in planning that captures what people really want, in counseling, and in writing. Workplaces that chase only numbers, or that are packed with meetings, drain you. Taking quiet time once a week to look back keeps you in good shape.", "jobs": ["Counselor / advisor", "Editor / writer", "HR / recruiting", "Childcare worker / teacher"], "growth": "People who notice others' feelings often put their own last. Tonight, before bed, jot down one line about something that made you happy today.", "A": "When assertive, you trust your own judgment and act calmly. When it matters, you can say clearly, “Here's what I think.”", "T": "When cautious, you're especially sensitive to other people's pain, and your words become very gentle. If you start worrying too much, tell yourself, “I was considerate enough.”"}, "INFP": {"catch": "There's always a movie playing in your head, just for you.", "overview": "On the train or on a lazy weekend afternoon, “what if” stories start playing in your head on their own. Music, books, and scenery move you easily, and you take time to really savor what you feel. In the ten-minute walk from the station to home, a whole night's worth of story can play out in your mind. You know clearly what you want to protect, and you can't get excited about things that don't fit it. You may be reserved, but once people talk with you, they find a unique sense of beauty and humor.", "strengths": ["You feel things deeply｜Small moments and words touch your heart. You notice beauty and fun that others tend to miss.", "You can stay close to someone's pain｜You can imagine what a hurting person feels as if it were happening to you. You don't judge, so just having you nearby helps people feel safe.", "You express yourself in your own words｜You're good at turning feelings into something real, like writing, art, or music. You can say hard things gently."], "pitfalls": ["You overthink and freeze｜Your imagination runs so far ahead that the first step feels heavy. Start small with “just five minutes,” and you'll warm up to it.", "You keep your true feelings tucked away｜You don't want to hurt anyone, so sometimes you never share your view. Sorting out your feelings in a note first makes it easier to talk.", "You're quick to blame yourself｜When things go wrong, you tend to think, “It's my fault.” Give yourself the same kind words you'd give a friend."], "relationships": "You feel most comfortable talking slowly with a few people you get along with. Once you open up, there's a surprising side of you that can't stop talking about the things you love. You don't like conflict, so you often end up smoothing over tense moments. You click with people who don't rush you and who enjoy the way you see things.", "love": "You long for a special connection where you understand each other deep down. When you fall for someone, you listen to their favorite songs over and over and remember their offhand comments. You might not even be dating yet, but in your head, your future together is already well underway. Putting small feelings into words, one at a time, makes the relationship more solid.", "work": "You really come alive in work that fits your values, where you can feel you're helping someone. You tend to shine in roles that use your sensitivity, like writing, design, or planning. Places tied down by small rules, or workplaces all about quotas, drain your motivation. Finding one thing you love in your work makes it easier to keep going.", "jobs": ["Writer / novelist", "Illustrator / designer", "Psychology / social work", "Video creator"], "growth": "Your imagination really does reach people when you give it shape. Today, write down just one thing you felt in the notes app on your phone.", "A": "When assertive, you trust your own sense of things more easily, and you bounce back fairly fast when you're down. You can say proudly, “This is what I love.”", "T": "When cautious, you feel your emotional ups and downs deeply, and that gives your expression its richness. When you feel anxious, try listing what you've managed to do."}, "ENFJ": {"catch": "You can't help taking care of people before they even ask.", "overview": "When someone's in trouble, you find yourself asking “Want a hand?” before they ask. If someone seems left out of a group, you naturally start talking to them and bring them in. At dinner and drinks, you're checking everyone else's glass before your own. Seeing people grow and smile is your greatest joy, and before you know it, you're the one holding the group together. The flip side is that you don't always notice when you're tired.", "strengths": ["You see the good in people and say it｜You put into words strengths people don't see in themselves. That one comment can give someone confidence.", "You bring everyone together｜You listen to scattered opinions and guide the group toward something everyone can accept. Your team feels united.", "Your words come from the heart｜You speak with warmth and passion, and you can move people. You leave listeners feeling more hopeful."], "pitfalls": ["You put yourself last｜You tend to say yes to one request after another. Put “time for me” on your calendar first, and you'll push yourself less.", "You try too hard to meet expectations｜You don't want to let anyone down, so you overdo it. Saying “I can't” won't break people's trust that easily.", "“It's for their own good” can go too far｜Advice you give with the best intentions can feel heavy. Ask “What would help you?” before you act."], "relationships": "You have lots of friends and often become the bridge between different groups. You remember birthdays and love planning surprises. You get along with people who openly say thank you, and who can handle it when you admit you're struggling. Relationships last longest when you're not only the one supporting, but also get supported.", "love": "When you like someone, you go all out to see them smile. You take their dreams and worries seriously, too. Just seeing that your message hasn't been read can send you rereading it, wondering, “Did I say something wrong?” Sometimes, let yourself be the one who's cared for, and tell them what you'd like.", "work": "You do your best where you work with people and help them grow. You tend to shine as a leader, a mentor, or a go-between, connecting people and getting them moving. Long stretches of solo work, or a tense workplace, drain you. You shine brightest where you can feel the “thank you.”", "jobs": ["Teacher / instructor", "HR / training", "Career advisor", "Public relations"], "growth": "Because you give so much support, please check how much energy you have left, too. Today, try answering just one request with, “Let me check and get back to you.”", "A": "When assertive, you're confident in your views and lead people without hesitation. You can be your full self in front of others.", "T": "When cautious, you pay even closer attention to how each person reacts. If you start worrying about what people think of you, remember the good things you've done."}, "ENFP": {"catch": "You say “That sounds fun!” and you're already on your way.", "overview": "A new café, a place you've never been, an idea no one's tried yet. When you find something that “sounds fun!”, your eyes light up. You want to share your thoughts right away, and one idea after another grows out of casual chats. You open up easily with new people, and before you know it, you've learned everything they love. You may seem lively, but you're actually sensitive to people's feelings and have a delicate side.", "strengths": ["Ideas keep pouring out｜From one topic, you can link up many ideas. Your strength is coming at things from angles no one expects.", "You hit it off with anyone｜Even meeting someone new, you don't put up walls, and you enjoy listening to them. You can be the one who connects people.", "You get others fired up｜The way you talk with such joy naturally pulls people in. You create a feeling of “Maybe I'll give it a try.”"], "pitfalls": ["Your interest keeps jumping｜Things you start often stop halfway. Pick just one thing you want to finish and set a small goal, and it moves forward more easily.", "You overbook yourself｜You can't say no to invites or to things you want to do, so your calendar fills up. Set one “nothing planned” day each week in advance.", "Detailed tasks tire you out｜Repetitive work and paperwork get pushed off. Adding some fun, like playing music or setting a timer, makes it easier."], "relationships": "You have a wide circle of friends and get along with all kinds of people. You'll text “Can we meet up now?” the moment it hits you, so you often end up planning the fun. You click with people who enjoy hearing your ideas, or who give you just the right dose of realism.", "love": "Love often starts for you with “I have so much fun with this person.” When you fall for someone, places you want to go together keep popping into your head, and you enjoy your time with them to the fullest. Rereading the long text you sent on an exciting night and cringing the next morning is a classic. Creating small joys together in everyday life helps it last.", "work": "You do your best where you can try new things and use your ideas and connections. You tend to shine in planning, launching, and getting the word out. Repeating the same steps, or strict micromanagement, deflates your motivation. Share the tasks you're not good at with people who are, and you'll have more time for your strengths.", "jobs": ["Planning / marketing", "Copywriter", "Event / travel planner", "Streamer / content creator"], "growth": "You already have plenty of power to start things. Today, pick just one unfinished thing and work on it for only five minutes.", "A": "When assertive, you turn ideas into action without hesitating. Even when you fail, you switch gears fast: “On to the next!”", "T": "When cautious, there's thoughtful care inside your brightness. If you wear yourself out worrying, recharge by doing something you love on your own."}, "ISTJ": {"catch": "A quiet, reliable pro who keeps promises and follows the steps", "overview": "You do what you've decided, exactly the way you decided, all the way to the end. Your work is ready the day before it's due, and you arrive ten minutes early. You don't show off, but you never cut corners on what you're trusted with. You may seem a bit hard to approach at first, but the longer people know you, the more they say, “If you ask them, it'll be fine.” You do your best when you have time to focus on your own.", "strengths": ["You always keep your word｜You do what you say, and you meet deadlines. Doing things right, little by little, earns you deep trust.", "You catch gaps and slips｜You notice right away when numbers don't add up or a step was skipped. You're the team's safety net, stopping mistakes before they happen.", "You stick with the unglamorous stuff｜You can keep daily records or practice steadily for years. Before you know it, it adds up to something big."], "pitfalls": ["Sudden changes tire you out｜You value good planning, so last-minute changes can throw you off. Keep one “backup plan” from the start, and it gets easier.", "Your feelings don't easily turn into words｜You tend to keep both thanks and complaints to yourself, and people can misread you. Just saying “That really helped” warms the air.", "You tend to carry it all yourself｜You often think doing it yourself is more reliable. Try handing off just part of it, not all of it, and your load gets much lighter."], "relationships": "You care more about relationships that last than about how many friends you have. You're steady: even after years apart, you treat people just the same. Long stretches of noisy gatherings tire you, so you get along best with people you can talk with quietly in a small group, and people who don't rush your pace.", "love": "It takes you a while to fall for someone, but once you decide, you're all in. You show it less with words and more with action, like remembering anniversaries or giving rides. Replying to a text with just “Got it” often gets you asked, “Are you mad?” Adding one line like “I had fun” at the end is enough for your feelings to come through.", "work": "You do your best in places where the rules and roles are clear. You're highly valued in work that needs accuracy, or in roles that reliably finish things on time. Workplaces where plans keep changing, or where you have to improvise with no prep, aren't your thing, so ask for time to gather information in advance.", "jobs": ["Accounting / bookkeeping", "Civil servant (administration)", "Quality control", "IT systems maintenance / operations"], "growth": "Try adding a little “something different” to your steady ways. Taking just one different street on your way home today is enough of a change.", "A": "When assertive, you trust your own way and move ahead without hesitation. When you make a mistake, you don't dwell on it, and you calmly think about the next step.", "T": "When cautious, you double- and triple-check, so you hardly ever make mistakes. Now and then, tell yourself, “This is good enough.”"}, "ISFJ": {"catch": "A caring, behind-the-scenes helper who quietly notices and acts first", "overview": "You notice small changes in people and quietly lend a hand before they ask. If a coworker looks pale, you leave a warm cup of tea on their desk without a word. You keep up that kind of kindness where no one sees. You remember what you've learned and what people like, and you see your role through to the end. Before long, you're “the person we couldn't do without,” the quiet support everything rests on.", "strengths": ["You notice changes in people｜You pick up on small differences right away, like a new haircut or a tone of voice. You can gently check in before they say a thing.", "You remember things｜You remember what people like and what they told you long ago. People are often delighted: “You remembered?”", "You keep supporting, steadily｜You never cut corners, even on work no one notices. Your team runs smoothly and feels safe because of you."], "pitfalls": ["You can't say no to requests｜It's because you really don't want to let anyone down. Instead of answering right away, pause with “Let me check and get back to you.” It helps.", "You don't show when you're tired｜You don't want others to worry, so you hold on until you hit your limit. Saying “I'm a bit tired today” isn't selfish.", "Change makes you uneasy｜Familiar ways feel safe to you. Try just one new thing in a small way, and you'll find it's easier than you thought."], "relationships": "Rather than being at the center of a lively crowd, you take good care of the people close to you. You remember all your friends' birthdays, and you're the first to help when someone's in trouble. Deep trust grows with people who say thank you clearly and who notice your thoughtfulness.", "love": "You show your feelings by taking care of the person you love. You remember their favorite food and make it for them, or check in often about how they're feeling. When asked what you want, you tend to say “Anything's fine,” but secretly you had a place in mind. That's a classic. Now and then, just say it.", "work": "You do your best in roles that support people, or in work where following steps carefully matters. With your careful attention and accuracy, you hold the team up from behind the scenes. You don't cut corners even when results are hard to see, but going unappreciated quietly wears you down. Choose a workplace where thanks gets said, and you'll last.", "jobs": ["Nurse", "Childcare worker", "Medical office staff", "General affairs / HR"], "growth": "Try turning a little of the kindness you give others toward yourself. Today, write one thing you want to do at the very top of your schedule.", "A": "When assertive, you keep your own pace even while supporting others. You know how much you can take on, so you don't overdo it.", "T": "When cautious, you imagine people's feelings so deeply that your care becomes very fine-tuned. Turn that kindness toward yourself, too, and things get much easier."}, "ESTJ": {"catch": "A dependable organizer who lays out the steps and moves everyone forward", "overview": "You're good at sorting things out and moving everyone forward. When a discussion goes in circles, you naturally take charge: “Okay, let's set deadlines and who's doing what.” You stick to what's been decided and expect the same honesty from others. Your direct way of speaking can come across as a bit scary, but when things go wrong, you're the one people rely on most. “If I said it, I'll do it” is your motto.", "strengths": ["You plan fast｜You line up what needs doing and quickly decide who does what. A stuck group suddenly gets moving.", "You have a strong sense of responsibility｜You never give up on what you've taken on. People feel, “If they're on it, we're fine.”", "You make clear calls｜You don't leave things vague. You decide one way or the other. When there's a lot of doubt, you're the one people lean on."], "pitfalls": ["You can sound harsh｜You want to get the right answer across quickly, so your words come out blunt. Just starting with a quick “thank you” changes how it lands.", "You stick to your own way｜It's because you trust what has worked before. Try someone else's way just once, and you might be surprised.", "You're bad at resting｜When you have free time, you fill it with the next task. Write your breaks on your calendar as “plans,” too."], "relationships": "You look out for people, and you naturally become the organizer among friends. You're the type who's already signed up to plan the trip or organize dinner and drinks before anyone asks. You get along with people who keep their promises and who speak their minds, and roundabout hints leave you a little puzzled.", "love": "In love, too, you're sincere and show how much you care through action. You're a dependable partner who picks the perfect restaurant and time for a date. But when they tell you their worries, you jump straight to solutions. That's a classic. Just listening first, with “I see, that sounds hard,” is plenty.", "work": "You do your best in organizations with clear goals and roles. People rely on you to pull the team together and deliver results on time. Meetings that never decide anything and workplaces with fuzzy rules tend to frustrate you, so things go better if you set the process yourself first.", "jobs": ["Sales manager", "Project management", "Store manager", "Banker"], "growth": "Your drive to move things forward works even better when you make time to listen. Today, try listening to someone all the way through without cutting in.", "A": "When assertive, you hesitate little and decide very fast. You stay confident under pressure and lead the people around you.", "T": "When cautious, you check ahead for gaps and risks in the plan. You also pay attention to how people react, so you're trusted as a gentle organizer."}, "ESFJ": {"catch": "A warm organizer who brings people together and works for everyone's smiles", "overview": "You're always checking whether the people around you are having a good time. At gatherings, you talk to anyone who's alone and notice right away when someone's glass is empty. Seeing people happy is what gives you energy, and you treasure events and celebrations. Before you know it, people are saying, “When they're here, everyone comes together.” Making others happy is what recharges you.", "strengths": ["You bring people together｜You're good at stepping in between people and connecting conversations. Even a group of strangers relaxes naturally around you.", "You're thoughtful in small ways｜You notice right away when someone's in a bind or has good news. You speak up at just the right moment.", "You value promises and occasions｜You remember birthdays and anniversaries and celebrate them properly. You carefully nurture your bonds with people."], "pitfalls": ["You worry too much about how people react｜It's because you want so much to make them happy. Remember that a slow reply usually just means they're busy.", "You put yourself last｜While putting others first, your own plans end up at the very bottom. Once a week, schedule something just for you first.", "Criticism hits you hard｜You try so hard that being told no really stings. Thinking of “how I did it” and “what I'm worth” as two separate things makes it easier."], "relationships": "You have lots of friends and are often put in charge of the group chat or of organizing get-togethers. You can't leave someone in trouble alone, so you often become everyone's go-to for advice. You get along with people who show their thanks and enjoy the moment with you, and a cold attitude from someone can bother you for a long time.", "love": "You show love through frequent messages and thoughtful gestures. You're the type who carefully prepares an anniversary surprise. When their reply is slow, you start worrying, “Did I do something?” That's a classic. It's okay to check how they feel with words, so just ask, “How are things lately?”", "work": "You do your best in work where you deal with people and get thanks in return. People rely on you to lift the team's mood and make sure everyone can work comfortably. Cold, purely competitive workplaces tire you out, so choose a place with a culture of helping each other, and you'll last.", "jobs": ["Hotel / hospitality staff", "Teacher", "Wedding planner", "Caregiver"], "growth": "You make the people around you smile, so you can get good at making yourself smile, too. Today, buy a little treat not for anyone else, but just for you.", "A": "When assertive, you don't get pulled around by people's reactions, and you move things along on your own judgment. Your cheerfulness stays steady and helps others feel at ease.", "T": "When cautious, you imagine people's feelings in detail, and your care reaches even further. Knowing that it comes through fine even if it isn't perfect lightens your heart."}, "ISTP": {"catch": "A quiet lover of how things work, whose hands move before the manual opens", "overview": "When you wonder “How does this work?”, you get your hands on it and find out. When a new gadget arrives, you skip the manual, play around with it, and figure it out. You don't say much, but when things go wrong, you calmly get to work and fix the problem fast. You value your own pace and freedom, a hands-on craftsperson who does things your way. Quiet time working alone is how you recharge best.", "strengths": ["You learn by doing｜You get better faster by actually trying than by listening. You pick up tools and machines quickly, too.", "You're strong in a crisis｜Even when something breaks, you don't panic. You find the cause and fix it. When it counts, you're the one people rely on most.", "You don't waste effort｜You do only what's needed, in the fewest steps. You're good at finding what can be cut."], "pitfalls": ["You skip too much of the explanation｜You already understand it, so you tend to skip the middle part. Add a quick “why I did it” along with the result, and people will feel at ease.", "Talking about feelings is hard for you｜When things get emotional, you're not sure how to respond. Even if you can't find the words, a nod and “I'm listening” says plenty.", "Planning ahead is tough｜You like to decide in the moment. For the deadlines that matter, put them in your phone's reminders ahead of time."], "relationships": "You'd rather keep a few close friends, loosely and for a long time, than a wide circle of casual ones. Clingy relationships aren't for you, and you're most comfortable with people you can be together with while each doing your own thing. You don't say much, but you quietly lend a hand when someone's stuck, so trust in you grows little by little.", "love": "You're not great at putting your feelings into words, but they show in what you do. You fix their bike, or grab their heavy bag without a word. They say, “You never say you love me,” and you think, “But I fixed your bike.” That's a classic. Now and then, put it into words, even briefly.", "work": "You do your best in work where you solve problems with your own hands and head. People rely on you when you're in charge of troubleshooting with machines, tools, or data. Workplaces with lots of small rules and long meetings tire you out, so choose a place that gives you a lot of freedom, and things get easier.", "jobs": ["Mechanical / facilities engineer", "Mechanic", "IT systems maintenance / infrastructure", "Video editor / sound technician"], "growth": "Your “You'll know once you try it” is a big strength. Today, try explaining something you did to someone, in just one sentence.", "A": "When assertive, you hesitate little in your judgment and act as soon as an idea hits. Even when you fail, you switch gears fast: “Next time, I'll do it this way.”", "T": "When cautious, you carefully check the details before you move. Your craftsperson side, picky about the quality of the finish, really shines."}, "ISFP": {"catch": "Someone who quietly follows where the heart says “I love this”", "overview": "You're a gentle, sensitive soul who treasures what you love. Even on your usual way home, a beautiful sunset makes you stop and take a photo. Rather than speaking up, you show who you are through what you wear and what you make. You don't like clashing with people, but you have a quiet strength that won't give in on what matters. Just being surrounded by things you love gives you energy.", "strengths": ["You have a rich sense of beauty｜You're sensitive to differences in color, sound, and taste. You're good at making your surroundings feel cozy.", "You stay close to others｜You don't blame people, and you have the kindness to accept them as they are. People say they feel relaxed around you.", "You throw yourself into what you love｜When something moves you, you lose track of time. That focus turns into careful, beautiful work."], "pitfalls": ["You tend to bottle up feelings｜You want to avoid conflict, so you laugh off even things that bother you. Saying “That kind of bothered me” while it's still small keeps things from getting tangled.", "Planning ahead is hard for you｜It's because you value how you feel right now. Write just one to-do on paper and stick it somewhere you'll see it.", "You take criticism to heart｜What you make feels close to who you are, so criticism stings. Hearing “feedback on my work” and “feedback on me” separately makes it easier."], "relationships": "You'd rather spend quiet time with people you get along with than go to big, noisy gatherings. You don't badmouth people and you're gentle with everyone, so people naturally feel safe around you. You form deep bonds with people who respect your pace and enjoy hearing about the things you love.", "love": "When you fall for someone, you show it with small, thoughtful gestures and handmade things. Secretly listening to every song they said they liked is a classic. It takes you time to say how you feel, so you get along with someone who pays attention to your actions more than your words.", "work": "You do your best in work that uses your sensitivity and skilled hands. You're valued in places where you care carefully for people, animals, or the things you make. Workplaces with number quotas or fierce competition tire you out, so choose a place where you can raise the quality at your own pace, and you'll last.", "jobs": ["Designer", "Hairstylist / nail artist", "Pastry chef / cook", "Veterinary nurse / pet groomer"], "growth": "What you feel reaches people even more when you put it into words. Today, save one thing that moved you, in a short note or a photo.", "A": "When assertive, you trust your senses and act on them directly. You don't worry much about what others think, and you throw yourself into what you love with confidence.", "T": "When cautious, you're very sensitive to other people's feelings and show fine-tuned care. Your care in reworking things again and again adds to your deep charm."}, "ESTP": {"catch": "Someone who steps forward before thinking and catches the flow of the moment", "overview": "You're a doer: your body moves before your mind does. When a meeting stalls, you're the first to raise your hand: “Let's just try it.” You're good at reading the room, and when trouble comes up, you think on your feet and get through it. You're fun to talk to and hit it off with people wherever you go, so before you know it, you're in the middle of the crowd. Sitting still for too long makes you itchy.", "strengths": ["You act fast｜Instead of hesitating, you think while you move. You don't miss chances, and you're the first to get results.", "You think on your feet｜Even when something unexpected happens, you make the best move right there. The tougher the spot, the more people can count on you.", "You draw people in｜You're a good talker and hit it off with new people right away. You liven up any room."], "pitfalls": ["You tend to jump in too soon｜You think as you go. For the things that matter, picture one “worst case” before you start, and you'll feel safer.", "Repetition bores you｜Without some excitement, your focus fades. For dull tasks, set a time limit and treat it like a game, and you'll get it done.", "Your words can be too blunt｜You say what you think right away. Just taking one breath before you speak softens how people take it."], "relationships": "You have lots of friends, and most plans to hang out start with you. Stiff, formal relationships aren't your thing, and you feel at home with people you can joke around with easily. You get along with people who are up for anything and move with you, and relationships bound by lots of little rules make you feel stifled.", "love": "When you like someone, you act on it right away and keep asking them out. You're a fun partner who never lets things get boring. But when they bring up the future, you change the subject. That's a classic. When it's an important talk, pause for a moment and face it, and their trust in you grows a lot.", "work": "You do your best in work with lots of change and quick, visible results. People rely on you in sales or hands-on roles where you get results by moving with people. Desk-bound work and rule-heavy workplaces tend to bore you, so choose a place where you have the freedom to act on your own.", "jobs": ["Sales", "Event planner", "Sports trainer", "Shop owner"], "growth": "Your drive to act gets even stronger with a little looking back. At the end of today, try recalling just one thing that went well.", "A": "When assertive, you're full of confidence and act without hesitating. You jump right into new places and naturally end up as the leader.", "T": "When cautious, along with your drive, you have the calm to watch how people react. You look back after you act and use what you learned for the next challenge."}, "ESFP": {"catch": "Someone who makes right now more fun for everyone around", "overview": "You enjoy the present moment to the fullest and spread that fun to everyone around you. When fun plans come up, you've replied “I'm in!” before you even think. Your face is so expressive that just talking with you brightens the room. When someone's down, you casually make them laugh and cheer them up, so people naturally gather around you as “the one who's fun to be with.” Seeing people happy is your best reward.", "strengths": ["You brighten the room｜With your smile and reactions, you ease even tense moments. You naturally create a mood where people feel free to talk.", "You quickly pick up on feelings｜You sense right away whether someone's having fun or getting tired. You can check in with them on the spot.", "You fit in fast｜A new school, a new team, a trip: you warm up to people in no time. You connect with strangers and keep widening your circle."], "pitfalls": ["You overbook yourself｜It's because you want to say yes to every fun invite. Set one “do nothing” day each week in advance so tiredness doesn't pile up.", "Money and time slip away｜You tend to put the fun of the moment first. Make it a rule to “sleep on it” before buying, and only what you really want will remain.", "You tend to avoid heavy talks｜It's because you want to keep things upbeat. For important talks, set aside a short time separate from fun time, and they'll be easier to face."], "relationships": "You have lots of friends and you're the one keeping the group chat lively. You're good at connecting people, and you notice small changes in others and ask, “How are things lately?” You get along with people who enjoy your brightness but can also sit down and listen calmly sometimes.", "love": "When you like someone, it shows right away. When you want to see them, you just reach out, and on dates you delight them with surprises. But when they ask “What about the future?”, you suddenly change the subject. That's a classic. Taking time now and then to think seriously builds a lot more trust.", "work": "You do your best in work where you deal with people and get reactions right away. In customer service or events, your brightness and thoughtfulness are valued, and you're treasured for lifting the team's mood. Working alone at a screen all day tires you out, so choose a place where you can see people smile.", "jobs": ["Customer service / sales staff", "Tour guide", "Event staff", "Childcare worker"], "growth": "Your brightness lasts even longer with a little looking ahead. Today, write down one “plan you're excited about” and one “thing you need to do.”", "A": "When assertive, you can show your charm freely. You don't worry too much about what others think, and you can enjoy being yourself in front of people.", "T": "When cautious, there's fine-tuned care for others inside your brightness. You think hard about how people feel, so you build deep, trusting relationships."}};
var HN={"type": {"ISTJ": {"want": "The satisfaction of seeing things through, and the security of being trusted", "effort": "Following rules and steps, and building up without mistakes", "work": "Work with clear rules and steps, where accuracy is valued", "jobs": ["Accounting & admin", "Quality control", "Public service", "Systems operations"]}, "ISFJ": {"want": "Feeling useful to others, and a place where you feel safe", "effort": "Thinking ahead, paying attention, and supporting those around you", "work": "Work where you support people close to you and get thanked directly", "jobs": ["Nursing & caregiving", "Childcare", "General affairs", "Medical admin"]}, "INFJ": {"want": "A sense of being part of something meaningful, and relationships where you truly understand each other", "effort": "Reading people's feelings and picking up on what goes unsaid", "work": "Work where you can be part of people's growth and inner lives for the long run", "jobs": ["Counselor", "Education & training", "Editor & writer", "Human resources"]}, "INTJ": {"want": "The satisfaction of moving things with a plan you made, and time alone to think deeply", "effort": "Looking ahead, laying out the logic, and showing the shortest route", "work": "Work where you're trusted with long-term strategy and building systems", "jobs": ["Planning & strategy", "Research", "Engineer", "Consultant"]}, "ISTP": {"want": "The freedom to solve problems with your own hands and head, and time without interference", "effort": "Fixing problems calmly and quickly when they come up", "work": "Work where the results of your hands-on effort are plain to see", "jobs": ["Technician & maintenance", "Engineer", "Craftsperson", "Hands-on specialist"]}, "ISFP": {"want": "Being honest about what you love, and calm relationships", "effort": "Keeping the peace and softening the mood with your own sense of things", "work": "Work where you can use your sensitivity and go at your own pace", "jobs": ["Design", "Beauty", "Making things", "Work with animals or nature"]}, "INFP": {"want": "Being able to honor your values, and a purpose you truly care about", "effort": "Staying close to people's feelings and putting ideals into words or form", "work": "Work where you can express what you believe in", "jobs": ["Writing & creative work", "Social welfare", "Counseling", "Social-impact work"]}, "INTP": {"want": "The freedom to think things through as deeply as you like, and intellectual stimulation", "effort": "Analyzing how things work, then finding and fixing contradictions", "work": "A place where thinking itself is the job", "jobs": ["Research & development", "Programmer", "Data analysis", "Specialist roles"]}, "ESTP": {"want": "The thrill of moving and seeing results right away, and competing in the moment", "effort": "Acting without hesitation and grabbing the chance in front of you", "work": "Work where speed and action turn straight into results", "jobs": ["Sales", "Events", "Sports", "Starting a business"]}, "ESFP": {"want": "Sharing fun with people, and savoring the moment", "effort": "Brightening the room and making everyone have a good time", "work": "Work where you deal with people directly and see them smile", "jobs": ["Customer service & retail", "Entertainment", "Childcare", "Beauty"]}, "ENFP": {"want": "Exciting possibilities, and the joy of connecting with people", "effort": "Coming up with ideas and getting people on board to start something new", "work": "Work full of new projects and new people", "jobs": ["Planning & PR", "Marketing", "Education", "Creative work"]}, "ENTP": {"want": "The freedom to try new ideas, and smart debates", "effort": "Questioning the usual and finding a breakthrough from another angle", "work": "Work with lots of change, where ideas win", "jobs": ["New ventures", "Consultant", "Planning", "Starting a business"]}, "ESTJ": {"want": "The satisfaction of organizing things and moving them forward, and a role with responsibility", "effort": "Setting up the plan, bringing people together, and getting results", "work": "Work where you run an organization and see results in numbers", "jobs": ["Management", "Project management", "Sales manager", "Public administration"]}, "ESFJ": {"want": "A place where everyone gets along, and the joy of being thanked", "effort": "Connecting people and keeping things in harmony", "work": "Work where you engage with your team or community and can be the one who pulls it together", "jobs": ["HR & general affairs", "Education", "Healthcare & welfare", "Customer service lead"]}, "ENFJ": {"want": "Bringing out people's potential, and relationships built on trust", "effort": "Encouraging people and uniting the team toward a goal", "work": "Work where you grow and guide people", "jobs": ["Teacher & instructor", "HR & training", "Coach", "PR"]}, "ENTJ": {"want": "Moving people and things toward a big goal, and the freedom to make the call", "effort": "Making decisions, moving people efficiently, and getting results", "work": "Work where you have decision-making power and can aim for big results", "jobs": ["Executive & management", "Consultant", "Starting a business", "Project leader"]}}, "gap": {"IE": {"axis": "Energy", "from": "Introverted", "to": "Extraverted", "worry": ["Time with people is fun, but you're drained on the way home", "You can't say no to invitations and your schedule fills up", "People see you as cheerful, so no one notices when you're tired"], "work": "Work with both a people-facing role and time to go deep alone. Listening to people, then taking it home and shaping it carefully (counseling, editing, research).", "key": "After a day with people, take the same amount of time doing nothing. Connecting with people is your strength, but you only recharge alone.", "both": "You have both the strength to think deeply on your own (I) and the strength to move with people (E). You can act naturally in front of others, yet you can only recharge in time alone."}, "EI": {"axis": "Energy", "from": "Extraverted", "to": "Introverted", "worry": ["You want to see people, yet plans on the calendar start to feel heavy", "After a stretch of time alone, your mood sinks for no clear reason", "After a gathering you enjoyed, exhaustion suddenly hits"], "work": "Work with both time with people and time to focus alone suits you. Shaping ideas carefully and then delivering them to people, or working in a small team.", "key": "Put both \"people days\" and \"alone days\" on your calendar in advance. When only one keeps going, the other strength starts to fade.", "both": "You have both the strength to recharge through people (E) and the strength to think deeply on your own (I). Lively time and quiet time are both things you need. When either runs low, you tire easily."}, "SN": {"axis": "How you see things", "from": "Realistic", "to": "Intuitive", "worry": ["Plenty of ideas come to you, but none of them take shape", "After talking big, you suddenly worry, \"Can I really do this?\"", "The gap between ideal and reality often lets you down"], "work": "Work where you think up new things and then make them real with your own hands. Building products or services, planning improvements, crafting.", "key": "Rewrite each idea as \"one step I can take tomorrow.\" Using both imagining and checking turns ideas into reality.", "both": "You have both the strength to check the facts in front of you (S) and the strength to imagine possibilities not yet visible (N). You can expand ideas, yet you can't settle until the ground under your feet is firm."}, "NS": {"axis": "How you see things", "from": "Intuitive", "to": "Realistic", "worry": ["You get everything done properly, yet something feels unfulfilled", "Repeating the same method slowly gets boring", "When asked what you really want to do, you can't answer well"], "work": "Steady work that still leaves room to invent new ways. Planning roles that know the front line, teaching, or being trusted with improvements.", "key": "Once a week, make time to think \"if I could do anything...\" Adding imagination to your steady progress changes how your days feel.", "both": "You have both the strength to imagine possibilities (N) and the strength to build on facts (S). You can move things forward realistically, yet without time to think \"what's next?\", days can feel flat."}, "TF": {"axis": "How you decide", "from": "Thinking", "to": "Feeling", "worry": ["After agreeing to go along, you realize you actually disagreed", "You have something to say, but swallow it for fear of spoiling the mood", "You help others so much that your own matters get pushed back"], "work": "Work that asks you to support people and also make sound judgments. Counseling and support roles, HR, healthcare or education, team coordinator.", "key": "Being kind and giving your opinion can go together. Try saying it in this order: \"I understand how you feel. And here's what I think.\"", "both": "You have both the strength to reason step by step (T) and the strength to sense people's feelings (F). You can stay gently by someone's side, yet inside you're calmly asking, \"Is that really right?\""}, "FT": {"axis": "How you decide", "from": "Feeling", "to": "Thinking", "worry": ["You know the right answer, yet it takes you a long time to decide", "After giving your opinion, you keep wondering, \"Was I too harsh?\"", "Sometimes you lose track of what you really want to value"], "work": "Work where both logical thinking and understanding feelings come alive. Planning, marketing, editing, people-centered consulting.", "key": "Hesitating is a sign you hold both strengths. Just write down \"What does my heart say?\" and \"What does logic say?\" separately, and what you're torn about becomes clear.", "both": "You have both the strength to sense people's feelings (F) and the strength to reason step by step (T). You see what people with only one can't, but you also tend to get two answers inside: \"my heart says this, logic says that.\""}, "JP": {"axis": "How you act", "from": "Planning", "to": "Flexible", "worry": ["Even when you look fine, an undecided plan keeps nagging at you", "After putting things off, you blame yourself", "You're free to move as you like, yet somehow it wears you out"], "work": "Work where the big frame is set, but you can design how to get there. Project management, on-site coordination, event operations.", "key": "You don't have to decide everything. Just pick three \"things I'll do this week.\" Keep your flexibility, and simply having a view ahead will lighten you.", "both": "You have both the strength to plan ahead (J) and the strength to flex in the moment (P). You can adapt to the unexpected, yet somewhere inside you can't settle without a view of what's ahead."}, "PJ": {"axis": "How you act", "from": "Flexible", "to": "Planning", "worry": ["Things are going to plan, yet somehow it isn't fun", "Sudden changes irritate you, even when you understand why", "\"I have to do this properly\" has become your catchphrase"], "work": "Work with both moments to follow the plan and moments that need on-the-spot judgment. Sales, planning, front-line management, customer service.", "key": "Leave some time in your schedule with nothing planned, on purpose. Adding the joy of the moment to your planning makes it easier to keep going.", "both": "You have both the strength to flex in the moment (P) and the strength to plan ahead (J). You can organize things well, yet days packed with plans can start to feel suffocating."}, "AT": {"axis": "Mindset", "from": "Assertive", "to": "Cautious", "worry": ["You're doing well, yet you still feel \"it's not enough\"", "Worrying about what others think keeps you from bold steps", "You dwell on small mistakes longer than you need to"], "work": "Work that needs both caution and decisiveness. Quality or risk management, healthcare, right hand to a leader.", "key": "At the end of each day, write down three things you did today. Your care is a strength. Add a moment to remember the confidence you started with.", "both": "You have both the strength to trust yourself and move forward (A) and the strength to check carefully (T). You act with care, yet sometimes you don't show the confidence you were born with."}, "TA": {"axis": "Mindset", "from": "Cautious", "to": "Assertive", "worry": ["You look confident, so you can't share your worries with anyone", "After deciding, you go over it again and again on your own", "The more people rely on you, the harder it is to admit you're struggling"], "work": "Work with both a deciding role and a careful-checking role. Team leader, specialist, head of planning.", "key": "Tell just one person you trust, \"Honestly, I'm a little worried.\" Being careful isn't weakness. It's what makes your judgment solid.", "both": "You have both the strength to check carefully (T) and the strength to trust yourself and move forward (A). You can decide without hesitating, yet inside you're quietly asking, \"Is this really okay?\""}}, "same": {"both": "Your temperament and character are the same type. You've been able to live as the person you were born as, without forcing anything. What people see is what you are, so others find you easy to read and reassuring. A clear sense of self that doesn't waver is your strength.", "worry": ["Places where your way doesn't fit cause you strong stress", "The thinking of people unlike you can be hard to understand", "The cause of your worries is often your surroundings or relationships, not you"], "key": "When something doesn't fit, changing your place or your distance from people tends to work better than changing yourself.", "work": "If the way you work now feels right, that's your answer. When in doubt, trust your own sense."}, "letter": {"E": "Gets energy from being with people", "I": "Gets energy from time alone", "S": "Relies on facts and experience", "N": "Relies on hunches and possibilities", "T": "Decides by reasoning things through", "F": "Decides by what feels right for people", "J": "Moves ahead with a clear plan", "P": "Adapts flexibly to the situation", "AT_A": "Moves ahead trusting their own judgment", "AT_T": "Watches carefully and moves with caution"}};
var TD={"themes": {"比肩": {"who": "born", "title": "A day your true colors shine", "lines": ["Today your \"born {B}\" side is at its strongest. Go at your own pace instead of matching others.", "Today your \"I just feel it's this way\" beats other people's opinions.", "No need to put on an act today. People find the real you the easiest to talk to."], "tip": "If it's yours to decide, decide it yourself"}, "劫財": {"who": "born", "title": "A day your competitive side shows", "lines": ["You might feel like competing today. Use that drive to beat your own record, not someone else.", "If comparing yourself to someone stings, that's your born fighting spirit. It's not a bad thing.", "Today you may not want to give an inch. Hold firm only on what matters, and let the rest go with a smile."], "tip": "When you want to compare, compare with yesterday's you"}, "食神": {"who": "born", "title": "The more you enjoy, the luckier you get", "lines": ["Today it's okay to relax. Eat something delicious and your born self will perk up.", "Today, having fun works better than trying hard. Add one little treat to your plans.", "Today, just being there puts everyone at ease. Reach out to someone you get along with."], "tip": "Just for today, have the treat first"}, "傷官": {"who": "born", "title": "A day your senses are sharp", "lines": ["Your intuition is sharp today. But so are your words. Take a breath before you speak.", "Today you'll easily notice when something feels off. You're probably right. Just say it gently.", "Your sense of style shines today. In clothes or in writing, the care you put in will come through."], "tip": "Read it over once before you hit send"}, "偏財": {"who": "now", "title": "A day your circle grows", "lines": ["Today \"you now\" gets to shine. If someone invites you, just go with it.", "Detours pay off today. Try a different road or a different shop.", "Spending time with people is fun today. Send a quick note to someone you haven't talked to in a while."], "tip": "When invited, start by saying \"Sounds good\""}, "正財": {"who": "now", "title": "A day steady effort pays off", "lines": ["Today \"you now\" gets rewarded for being diligent. The plainer the task, the more it pays off later.", "A good day to get your money and time in order. Take a quick look at your receipts or schedule.", "Today people trust you for keeping your word. The smaller the promise, the more it matters."], "tip": "Take care of one small errand you've been putting off"}, "偏官": {"who": "now", "title": "A day you handle surprises well", "lines": ["Today might get hectic. But \"you now\" is at your best on days like this.", "A sudden request may come your way. You don't have to take it all on. Just the one that matters most.", "Your drive is up today. If you've been on the fence about something, take just one step forward."], "tip": "When in doubt, give it just 5 minutes"}, "正官": {"who": "now", "title": "A day your diligence gets noticed", "lines": ["Today, the skills \"you now\" worked hard for get the recognition they deserve.", "The more you follow the rules and the plan, the better today goes. Move 5 minutes earlier than usual.", "Someone will rely on you today. Once you've come through for them, give yourself some praise on the way home."], "tip": "Move 5 minutes earlier than usual"}, "偏印": {"who": "born", "title": "A day ideas come to you", "lines": ["Today your born flashes of inspiration are sharp. Jot down whatever comes to mind.", "Time alone recharges you most today. Don't pack your schedule too tight.", "Today you'll think differently from others. It's probably interesting, so share it with someone later."], "tip": "Save your ideas in your phone's notes"}, "印綬": {"who": "now", "title": "A day of learning and helping hands", "lines": ["Today people will help \"you now.\" Don't carry it all alone; it's okay to lean on others.", "New things sink in easily today. That book or video you've been curious about? Today's the day.", "Today there's a hint in what a mentor or family member says. Try asking them."], "tip": "Ask someone about one thing you don't understand"}}, "power": {"high": {"label": "Power: high", "stars": 3, "add": "Your energy is full. Do what you want to do today, today."}, "mid": {"label": "Power: medium", "stars": 2, "add": "Your energy is moderate. Your usual pace is just right today."}, "low": {"label": "Power: low", "stars": 1, "add": "Your energy is in power-saving mode. Going to bed early is today's best luck boost."}}};
